window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["EZR"]={"book":"EZR","editions":{"hbo-source":[[1,1,"וּ⁠בִ⁠שְׁנַ֣ת אַחַ֗ת לְ⁠כ֨וֹרֶשׁ֙ מֶ֣לֶךְ פָּרַ֔ס לִ⁠כְל֥וֹת דְּבַר־יְהוָ֖ה מִ⁠פִּ֣י יִרְמְיָ֑ה הֵעִ֣יר יְהוָ֗ה אֶת־ר֨וּחַ֙ כֹּ֣רֶשׁ מֶֽלֶךְ־פָּרַ֔ס וַ⁠יַּֽעֲבֶר־קוֹל֙ בְּ⁠כָל־מַלְכוּת֔⁠וֹ וְ⁠גַם־בְּ⁠מִכְתָּ֖ב לֵ⁠אמֹֽר׃","ẇ⁠bi⁠şĕ̌na֣ţ ʼaẖa֗ţ lĕ⁠k֨wòreş̌֙ me֣lekĕ pá̇ra֔s li⁠kĕl֥wòţ dĕ̇bar-yĕhwá֖h mi⁠pi֣̇y yirĕmĕyá֑h héʻi֣yr yĕhwá֗h ʼeţ-r֨ẇẖa֙ kò֣̇reş̌ meֽlekĕ-pá̇ra֔s wa⁠yȧֽʻàber-qwòl֙ bĕ̇⁠kál-malĕkẇţ֔⁠wò wĕ⁠gam-bĕ̇⁠mikĕţá֖̇b lé⁠ʼmòֽr׃"],[1,2,"כֹּ֣ה אָמַ֗ר כֹּ֚רֶשׁ מֶ֣לֶךְ פָּרַ֔ס כֹּ֚ל מַמְלְכ֣וֹת הָ⁠אָ֔רֶץ נָ֣תַן לִ֔⁠י יְהוָ֖ה אֱלֹהֵ֣י הַ⁠שָּׁמָ֑יִם וְ⁠הֽוּא־פָקַ֤ד עָלַ⁠י֙ לִ⁠בְנֽוֹת־ל֣⁠וֹ בַ֔יִת בִּ⁠ירוּשָׁלִַ֖ם אֲשֶׁ֥ר בִּֽ⁠יהוּדָֽה׃","kò֣̇h ʼáma֗r kò֚̇reş̌ me֣lekĕ pá̇ra֔s kò֚̇l mamĕlĕk֣wòţ há⁠ʼá֔reẕ ná֣ţan li֔⁠y yĕhwá֖h ʼèlòhé֣y ha⁠şá̇̌má֑yim wĕ⁠hֽẇʼ-páqa֤d ʻála⁠y֙ li⁠bĕnֽwòţ-l֣⁠wò ba֔yiţ bi̇⁠yrẇşá̌lia֖m ʼàşě֥r biֽ̇⁠yhẇdáֽh׃"],[1,3,"מִֽי־בָ⁠כֶ֣ם מִ⁠כָּל־עַמּ֗⁠וֹ יְהִ֤י אֱלֹהָי⁠ו֙ עִמּ֔⁠וֹ וְ⁠יַ֕עַל לִ⁠ירוּשָׁלִַ֖ם אֲשֶׁ֣ר בִּ⁠יהוּדָ֑ה וְ⁠יִ֗בֶן אֶת־בֵּ֤ית יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל ה֥וּא הָ⁠אֱלֹהִ֖ים אֲשֶׁ֥ר בִּ⁠ירוּשָׁלִָֽם׃","miֽy-bá⁠ke֣m mi⁠ká̇l-ʻaṁ֗⁠wò yĕhi֤y ʼèlòháy⁠w֙ ʻiṁ֔⁠wò wĕ⁠ya֕ʻal li⁠yrẇşá̌lia֖m ʼàşě֣r bi̇⁠yhẇdá֑h wĕ⁠yi֗ben ʼeţ-bé֤̇yţ yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l h֥ẇʼ há⁠ʼèlòhi֖ym ʼàşě֥r bi̇⁠yrẇşá̌liáֽm׃"],[1,4,"וְ⁠כָל־הַ⁠נִּשְׁאָ֗ר מִֽ⁠כָּל־הַ⁠מְּקֹמוֹת֮ אֲשֶׁ֣ר ה֣וּא גָֽר־שָׁם֒ יְנַשְּׂא֨וּ⁠הוּ֙ אַנְשֵׁ֣י מְקֹמ֔⁠וֹ בְּ⁠כֶ֥סֶף וּ⁠בְ⁠זָהָ֖ב וּ⁠בִ⁠רְכ֣וּשׁ וּ⁠בִ⁠בְהֵמָ֑ה עִם־הַ֨⁠נְּדָבָ֔ה לְ⁠בֵ֥ית הָ⁠אֱלֹהִ֖ים אֲשֶׁ֥ר בִּ⁠ירוּשָׁלִָֽם׃","wĕ⁠kál-ha⁠ni̇şĕ̌ʼá֗r miֽ⁠ká̇l-ha⁠mĕ̇qòmwòţ֮ ʼàşě֣r h֣ẇʼ gáֽr-şá̌m֒ yĕnaşĕ̇̂ʼ֨ẇ⁠hẇ֙ ʼanĕşé֣̌y mĕqòm֔⁠wò bĕ̇⁠ke֥sep ẇ⁠bĕ⁠záhá֖b ẇ⁠bi⁠rĕk֣ẇş̌ ẇ⁠bi⁠bĕhémá֑h ʻim-ha֨⁠nĕ̇dábá֔h lĕ⁠bé֥yţ há⁠ʼèlòhi֖ym ʼàşě֥r bi̇⁠yrẇşá̌liáֽm׃"],[1,5,"וַ⁠יָּק֜וּמוּ רָאשֵׁ֣י הָ⁠אָב֗וֹת לִֽ⁠יהוּדָה֙ וּ⁠בִנְיָמִ֔ן וְ⁠הַ⁠כֹּהֲנִ֖ים וְ⁠הַ⁠לְוִיִּ֑ם לְ⁠כֹ֨ל הֵעִ֤יר הָ⁠אֱלֹהִים֙ אֶת־רוּח֔⁠וֹ לַ⁠עֲל֣וֹת לִ⁠בְנ֔וֹת אֶת־בֵּ֥ית יְהוָ֖ה אֲשֶׁ֥ר בִּ⁠ירוּשָׁלִָֽם׃","wa⁠yá̇q֜ẇmẇ ráʼşé֣̌y há⁠ʼáb֗wòţ liֽ⁠yhẇdáh֙ ẇ⁠binĕyámi֔n wĕ⁠ha⁠kò̇hàni֖ym wĕ⁠ha⁠lĕwiyi֑̇m lĕ⁠kò֨l héʻi֤yr há⁠ʼèlòhiym֙ ʼeţ-rẇẖ֔⁠wò la⁠ʻàl֣wòţ li⁠bĕn֔wòţ ʼeţ-bé֥̇yţ yĕhwá֖h ʼàşě֥r bi̇⁠yrẇşá̌liáֽm׃"],[1,6,"וְ⁠כָל־סְבִיבֹֽתֵי⁠הֶם֙ חִזְּק֣וּ בִֽ⁠ידֵי⁠הֶ֔ם בִּ⁠כְלֵי־כֶ֧סֶף בַּ⁠זָּהָ֛ב בָּ⁠רְכ֥וּשׁ וּ⁠בַ⁠בְּהֵמָ֖ה וּ⁠בַ⁠מִּגְדָּנ֑וֹת לְ⁠בַ֖ד עַל־כָּל־הִתְנַדֵּֽב׃ס","wĕ⁠kál-sĕbiybòֽţéy⁠hem֙ ẖizĕ̇q֣ẇ biֽ⁠ydéy⁠he֔m bi̇⁠kĕléy-ke֧sep bȧ⁠zá̇há֛b bá̇⁠rĕk֥ẇş̌ ẇ⁠ba⁠bĕ̇hémá֖h ẇ⁠ba⁠mi̇gĕdá̇n֑wòţ lĕ⁠ba֖d ʻal-ká̇l-hiţĕnadéֽ̇b׃s"],[1,7,"וְ⁠הַ⁠מֶּ֣לֶךְ כּ֔וֹרֶשׁ הוֹצִ֖יא אֶת־כְּלֵ֣י בֵית־יְהוָ֑ה אֲשֶׁ֨ר הוֹצִ֤יא נְבֽוּכַדְנֶצַּר֙ מִ⁠יר֣וּשָׁלִַ֔ם וַֽ⁠יִּתְּנֵ֖⁠ם בְּ⁠בֵ֥ית אֱלֹהָֽי⁠ו׃","wĕ⁠ha⁠mė֣lekĕ k̇֔wòreş̌ hwòẕi֖yʼ ʼeţ-kĕ̇lé֣y béyţ-yĕhwá֑h ʼàşě֨r hwòẕi֤yʼ nĕbֽẇkadĕneẕȧr֙ mi⁠yr֣ẇşá̌lia֔m waֽ⁠yi̇ţĕ̇né֖⁠m bĕ̇⁠bé֥yţ ʼèlòháֽy⁠w׃"],[1,8,"וַ⁠יּֽוֹצִיאֵ֗⁠ם כּ֚וֹרֶשׁ מֶ֣לֶךְ פָּרַ֔ס עַל־יַ֖ד מִתְרְדָ֣ת הַ⁠גִּזְבָּ֑ר וַֽ⁠יִּסְפְּרֵ⁠ם֙ לְ⁠שֵׁשְׁבַּצַּ֔ר הַ⁠נָּשִׂ֖יא לִ⁠יהוּדָֽה׃","wa⁠ẏֽwòẕiyʼé֗⁠m k֚̇wòreş̌ me֣lekĕ pá̇ra֔s ʻal-ya֖d miţĕrĕdá֣ţ ha⁠gi̇zĕbá֑̇r waֽ⁠yi̇sĕpĕ̇ré⁠m֙ lĕ⁠şé̌şĕ̌bȧẕȧ֔r ha⁠ná̇şî֖yʼ li⁠yhẇdáֽh׃"],[1,9,"וְ⁠אֵ֖לֶּה מִסְפָּרָ֑⁠ם אֲגַרְטְלֵ֨י זָהָ֜ב שְׁלֹשִׁ֗ים אֲגַרְטְלֵי־כֶ֨סֶף֙ אָ֔לֶף מַחֲלָפִ֖ים תִּשְׁעָ֥ה וְ⁠עֶשְׂרִֽים׃ס","wĕ⁠ʼé֖lėh misĕpá̇rá֑⁠m ʼàgarĕtĕlé֨y záhá֜b şĕ̌lòşǐ֗ym ʼàgarĕtĕléy-ke֨sep֙ ʼá֔lep maẖàlápi֖ym ţi̇şĕ̌ʻá֥h wĕ⁠ʻeşĕ̂riֽym׃s"],[1,10,"כְּפוֹרֵ֤י זָהָב֙ שְׁלֹשִׁ֔ים כְּפ֤וֹרֵי כֶ֨סֶף֙ מִשְׁנִ֔ים אַרְבַּ֥ע מֵא֖וֹת וַ⁠עֲשָׂרָ֑ה כֵּלִ֥ים אֲחֵרִ֖ים אָֽלֶף׃ס","kĕ̇pwòré֤y záháb֙ şĕ̌lòşǐ֔ym kĕ̇p֤wòréy ke֨sep֙ mişĕ̌ni֔ym ʼarĕbȧ֥ʻ méʼ֖wòţ wa⁠ʻàşá̂rá֑h ké̇li֥ym ʼàẖéri֖ym ʼáֽlep׃s"],[1,11,"כָּל־כֵּלִים֙ לַ⁠זָּהָ֣ב וְ⁠לַ⁠כֶּ֔סֶף חֲמֵ֥שֶׁת אֲלָפִ֖ים וְ⁠אַרְבַּ֣ע מֵא֑וֹת הַ⁠כֹּ֞ל הֶעֱלָ֣ה שֵׁשְׁבַּצַּ֗ר עִ֚ם הֵעָל֣וֹת הַ⁠גּוֹלָ֔ה מִ⁠בָּבֶ֖ל לִ⁠ירוּשָׁלִָֽם׃פ","ká̇l-ké̇liym֙ la⁠zá̇há֣b wĕ⁠la⁠kė֔sep ẖàmé֥şěţ ʼàlápi֖ym wĕ⁠ʼarĕbȧ֣ʻ méʼ֑wòţ ha⁠kò̇֞l heʻèlá֣h şé̌şĕ̌bȧẕȧ֗r ʻi֚m héʻál֣wòţ ha⁠ġwòlá֔h mi⁠bá̇be֖l li⁠yrẇşá̌liáֽm׃p"],[2,1,"וְ⁠אֵ֣לֶּה ׀ בְּנֵ֣י הַ⁠מְּדִינָ֗ה הָֽ⁠עֹלִים֙ מִ⁠שְּׁבִ֣י הַ⁠גּוֹלָ֔ה אֲשֶׁ֥ר הֶגְלָ֛ה נבוכדנצור מֶֽלֶךְ־בָּבֶ֖ל לְ⁠בָבֶ֑ל וַ⁠יָּשׁ֛וּבוּ לִ⁠ירוּשָׁלִַ֥ם וִֽ⁠יהוּדָ֖ה אִ֥ישׁ לְ⁠עִירֽ⁠וֹ׃","wĕ⁠ʼé֣lėh ׀ bĕ̇né֣y ha⁠mĕ̇diyná֗h háֽ⁠ʻòliym֙ mi⁠şĕ̇̌bi֣y ha⁠ġwòlá֔h ʼàşě֥r hegĕlá֛h nbwkdnẕwr meֽlekĕ-bá̇be֖l lĕ⁠bábe֑l wa⁠yá̇ş֛̌ẇbẇ li⁠yrẇşá̌lia֥m wiֽ⁠yhẇdá֖h ʼi֥yş̌ lĕ⁠ʻiyrֽ⁠wò׃"],[2,2,"אֲשֶׁר־בָּ֣אוּ עִם־זְרֻבָּבֶ֗ל יֵשׁ֡וּעַ נְ֠חֶמְיָה שְׂרָיָ֨ה רְֽעֵלָיָ֜ה מָרְדֳּכַ֥י בִּלְשָׁ֛ן מִסְפָּ֥ר בִּגְוַ֖י רְח֣וּם בַּעֲנָ֑ה מִסְפַּ֕ר אַנְשֵׁ֖י עַ֥ם יִשְׂרָאֵֽל׃ס","ʼàşěr-bá֣̇ʼẇ ʻim-zĕrubá̇be֗l yéş̌֡ẇʻa nĕ֠ẖemĕyáh şĕ̂ráyá֨h rĕֽʻéláyá֜h márĕdȯka֥y bi̇lĕşá֛̌n misĕpá֥̇r bi̇gĕwa֖y rĕẖ֣ẇm bȧʻàná֑h misĕpȧ֕r ʼanĕşé֖̌y ʻa֥m yişĕ̂ráʼéֽl׃s"],[2,3,"בְּנֵ֣י פַרְעֹ֔שׁ אַלְפַּ֕יִם מֵאָ֖ה שִׁבְעִ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֣y parĕʻò֔ş̌ ʼalĕpȧ֕yim méʼá֖h şǐbĕʻi֥ym ẇ⁠şĕ̌náֽyim׃s"],[2,4,"בְּנֵ֣י שְׁפַטְיָ֔ה שְׁלֹ֥שׁ מֵא֖וֹת שִׁבְעִ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֣y şĕ̌patĕyá֔h şĕ̌lò֥ş̌ méʼ֖wòţ şǐbĕʻi֥ym ẇ⁠şĕ̌náֽyim׃s"],[2,5,"בְּנֵ֣י אָרַ֔ח שְׁבַ֥ע מֵא֖וֹת חֲמִשָּׁ֥ה וְ⁠שִׁבְעִֽים׃ס","bĕ̇né֣y ʼára֔ẖ şĕ̌ba֥ʻ méʼ֖wòţ ẖàmişá֥̇̌h wĕ⁠şǐbĕʻiֽym׃s"],[2,6,"בְּנֵֽי־פַחַ֥ת מוֹאָ֛ב לִ⁠בְנֵ֥י יֵשׁ֖וּעַ יוֹאָ֑ב אַלְפַּ֕יִם שְׁמֹנֶ֥ה מֵא֖וֹת וּ⁠שְׁנֵ֥ים עָשָֽׂר׃ס","bĕ̇néֽy-paẖa֥ţ mwòʼá֛b li⁠bĕné֥y yéş֖̌ẇʻa ywòʼá֑b ʼalĕpȧ֕yim şĕ̌mòne֥h méʼ֖wòţ ẇ⁠şĕ̌né֥ym ʻáşáֽ̂r׃s"],[2,7,"בְּנֵ֣י עֵילָ֔ם אֶ֕לֶף מָאתַ֖יִם חֲמִשִּׁ֥ים וְ⁠אַרְבָּעָֽה׃ס","bĕ̇né֣y ʻéylá֔m ʼe֕lep máʼţa֖yim ẖàmişi֥̇̌ym wĕ⁠ʼarĕbá̇ʻáֽh׃s"],[2,8,"בְּנֵ֣י זַתּ֔וּא תְּשַׁ֥ע מֵא֖וֹת וְ⁠אַרְבָּעִ֥ים וַ⁠חֲמִשָּֽׁה׃ס","bĕ̇né֣y zaţ̇֔ẇʼ ţĕ̇şǎ֥ʻ méʼ֖wòţ wĕ⁠ʼarĕbá̇ʻi֥ym wa⁠ẖàmişáֽ̇̌h׃s"],[2,9,"בְּנֵ֣י זַכָּ֔י שְׁבַ֥ע מֵא֖וֹת וְ⁠שִׁשִּֽׁים׃ס","bĕ̇né֣y zaká̇֔y şĕ̌ba֥ʻ méʼ֖wòţ wĕ⁠şǐşiֽ̇̌ym׃s"],[2,10,"בְּנֵ֣י בָנִ֔י שֵׁ֥שׁ מֵא֖וֹת אַרְבָּעִ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֣y báni֔y şé֥̌ş̌ méʼ֖wòţ ʼarĕbá̇ʻi֥ym ẇ⁠şĕ̌náֽyim׃s"],[2,11,"בְּנֵ֣י בֵבָ֔י שֵׁ֥שׁ מֵא֖וֹת עֶשְׂרִ֥ים וּ⁠שְׁלֹשָֽׁה׃ס","bĕ̇né֣y bébá֔y şé֥̌ş̌ méʼ֖wòţ ʻeşĕ̂ri֥ym ẇ⁠şĕ̌lòşáֽ̌h׃s"],[2,12,"בְּנֵ֣י עַזְגָּ֔ד אֶ֕לֶף מָאתַ֖יִם עֶשְׂרִ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֣y ʻazĕgá̇֔d ʼe֕lep máʼţa֖yim ʻeşĕ̂ri֥ym ẇ⁠şĕ̌náֽyim׃s"],[2,13,"בְּנֵי֙ אֲדֹ֣נִיקָ֔ם שֵׁ֥שׁ מֵא֖וֹת שִׁשִּׁ֥ים וְ⁠שִׁשָּֽׁה׃ס","bĕ̇néy֙ ʼàdò֣niyqá֔m şé֥̌ş̌ méʼ֖wòţ şǐşi֥̇̌ym wĕ⁠şǐşáֽ̇̌h׃s"],[2,14,"בְּנֵ֣י בִגְוָ֔י אַלְפַּ֖יִם חֲמִשִּׁ֥ים וְ⁠שִׁשָּֽׁה׃ס","bĕ̇né֣y bigĕwá֔y ʼalĕpȧ֖yim ẖàmişi֥̇̌ym wĕ⁠şǐşáֽ̇̌h׃s"],[2,15,"בְּנֵ֣י עָדִ֔ין אַרְבַּ֥ע מֵא֖וֹת חֲמִשִּׁ֥ים וְ⁠אַרְבָּעָֽה׃ס","bĕ̇né֣y ʻádi֔yn ʼarĕbȧ֥ʻ méʼ֖wòţ ẖàmişi֥̇̌ym wĕ⁠ʼarĕbá̇ʻáֽh׃s"],[2,16,"בְּנֵֽי־אָטֵ֥ר לִֽ⁠יחִזְקִיָּ֖ה תִּשְׁעִ֥ים וּ⁠שְׁמֹנָֽה׃ס","bĕ̇néֽy-ʼáté֥r liֽ⁠yẖizĕqiyá֖̇h ţi̇şĕ̌ʻi֥ym ẇ⁠şĕ̌mònáֽh׃s"],[2,17,"בְּנֵ֣י בֵצָ֔י שְׁלֹ֥שׁ מֵא֖וֹת עֶשְׂרִ֥ים וּ⁠שְׁלֹשָֽׁה׃ס","bĕ̇né֣y béẕá֔y şĕ̌lò֥ş̌ méʼ֖wòţ ʻeşĕ̂ri֥ym ẇ⁠şĕ̌lòşáֽ̌h׃s"],[2,18,"בְּנֵ֣י יוֹרָ֔ה מֵאָ֖ה וּ⁠שְׁנֵ֥ים עָשָֽׂר׃ס","bĕ̇né֣y ywòrá֔h méʼá֖h ẇ⁠şĕ̌né֥ym ʻáşáֽ̂r׃s"],[2,19,"בְּנֵ֣י חָשֻׁ֔ם מָאתַ֖יִם עֶשְׂרִ֥ים וּ⁠שְׁלֹשָֽׁה׃ס","bĕ̇né֣y ẖáşǔ֔m máʼţa֖yim ʻeşĕ̂ri֥ym ẇ⁠şĕ̌lòşáֽ̌h׃s"],[2,20,"בְּנֵ֥י גִבָּ֖ר תִּשְׁעִ֥ים וַ⁠חֲמִשָּֽׁה׃ס","bĕ̇né֥y gibá֖̇r ţi̇şĕ̌ʻi֥ym wa⁠ẖàmişáֽ̇̌h׃s"],[2,21,"בְּנֵ֣י בֵֽית־לָ֔חֶם מֵאָ֖ה עֶשְׂרִ֥ים וּ⁠שְׁלֹשָֽׁה׃ס","bĕ̇né֣y béֽyţ-lá֔ẖem méʼá֖h ʻeşĕ̂ri֥ym ẇ⁠şĕ̌lòşáֽ̌h׃s"],[2,22,"אַנְשֵׁ֥י נְטֹפָ֖ה חֲמִשִּׁ֥ים וְ⁠שִׁשָּֽׁה׃","ʼanĕşé֥̌y nĕtòpá֖h ẖàmişi֥̇̌ym wĕ⁠şǐşáֽ̇̌h׃"],[2,23,"אַנְשֵׁ֣י עֲנָת֔וֹת מֵאָ֖ה עֶשְׂרִ֥ים וּ⁠שְׁמֹנָֽה׃ס","ʼanĕşé֣̌y ʻànáţ֔wòţ méʼá֖h ʻeşĕ̂ri֥ym ẇ⁠şĕ̌mònáֽh׃s"],[2,24,"בְּנֵ֥י עַזְמָ֖וֶת אַרְבָּעִ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֥y ʻazĕmá֖weţ ʼarĕbá̇ʻi֥ym ẇ⁠şĕ̌náֽyim׃s"],[2,25,"בְּנֵ֨י קִרְיַ֤ת עָרִים֙ כְּפִירָ֣ה וּ⁠בְאֵר֔וֹת שְׁבַ֥ע מֵא֖וֹת וְ⁠אַרְבָּעִ֥ים וּ⁠שְׁלֹשָֽׁה׃ס","bĕ̇né֨y qirĕya֤ţ ʻáriym֙ kĕ̇piyrá֣h ẇ⁠bĕʼér֔wòţ şĕ̌ba֥ʻ méʼ֖wòţ wĕ⁠ʼarĕbá̇ʻi֥ym ẇ⁠şĕ̌lòşáֽ̌h׃s"],[2,26,"בְּנֵ֤י הָ⁠רָמָה֙ וָ⁠גָ֔בַע שֵׁ֥שׁ מֵא֖וֹת עֶשְׂרִ֥ים וְ⁠אֶחָֽד׃ס","bĕ̇né֤y há⁠rámáh֙ wá⁠gá֔baʻ şé֥̌ş̌ méʼ֖wòţ ʻeşĕ̂ri֥ym wĕ⁠ʼeẖáֽd׃s"],[2,27,"אַנְשֵׁ֣י מִכְמָ֔ס מֵאָ֖ה עֶשְׂרִ֥ים וּ⁠שְׁנָֽיִם׃ס","ʼanĕşé֣̌y mikĕmá֔s méʼá֖h ʻeşĕ̂ri֥ym ẇ⁠şĕ̌náֽyim׃s"],[2,28,"אַנְשֵׁ֤י בֵֽית־אֵל֙ וְ⁠הָ⁠עָ֔י מָאתַ֖יִם עֶשְׂרִ֥ים וּ⁠שְׁלֹשָֽׁה׃ס","ʼanĕşé֤̌y béֽyţ-ʼél֙ wĕ⁠há⁠ʻá֔y máʼţa֖yim ʻeşĕ̂ri֥ym ẇ⁠şĕ̌lòşáֽ̌h׃s"],[2,29,"בְּנֵ֥י נְב֖וֹ חֲמִשִּׁ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֥y nĕb֖wò ẖàmişi֥̇̌ym ẇ⁠şĕ̌náֽyim׃s"],[2,30,"בְּנֵ֣י מַגְבִּ֔ישׁ מֵאָ֖ה חֲמִשִּׁ֥ים וְ⁠שִׁשָּֽׁה׃ס","bĕ̇né֣y magĕbi̇֔yş̌ méʼá֖h ẖàmişi֥̇̌ym wĕ⁠şǐşáֽ̇̌h׃s"],[2,31,"בְּנֵי֙ עֵילָ֣ם אַחֵ֔ר אֶ֕לֶף מָאתַ֖יִם חֲמִשִּׁ֥ים וְ⁠אַרְבָּעָֽה׃ס","bĕ̇néy֙ ʻéylá֣m ʼaẖé֔r ʼe֕lep máʼţa֖yim ẖàmişi֥̇̌ym wĕ⁠ʼarĕbá̇ʻáֽh׃s"],[2,32,"בְּנֵ֣י חָרִ֔ם שְׁלֹ֥שׁ מֵא֖וֹת וְ⁠עֶשְׂרִֽים׃ס","bĕ̇né֣y ẖári֔m şĕ̌lò֥ş̌ méʼ֖wòţ wĕ⁠ʻeşĕ̂riֽym׃s"],[2,33,"בְּנֵי־לֹד֙ חָדִ֣יד וְ⁠אוֹנ֔וֹ שְׁבַ֥ע מֵא֖וֹת עֶשְׂרִ֥ים וַ⁠חֲמִשָּֽׁה׃ס","bĕ̇néy-lòd֙ ẖádi֣yd wĕ⁠ʼwòn֔wò şĕ̌ba֥ʻ méʼ֖wòţ ʻeşĕ̂ri֥ym wa⁠ẖàmişáֽ̇̌h׃s"],[2,34,"בְּנֵ֣י יְרֵח֔וֹ שְׁלֹ֥שׁ מֵא֖וֹת אַרְבָּעִ֥ים וַ⁠חֲמִשָּֽׁה׃ס","bĕ̇né֣y yĕréẖ֔wò şĕ̌lò֥ş̌ méʼ֖wòţ ʼarĕbá̇ʻi֥ym wa⁠ẖàmişáֽ̇̌h׃s"],[2,35,"בְּנֵ֣י סְנָאָ֔ה שְׁלֹ֣שֶׁת אֲלָפִ֔ים וְ⁠שֵׁ֥שׁ מֵא֖וֹת וּ⁠שְׁלֹשִֽׁים׃ס","bĕ̇né֣y sĕnáʼá֔h şĕ̌lò֣şěţ ʼàlápi֔ym wĕ⁠şé֥̌ş̌ méʼ֖wòţ ẇ⁠şĕ̌lòşǐֽym׃s"],[2,36,"הַֽ⁠כֹּהֲנִ֑ים בְּנֵ֤י יְדַֽעְיָה֙ לְ⁠בֵ֣ית יֵשׁ֔וּעַ תְּשַׁ֥ע מֵא֖וֹת שִׁבְעִ֥ים וּ⁠שְׁלֹשָֽׁה׃ס","haֽ⁠kò̇hàni֑ym bĕ̇né֤y yĕdaֽʻĕyáh֙ lĕ⁠bé֣yţ yéş̌֔ẇʻa ţĕ̇şǎ֥ʻ méʼ֖wòţ şǐbĕʻi֥ym ẇ⁠şĕ̌lòşáֽ̌h׃s"],[2,37,"בְּנֵ֣י אִמֵּ֔ר אֶ֖לֶף חֲמִשִּׁ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֣y ʼimé̇֔r ʼe֖lep ẖàmişi֥̇̌ym ẇ⁠şĕ̌náֽyim׃s"],[2,38,"בְּנֵ֣י פַשְׁח֔וּר אֶ֕לֶף מָאתַ֖יִם אַרְבָּעִ֥ים וְ⁠שִׁבְעָֽה׃ס","bĕ̇né֣y paşĕ̌ẖ֔ẇr ʼe֕lep máʼţa֖yim ʼarĕbá̇ʻi֥ym wĕ⁠şǐbĕʻáֽh׃s"],[2,39,"בְּנֵ֣י חָרִ֔ם אֶ֖לֶף וְ⁠שִׁבְעָ֥ה עָשָֽׂר׃ס","bĕ̇né֣y ẖári֔m ʼe֖lep wĕ⁠şǐbĕʻá֥h ʻáşáֽ̂r׃s"],[2,40,"הַ⁠לְוִיִּ֑ם בְּנֵי־יֵשׁ֧וּעַ וְ⁠קַדְמִיאֵ֛ל לִ⁠בְנֵ֥י הוֹדַוְיָ֖ה שִׁבְעִ֥ים וְ⁠אַרְבָּעָֽה׃ס","ha⁠lĕwiyi֑̇m bĕ̇néy-yéş֧̌ẇʻa wĕ⁠qadĕmiyʼé֛l li⁠bĕné֥y hwòdawĕyá֖h şǐbĕʻi֥ym wĕ⁠ʼarĕbá̇ʻáֽh׃s"],[2,41,"הַֽ⁠מְשֹׁרְרִ֑ים בְּנֵ֣י אָסָ֔ף מֵאָ֖ה עֶשְׂרִ֥ים וּ⁠שְׁמֹנָֽה׃פ","haֽ⁠mĕşò̌rĕri֑ym bĕ̇né֣y ʼásá֔p méʼá֖h ʻeşĕ̂ri֥ym ẇ⁠şĕ̌mònáֽh׃p"],[2,42,"בְּנֵ֣י הַ⁠שֹּֽׁעֲרִ֗ים בְּנֵי־שַׁלּ֤וּם בְּנֵֽי־אָטֵר֙ בְּנֵי־טַלְמ֣וֹן בְּנֵי־עַקּ֔וּב בְּנֵ֥י חֲטִיטָ֖א בְּנֵ֣י שֹׁבָ֑י הַ⁠כֹּ֕ל מֵאָ֖ה שְׁלֹשִׁ֥ים וְ⁠תִשְׁעָֽה׃פ","bĕ̇né֣y ha⁠şòֽ̇̌ʻàri֗ym bĕ̇néy-şǎl֤̇ẇm bĕ̇néֽy-ʼátér֙ bĕ̇néy-talĕm֣wòn bĕ̇néy-ʻaq̇֔ẇb bĕ̇né֥y ẖàtiytá֖ʼ bĕ̇né֣y şò̌bá֑y ha⁠kò̇֕l méʼá֖h şĕ̌lòşǐ֥ym wĕ⁠ţişĕ̌ʻáֽh׃p"],[2,43,"הַ⁠נְּתִינִ֑ים בְּנֵי־צִיחָ֥א בְנֵי־חֲשׂוּפָ֖א בְּנֵ֥י טַבָּעֽוֹת׃","ha⁠nĕ̇ţiyni֑ym bĕ̇néy-ẕiyẖá֥ʼ bĕnéy-ẖàş̂ẇpá֖ʼ bĕ̇né֥y tabá̇ʻֽwòţ׃"],[2,44,"בְּנֵי־קֵרֹ֥ס בְּֽנֵי־סִֽיעֲהָ֖א בְּנֵ֥י פָדֽוֹן׃","bĕ̇néy-qérò֥s bĕֽ̇néy-siֽyʻàhá֖ʼ bĕ̇né֥y pádֽwòn׃"],[2,45,"בְּנֵי־לְבָנָ֥ה בְנֵי־חֲגָבָ֖ה בְּנֵ֥י עַקּֽוּב׃","bĕ̇néy-lĕbáná֥h bĕnéy-ẖàgábá֖h bĕ̇né֥y ʻaqֽ̇ẇb׃"],[2,46,"בְּנֵי־חָגָ֥ב בְּנֵי־שמלי בְּנֵ֥י חָנָֽן׃","bĕ̇néy-ẖágá֥b bĕ̇néy-şmly bĕ̇né֥y ẖánáֽn׃"],[2,47,"בְּנֵי־גִדֵּ֥ל בְּנֵי־גַ֖חַר בְּנֵ֥י רְאָיָֽה׃","bĕ̇néy-gidé֥̇l bĕ̇néy-ga֖ẖar bĕ̇né֥y rĕʼáyáֽh׃"],[2,48,"בְּנֵי־רְצִ֥ין בְּנֵי־נְקוֹדָ֖א בְּנֵ֥י גַזָּֽם׃","bĕ̇néy-rĕẕi֥yn bĕ̇néy-nĕqwòdá֖ʼ bĕ̇né֥y gazáֽ̇m׃"],[2,49,"בְּנֵי־עֻזָּ֥א בְנֵי־פָסֵ֖חַ בְּנֵ֥י בֵסָֽי׃","bĕ̇néy-ʻuzá֥̇ʼ bĕnéy-pásé֖ẖa bĕ̇né֥y bésáֽy׃"],[2,50,"בְּנֵי־אַסְנָ֥ה בְנֵי־מעינים בְּנֵ֥י נפיסים׃","bĕ̇néy-ʼasĕná֥h bĕnéy-mʻynym bĕ̇né֥y npysym׃"],[2,51,"בְּנֵי־בַקְבּ֥וּק בְּנֵי־חֲקוּפָ֖א בְּנֵ֥י חַרְחֽוּר׃","bĕ̇néy-baqĕḃ֥ẇq bĕ̇néy-ẖàqẇpá֖ʼ bĕ̇né֥y ẖarĕẖֽẇr׃"],[2,52,"בְּנֵי־בַצְל֥וּת בְּנֵי־מְחִידָ֖א בְּנֵ֥י חַרְשָֽׁא׃","bĕ̇néy-baẕĕl֥ẇţ bĕ̇néy-mĕẖiydá֖ʼ bĕ̇né֥y ẖarĕşáֽ̌ʼ׃"],[2,53,"בְּנֵי־בַרְק֥וֹס בְּֽנֵי־סִֽיסְרָ֖א בְּנֵי־תָֽמַח׃","bĕ̇néy-barĕq֥wòs bĕֽ̇néy-siֽysĕrá֖ʼ bĕ̇néy-ţáֽmaẖ׃"],[2,54,"בְּנֵ֥י נְצִ֖יחַ בְּנֵ֥י חֲטִיפָֽא׃","bĕ̇né֥y nĕẕi֖yẖa bĕ̇né֥y ẖàtiypáֽʼ׃"],[2,55,"בְּנֵ֖י עַבְדֵ֣י שְׁלֹמֹ֑ה בְּנֵי־סֹטַ֥י בְּנֵי־הַ⁠סֹּפֶ֖רֶת בְּנֵ֥י פְרוּדָֽא׃","bĕ̇né֖y ʻabĕdé֣y şĕ̌lòmò֑h bĕ̇néy-sòta֥y bĕ̇néy-ha⁠sò̇pe֖reţ bĕ̇né֥y pĕrẇdáֽʼ׃"],[2,56,"בְּנֵי־יַעְלָ֥ה בְנֵי־דַרְק֖וֹן בְּנֵ֥י גִדֵּֽל׃","bĕ̇néy-yaʻĕlá֥h bĕnéy-darĕq֖wòn bĕ̇né֥y gidéֽ̇l׃"],[2,57,"בְּנֵ֧י שְׁפַטְיָ֣ה בְנֵֽי־חַטִּ֗יל בְּנֵ֛י פֹּכֶ֥רֶת הַצְּבָיִ֖ים בְּנֵ֥י אָמִֽי׃","bĕ̇né֧y şĕ̌patĕyá֣h bĕnéֽy-ẖati̇֗yl bĕ̇né֛y pò̇ke֥reţ haẕĕ̇báyi֖ym bĕ̇né֥y ʼámiֽy׃"],[2,58,"כָּ֨ל־הַ⁠נְּתִינִ֔ים וּ⁠בְנֵ֖י עַבְדֵ֣י שְׁלֹמֹ֑ה שְׁלֹ֥שׁ מֵא֖וֹת תִּשְׁעִ֥ים וּ⁠שְׁנָֽיִם׃ס","ká̇֨l-ha⁠nĕ̇ţiyni֔ym ẇ⁠bĕné֖y ʻabĕdé֣y şĕ̌lòmò֑h şĕ̌lò֥ş̌ méʼ֖wòţ ţi̇şĕ̌ʻi֥ym ẇ⁠şĕ̌náֽyim׃s"],[2,59,"וְ⁠אֵ֗לֶּה הָֽ⁠עֹלִים֙ מִ⁠תֵּ֥ל מֶ֨לַח֙ תֵּ֣ל חַרְשָׁ֔א כְּר֥וּב אַדָּ֖ן אִמֵּ֑ר וְ⁠לֹ֣א יָֽכְל֗וּ לְ⁠הַגִּ֤יד בֵּית־אֲבוֹתָ⁠ם֙ וְ⁠זַרְעָ֔⁠ם אִ֥ם מִ⁠יִּשְׂרָאֵ֖ל הֵֽם׃","wĕ⁠ʼé֗lėh háֽ⁠ʻòliym֙ mi⁠ţé֥̇l me֨laẖ֙ ţé֣̇l ẖarĕşá̌֔ʼ kĕ̇r֥ẇb ʼadá֖̇n ʼimé֑̇r wĕ⁠lò֣ʼ yáֽkĕl֗ẇ lĕ⁠hagi֤̇yd bé̇yţ-ʼàbwòţá⁠m֙ wĕ⁠zarĕʻá֔⁠m ʼi֥m mi⁠yi̇şĕ̂ráʼé֖l héֽm׃"],[2,60,"בְּנֵי־דְלָיָ֥ה בְנֵי־טוֹבִיָּ֖ה בְּנֵ֣י נְקוֹדָ֑א שֵׁ֥שׁ מֵא֖וֹת חֲמִשִּׁ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇néy-dĕláyá֥h bĕnéy-twòbiyá֖̇h bĕ̇né֣y nĕqwòdá֑ʼ şé֥̌ş̌ méʼ֖wòţ ẖàmişi֥̇̌ym ẇ⁠şĕ̌náֽyim׃s"],[2,61,"וּ⁠מִ⁠בְּנֵי֙ הַ⁠כֹּ֣הֲנִ֔ים בְּנֵ֥י חֳבַיָּ֖ה בְּנֵ֣י הַקּ֑וֹץ בְּנֵ֣י בַרְזִלַּ֗י אֲשֶׁ֣ר לָ֠קַח מִ⁠בְּנ֞וֹת בַּרְזִלַּ֤י הַ⁠גִּלְעָדִי֙ אִשָּׁ֔ה וַ⁠יִּקָּרֵ֖א עַל־שְׁמָֽ⁠ם׃","ẇ⁠mi⁠bĕ̇néy֙ ha⁠kò֣̇hàni֔ym bĕ̇né֥y ẖobayá֖̇h bĕ̇né֣y haq֑̇wòẕ bĕ̇né֣y barĕzilȧ֗y ʼàşě֣r lá֠qaẖ mi⁠bĕ̇n֞wòţ bȧrĕzilȧ֤y ha⁠gi̇lĕʻádiy֙ ʼişá̇̌֔h wa⁠yi̇qá̇ré֖ʼ ʻal-şĕ̌máֽ⁠m׃"],[2,62,"אֵ֗לֶּה בִּקְשׁ֧וּ כְתָבָ֛⁠ם הַ⁠מִּתְיַחְשִׂ֖ים וְ⁠לֹ֣א נִמְצָ֑אוּ וַֽ⁠יְגֹאֲל֖וּ מִן־הַ⁠כְּהֻנָּֽה׃","ʼé֗lėh bi̇qĕş֧̌ẇ kĕţábá֛⁠m ha⁠mi̇ţĕyaẖĕşî֖ym wĕ⁠lò֣ʼ nimĕẕá֑ʼẇ waֽ⁠yĕgòʼàl֖ẇ min-ha⁠kĕ̇hunáֽ̇h׃"],[2,63,"וַ⁠יֹּ֤אמֶר הַ⁠תִּרְשָׁ֨תָא֙ לָ⁠הֶ֔ם אֲשֶׁ֥ר לֹא־יֹאכְל֖וּ מִ⁠קֹּ֣דֶשׁ הַ⁠קֳּדָשִׁ֑ים עַ֛ד עֲמֹ֥ד כֹּהֵ֖ן לְ⁠אוּרִ֥ים וּ⁠לְ⁠תֻמִּֽים׃","wa⁠yò֤̇ʼmer ha⁠ţi̇rĕşá̌֨ţáʼ֙ lá⁠he֔m ʼàşě֥r lòʼ-yòʼkĕl֖ẇ mi⁠qò֣̇deş̌ ha⁠qȯdáşǐ֑ym ʻa֛d ʻàmò֥d kò̇hé֖n lĕ⁠ʼẇri֥ym ẇ⁠lĕ⁠ţumiֽ̇ym׃"],[2,64,"כָּל־הַ⁠קָּהָ֖ל כְּ⁠אֶחָ֑ד אַרְבַּ֣ע רִבּ֔וֹא אַלְפַּ֖יִם שְׁלֹשׁ־מֵא֥וֹת שִׁשִּֽׁים׃","ká̇l-ha⁠qá̇há֖l kĕ̇⁠ʼeẖá֑d ʼarĕbȧ֣ʻ riḃ֔wòʼ ʼalĕpȧ֖yim şĕ̌lòş̌-méʼ֥wòţ şǐşiֽ̇̌ym׃"],[2,65,"מִ֠⁠לְּ⁠בַד עַבְדֵי⁠הֶ֤ם וְ⁠אַמְהֹֽתֵי⁠הֶם֙ אֵ֔לֶּה שִׁבְעַ֣ת אֲלָפִ֔ים שְׁלֹ֥שׁ מֵא֖וֹת שְׁלֹשִׁ֣ים וְ⁠שִׁבְעָ֑ה וְ⁠לָ⁠הֶ֛ם מְשֹׁרְרִ֥ים וּֽ⁠מְשֹׁרְר֖וֹת מָאתָֽיִם׃","mi֠⁠lĕ̇⁠bad ʻabĕdéy⁠he֤m wĕ⁠ʼamĕhòֽţéy⁠hem֙ ʼé֔lėh şǐbĕʻa֣ţ ʼàlápi֔ym şĕ̌lò֥ş̌ méʼ֖wòţ şĕ̌lòşǐ֣ym wĕ⁠şǐbĕʻá֑h wĕ⁠lá⁠he֛m mĕşò̌rĕri֥ym ẇֽ⁠mĕşò̌rĕr֖wòţ máʼţáֽyim׃"],[2,66,"סוּסֵי⁠הֶ֕ם שְׁבַ֥ע מֵא֖וֹת שְׁלֹשִׁ֣ים וְ⁠שִׁשָּׁ֑ה פִּרְדֵי⁠הֶ֕ם מָאתַ֖יִם אַרְבָּעִ֥ים וַ⁠חֲמִשָּֽׁה׃","sẇséy⁠he֕m şĕ̌ba֥ʻ méʼ֖wòţ şĕ̌lòşǐ֣ym wĕ⁠şǐşá֑̇̌h pi̇rĕdéy⁠he֕m máʼţa֖yim ʼarĕbá̇ʻi֥ym wa⁠ẖàmişáֽ̇̌h׃"],[2,67,"גְּמַ֨לֵּי⁠הֶ֔ם אַרְבַּ֥ע מֵא֖וֹת שְׁלֹשִׁ֣ים וַ⁠חֲמִשָּׁ֑ה חֲמֹרִ֕ים שֵׁ֣שֶׁת אֲלָפִ֔ים שְׁבַ֥ע מֵא֖וֹת וְ⁠עֶשְׂרִֽים׃פ","gĕ̇ma֨lé̇y⁠he֔m ʼarĕbȧ֥ʻ méʼ֖wòţ şĕ̌lòşǐ֣ym wa⁠ẖàmişá֑̇̌h ẖàmòri֕ym şé֣̌şěţ ʼàlápi֔ym şĕ̌ba֥ʻ méʼ֖wòţ wĕ⁠ʻeşĕ̂riֽym׃p"],[2,68,"וּ⁠מֵ⁠רָאשֵׁי֙ הָֽ⁠אָב֔וֹת בְּ⁠בוֹאָ֕⁠ם לְ⁠בֵ֥ית יְהוָ֖ה אֲשֶׁ֣ר בִּ⁠ירוּשָׁלִָ֑ם הִֽתְנַדְּבוּ֙ לְ⁠בֵ֣ית הָֽ⁠אֱלֹהִ֔ים לְ⁠הַעֲמִיד֖⁠וֹ עַל־מְכוֹנֽ⁠וֹ׃","ẇ⁠mé⁠ráʼşé̌y֙ háֽ⁠ʼáb֔wòţ bĕ̇⁠bwòʼá֕⁠m lĕ⁠bé֥yţ yĕhwá֖h ʼàşě֣r bi̇⁠yrẇşá̌liá֑m hiֽţĕnadĕ̇bẇ֙ lĕ⁠bé֣yţ háֽ⁠ʼèlòhi֔ym lĕ⁠haʻàmiyd֖⁠wò ʻal-mĕkwònֽ⁠wò׃"],[2,69,"כְּ⁠כֹחָ֗⁠ם נָתְנוּ֮ לְ⁠אוֹצַ֣ר הַ⁠מְּלָאכָה֒ זָהָ֗ב דַּרְכְּמוֹנִים֙ שֵׁשׁ־רִבֹּ֣אות וָ⁠אֶ֔לֶף ס וְ⁠כֶ֕סֶף מָנִ֖ים חֲמֵ֣שֶׁת אֲלָפִ֑ים וְ⁠כָתְנֹ֥ת כֹּהֲנִ֖ים מֵאָֽה׃ס","kĕ̇⁠kòẖá֗⁠m náţĕnẇ֮ lĕ⁠ʼwòẕa֣r ha⁠mĕ̇láʼkáh֒ záhá֗b dȧrĕkĕ̇mwòniym֙ şé̌ş̌-ribò֣̇ʼwţ wá⁠ʼe֔lep s wĕ⁠ke֕sep máni֖ym ẖàmé֣şěţ ʼàlápi֑ym wĕ⁠káţĕnò֥ţ kò̇hàni֖ym méʼáֽh׃s"],[2,70,"וַ⁠יֵּשְׁב֣וּ הַ⁠כֹּהֲנִ֣ים וְ֠⁠הַ⁠לְוִיִּם וּֽ⁠מִן־הָ⁠עָ֞ם וְ⁠הַ⁠מְשֹׁרְרִ֧ים וְ⁠הַ⁠שּׁוֹעֲרִ֛ים וְ⁠הַ⁠נְּתִינִ֖ים בְּ⁠עָרֵי⁠הֶ֑ם וְ⁠כָל־יִשְׂרָאֵ֖ל בְּ⁠עָרֵי⁠הֶֽם׃ס","wa⁠yé̇şĕ̌b֣ẇ ha⁠kò̇hàni֣ym wĕ֠⁠ha⁠lĕwiyi̇m ẇֽ⁠min-há⁠ʻá֞m wĕ⁠ha⁠mĕşò̌rĕri֧ym wĕ⁠ha⁠ş̇̌wòʻàri֛ym wĕ⁠ha⁠nĕ̇ţiyni֖ym bĕ̇⁠ʻáréy⁠he֑m wĕ⁠kál-yişĕ̂ráʼé֖l bĕ̇⁠ʻáréy⁠heֽm׃s"],[3,1,"וַ⁠יִּגַּע֙ הַ⁠חֹ֣דֶשׁ הַ⁠שְּׁבִיעִ֔י וּ⁠בְנֵ֥י יִשְׂרָאֵ֖ל בֶּ⁠עָרִ֑ים ס וַ⁠יֵּאָסְפ֥וּ הָ⁠עָ֛ם כְּ⁠אִ֥ישׁ אֶחָ֖ד אֶל־יְרוּשָׁלִָֽם׃ס","wa⁠yi̇gȧʻ֙ ha⁠ẖò֣deş̌ ha⁠şĕ̇̌biyʻi֔y ẇ⁠bĕné֥y yişĕ̂ráʼé֖l bė⁠ʻári֑ym s wa⁠yé̇ʼásĕp֥ẇ há⁠ʻá֛m kĕ̇⁠ʼi֥yş̌ ʼeẖá֖d ʼel-yĕrẇşá̌liáֽm׃s"],[3,2,"וַ⁠יָּקָם֩ יֵשׁ֨וּעַ בֶּן־יֽוֹצָדָ֜ק וְ⁠אֶחָ֣י⁠ו הַ⁠כֹּהֲנִ֗ים וּ⁠זְרֻבָּבֶ֤ל בֶּן־שְׁאַלְתִּיאֵל֙ וְ⁠אֶחָ֔י⁠ו וַ⁠יִּבְנ֕וּ אֶת־מִזְבַּ֖ח אֱלֹהֵ֣י יִשְׂרָאֵ֑ל לְ⁠הַעֲל֤וֹת עָלָי⁠ו֙ עֹל֔וֹת כַּ⁠כָּת֕וּב בְּ⁠תוֹרַ֖ת מֹשֶׁ֥ה אִישׁ־הָ⁠אֱלֹהִֽים׃","wa⁠yá̇qám֩ yéş̌֨ẇʻa bėn-yֽwòẕádá֜q wĕ⁠ʼeẖá֣y⁠w ha⁠kò̇hàni֗ym ẇ⁠zĕrubá̇be֤l bėn-şĕ̌ʼalĕţi̇yʼél֙ wĕ⁠ʼeẖá֔y⁠w wa⁠yi̇bĕn֕ẇ ʼeţ-mizĕbȧ֖ẖ ʼèlòhé֣y yişĕ̂ráʼé֑l lĕ⁠haʻàl֤wòţ ʻáláy⁠w֙ ʻòl֔wòţ kȧ⁠ká̇ţ֕ẇb bĕ̇⁠ţwòra֖ţ mòşě֥h ʼiyş̌-há⁠ʼèlòhiֽym׃"],[3,3,"וַ⁠יָּכִ֤ינוּ הַ⁠מִּזְבֵּ֨חַ֙ עַל־מְכ֣וֹנֹתָ֔י⁠ו כִּ֚י בְּ⁠אֵימָ֣ה עֲלֵי⁠הֶ֔ם מֵ⁠עַמֵּ֖י הָ⁠אֲרָצ֑וֹת ו⁠יעל עָלָ֤י⁠ו עֹלוֹת֙ לַֽ⁠יהוָ֔ה עֹל֖וֹת לַ⁠בֹּ֥קֶר וְ⁠לָ⁠עָֽרֶב׃","wa⁠yá̇ki֤ynẇ ha⁠mi̇zĕbé̇֨ẖa֙ ʻal-mĕk֣wònòţá֔y⁠w ki֚̇y bĕ̇⁠ʼéymá֣h ʻàléy⁠he֔m mé⁠ʻamé֖̇y há⁠ʼàráẕ֑wòţ w⁠yʻl ʻálá֤y⁠w ʻòlwòţ֙ laֽ⁠yhwá֔h ʻòl֖wòţ la⁠bò֥̇qer wĕ⁠lá⁠ʻáֽreb׃"],[3,4,"וַֽ⁠יַּעֲשׂ֛וּ אֶת־חַ֥ג הַ⁠סֻּכּ֖וֹת כַּ⁠כָּת֑וּב וְ⁠עֹלַ֨ת י֤וֹם בְּ⁠יוֹם֙ בְּ⁠מִסְפָּ֔ר כְּ⁠מִשְׁפַּ֖ט דְּבַר־י֥וֹם בְּ⁠יוֹמֽ⁠וֹ׃","wֽa⁠yȧʻàş֛̂ẇ ʼeţ-ẖa֥g ha⁠su̇k֖̇wòţ kȧ⁠ká̇ţ֑ẇb wĕ⁠ʻòla֨ţ y֤wòm bĕ̇⁠ywòm֙ bĕ̇⁠misĕpá̇֔r kĕ̇⁠mişĕ̌pȧ֖t dĕ̇bar-y֥wòm bĕ̇⁠ywòmֽ⁠wò׃"],[3,5,"וְ⁠אַחֲרֵי כֵ֞ן עֹלַ֤ת תָּמִיד֙ וְ⁠לֶ֣⁠חֳדָשִׁ֔ים וּ⁠לְ⁠כָל־מוֹעֲדֵ֥י יְהוָ֖ה הַ⁠מְקֻדָּשִׁ֑ים וּ⁠לְ⁠כֹ֛ל מִתְנַדֵּ֥ב נְדָבָ֖ה לַ⁠יהוָֽה׃","wĕ⁠ʼaẖàréy ké֞n ʻòla֤ţ ţá̇miyd֙ wĕ⁠le֣⁠ẖodáşǐ֔ym ẇ⁠lĕ⁠kál-mwòʻàdé֥y yĕhwá֖h ha⁠mĕqudá̇şǐ֑ym ẇ⁠lĕ⁠kò֛l miţĕnadé֥̇b nĕdábá֖h la⁠yhwáֽh׃"],[3,6,"מִ⁠יּ֤וֹם אֶחָד֙ לַ⁠חֹ֣דֶשׁ הַ⁠שְּׁבִיעִ֔י הֵחֵ֕לּוּ לְ⁠הַעֲל֥וֹת עֹל֖וֹת לַ⁠יהוָ֑ה וְ⁠הֵיכַ֥ל יְהוָ֖ה לֹ֥א יֻסָּֽד׃","mi⁠ẏ֤wòm ʼeẖád֙ la⁠ẖò֣deş̌ ha⁠şĕ̇̌biyʻi֔y héẖé֕l̇ẇ lĕ⁠haʻàl֥wòţ ʻòl֖wòţ la⁠yhwá֑h wĕ⁠héyka֥l yĕhwá֖h lò֥ʼ yusáֽ̇d׃"],[3,7,"וַ⁠יִּ֨תְּנוּ־כֶ֔סֶף לַ⁠חֹצְבִ֖ים וְ⁠לֶ⁠חָרָשִׁ֑ים וּ⁠מַאֲכָ֨ל וּ⁠מִשְׁתֶּ֜ה וָ⁠שֶׁ֗מֶן לַ⁠צִּֽדֹנִים֙ וְ⁠לַ⁠צֹּרִ֔ים לְ⁠הָבִיא֩ עֲצֵ֨י אֲרָזִ֤ים מִן־הַ⁠לְּבָנוֹן֙ אֶל־יָ֣ם יָפ֔וֹא כְּ⁠רִשְׁי֛וֹן כּ֥וֹרֶשׁ מֶֽלֶךְ־פָּרַ֖ס עֲלֵי⁠הֶֽם׃פ","wa⁠yi̇֨ţĕ̇nẇ-ke֔sep la⁠ẖòẕĕbi֖ym wĕ⁠le⁠ẖáráşǐ֑ym ẇ⁠maʼàká֨l ẇ⁠mişĕ̌ţė֜h wá⁠şě֗men la⁠ẕiֽ̇dòniym֙ wĕ⁠la⁠ẕò̇ri֔ym lĕ⁠hábiyʼ֩ ʻàẕé֨y ʼàrázi֤ym min-ha⁠lĕ̇bánwòn֙ ʼel-yá֣m yáp֔wòʼ kĕ̇⁠rişĕ̌y֛wòn k֥̇wòreş̌ meֽlekĕ-pá̇ra֖s ʻàléy⁠heֽm׃p"],[3,8,"וּ⁠בַ⁠שָּׁנָ֣ה הַ⁠שֵּׁנִ֗ית לְ⁠בוֹאָ֞⁠ם אֶל־בֵּ֤ית הָֽ⁠אֱלֹהִים֙ לִ⁠יר֣וּשָׁלִַ֔ם בַּ⁠חֹ֖דֶשׁ הַ⁠שֵּׁנִ֑י הֵחֵ֡לּוּ זְרֻבָּבֶ֣ל בֶּן־שְׁ֠אַלְתִּיאֵל וְ⁠יֵשׁ֨וּעַ בֶּן־יֽוֹצָדָ֜ק וּ⁠שְׁאָ֥ר אֲחֵי⁠הֶ֣ם ׀ הַ⁠כֹּהֲנִ֣ים וְ⁠הַ⁠לְוִיִּ֗ם וְ⁠כָל־הַ⁠בָּאִים֙ מֵ⁠הַ⁠שְּׁבִ֣י יְרֽוּשָׁלִַ֔ם וַ⁠יַּעֲמִ֣ידוּ אֶת־הַ⁠לְוִיִּ֗ם מִ⁠בֶּ֨ן עֶשְׂרִ֤ים שָׁנָה֙ וָ⁠מַ֔עְלָ⁠ה לְ⁠נַצֵּ֖חַ עַל־מְלֶ֥אכֶת בֵּית־יְהוָֽה׃פ","ẇ⁠ba⁠şá̇̌ná֣h ha⁠şé̇̌ni֗yţ lĕ⁠bwòʼá֞⁠m ʼel-bé֤̇yţ háֽ⁠ʼèlòhiym֙ li⁠yr֣ẇşá̌lia֔m bȧ⁠ẖò֖deş̌ ha⁠şé̇̌ni֑y héẖé֡l̇ẇ zĕrubá̇be֣l bėn-şĕ̌֠ʼalĕţi̇yʼél wĕ⁠yéş̌֨ẇʻa bėn-yֽwòẕádá֜q ẇ⁠şĕ̌ʼá֥r ʼàẖéy⁠he֣m ׀ ha⁠kò̇hàni֣ym wĕ⁠ha⁠lĕwiyi̇֗m wĕ⁠kál-ha⁠bá̇ʼiym֙ mé⁠ha⁠şĕ̇̌bi֣y yĕrֽẇşá̌lia֔m wa⁠yȧʻàmi֣ydẇ ʼeţ-ha⁠lĕwiyi̇֗m mi⁠bė֨n ʻeşĕ̂ri֤ym şá̌náh֙ wá⁠ma֔ʻĕlá⁠h lĕ⁠naẕé֖̇ẖa ʻal-mĕle֥ʼkeţ bé̇yţ-yĕhwáֽh׃p"],[3,9,"וַ⁠יַּעֲמֹ֣ד יֵשׁ֡וּעַ בָּנָ֣י⁠ו וְ֠⁠אֶחָי⁠ו קַדְמִיאֵ֨ל וּ⁠בָנָ֤י⁠ו בְּנֵֽי־יְהוּדָה֙ כְּ⁠אֶחָ֔ד לְ⁠נַצֵּ֛חַ עַל־עֹשֵׂ֥ה הַ⁠מְּלָאכָ֖ה בְּ⁠בֵ֣ית הָ⁠אֱלֹהִ֑ים ס בְּנֵי֙ חֵֽנָדָ֔ד בְּנֵי⁠הֶ֥ם וַ⁠אֲחֵי⁠הֶ֖ם הַ⁠לְוִיִּֽם׃","wa⁠yȧʻàmò֣d yéş̌֡ẇʻa bá̇ná֣y⁠w wĕ֠⁠ʼeẖáy⁠w qadĕmiyʼé֨l ẇ⁠báná֤y⁠w bĕ̇néֽy-yĕhẇdáh֙ kĕ̇⁠ʼeẖá֔d lĕ⁠naẕé֛̇ẖa ʻal-ʻòşé֥̂h ha⁠mĕ̇láʼká֖h bĕ̇⁠bé֣yţ há⁠ʼèlòhi֑ym s bĕ̇néy֙ ẖéֽnádá֔d bĕ̇néy⁠he֥m wa⁠ʼàẖéy⁠he֖m ha⁠lĕwiyiֽ̇m׃"],[3,10,"וְ⁠יִסְּד֥וּ הַ⁠בֹּנִ֖ים אֶת־הֵיכַ֣ל יְהוָ֑ה וַ⁠יַּעֲמִידוּ֩ הַ⁠כֹּהֲנִ֨ים מְלֻבָּשִׁ֜ים בַּ⁠חֲצֹֽצְר֗וֹת וְ⁠הַ⁠לְוִיִּ֤ם בְּנֵֽי־אָסָף֙ בַּֽ⁠מְצִלְתַּ֔יִם לְ⁠הַלֵּל֙ אֶת־יְהוָ֔ה עַל־יְדֵ֖י דָּוִ֥יד מֶֽלֶךְ־יִשְׂרָאֵֽל׃","wĕ⁠yisĕ̇d֥ẇ ha⁠bò̇ni֖ym ʼeţ-héyka֣l yĕhwá֑h wa⁠yȧʻàmiydẇ֩ ha⁠kò̇hàni֨ym mĕlubá̇şǐ֜ym bȧ⁠ẖàẕòֽẕĕr֗wòţ wĕ⁠ha⁠lĕwiyi֤̇m bĕ̇néֽy-ʼásáp֙ bȧֽ⁠mĕẕilĕţȧ֔yim lĕ⁠halé̇l֙ ʼeţ-yĕhwá֔h ʻal-yĕdé֖y dá̇wi֥yd meֽlekĕ-yişĕ̂ráʼéֽl׃"],[3,11,"וַֽ֠⁠יַּעֲנוּ בְּ⁠הַלֵּ֨ל וּ⁠בְ⁠הוֹדֹ֤ת לַֽ⁠יהוָה֙ כִּ֣י ט֔וֹב כִּֽי־לְ⁠עוֹלָ֥ם חַסְדּ֖⁠וֹ עַל־יִשְׂרָאֵ֑ל וְ⁠כָל־הָ⁠עָ֡ם הֵרִיעוּ֩ תְרוּעָ֨ה גְדוֹלָ֤ה בְ⁠הַלֵּל֙ לַֽ⁠יהוָ֔ה עַ֖ל הוּסַ֥ד בֵּית־יְהוָֽה׃ס","wֽa֠⁠yȧʻànẇ bĕ̇⁠halé̇֨l ẇ⁠bĕ⁠hwòdò֤ţ laֽ⁠yhwáh֙ ki֣̇y t֔wòb kiֽ̇y-lĕ⁠ʻwòlá֥m ẖasĕḋ֖⁠wò ʻal-yişĕ̂ráʼé֑l wĕ⁠kál-há⁠ʻá֡m hériyʻẇ֩ ţĕrẇʻá֨h gĕdwòlá֤h bĕ⁠halé̇l֙ laֽ⁠yhwá֔h ʻa֖l hẇsa֥d bé̇yţ-yĕhwáֽh׃s"],[3,12,"וְ⁠רַבִּ֡ים מֵ⁠הַ⁠כֹּהֲנִ֣ים וְ⁠הַ⁠לְוִיִּם֩ וְ⁠רָאשֵׁ֨י הָ⁠אָב֜וֹת הַ⁠זְּקֵנִ֗ים אֲשֶׁ֨ר רָא֜וּ אֶת־הַ⁠בַּ֤יִת הָֽ⁠רִאשׁוֹן֙ בְּ⁠יָסְד֔⁠וֹ זֶ֤ה הַ⁠בַּ֨יִת֙ בְּ⁠עֵ֣ינֵי⁠הֶ֔ם בֹּכִ֖ים בְּ⁠ק֣וֹל גָּד֑וֹל וְ⁠רַבִּ֛ים בִּ⁠תְרוּעָ֥ה בְ⁠שִׂמְחָ֖ה לְ⁠הָרִ֥ים קֽוֹל׃","wĕ⁠rabi̇֡ym mé⁠ha⁠kò̇hàni֣ym wĕ⁠ha⁠lĕwiyi̇m֩ wĕ⁠ráʼşé̌֨y há⁠ʼáb֜wòţ ha⁠zĕ̇qéni֗ym ʼàşě֨r ráʼ֜ẇ ʼeţ-ha⁠bȧ֤yiţ háֽ⁠riʼş̌wòn֙ bĕ̇⁠yásĕd֔⁠wò ze֤h ha⁠bȧ֨yiţ֙ bĕ̇⁠ʻé֣ynéy⁠he֔m bò̇ki֖ym bĕ̇⁠q֣wòl gá̇d֑wòl wĕ⁠rabi֛̇ym bi̇⁠ţĕrẇʻá֥h bĕ⁠şîmĕẖá֖h lĕ⁠hári֥ym qֽwòl׃"],[3,13,"וְ⁠אֵ֣ין הָ⁠עָ֗ם מַכִּירִים֙ ק֚וֹל תְּרוּעַ֣ת הַ⁠שִּׂמְחָ֔ה לְ⁠ק֖וֹל בְּכִ֣י הָ⁠עָ֑ם כִּ֣י הָ⁠עָ֗ם מְרִיעִים֙ תְּרוּעָ֣ה גְדוֹלָ֔ה וְ⁠הַ⁠קּ֥וֹל נִשְׁמַ֖ע עַד־לְ⁠מֵ⁠רָחֽוֹק׃פ","wĕ⁠ʼé֣yn há⁠ʻá֗m maki̇yriym֙ q֚wòl ţĕ̇rẇʻa֣ţ ha⁠şi̇̂mĕẖá֔h lĕ⁠q֖wòl bĕ̇ki֣y há⁠ʻá֑m ki֣̇y há⁠ʻá֗m mĕriyʻiym֙ ţĕ̇rẇʻá֣h gĕdwòlá֔h wĕ⁠ha⁠q֥̇wòl nişĕ̌ma֖ʻ ʻad-lĕ⁠mé⁠ráẖֽwòq׃p"],[4,1,"וַֽ⁠יִּשְׁמְע֔וּ צָרֵ֥י יְהוּדָ֖ה וּ⁠בִנְיָמִ֑ן כִּֽי־בְנֵ֤י הַ⁠גּוֹלָה֙ בּוֹנִ֣ים הֵיכָ֔ל לַ⁠יהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","waֽ⁠yi̇şĕ̌mĕʻ֔ẇ ẕáré֥y yĕhẇdá֖h ẇ⁠binĕyámi֑n kiֽ̇y-bĕné֤y ha⁠ġwòláh֙ ḃwòni֣ym héyká֔l la⁠yhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[4,2,"וַ⁠יִּגְּשׁ֨וּ אֶל־זְרֻבָּבֶ֜ל וְ⁠אֶל־רָאשֵׁ֣י הָֽ⁠אָב֗וֹת וַ⁠יֹּאמְר֤וּ לָ⁠הֶם֙ נִבְנֶ֣ה עִמָּ⁠כֶ֔ם כִּ֣י כָ⁠כֶ֔ם נִדְר֖וֹשׁ לֵֽ⁠אלֹהֵי⁠כֶ֑ם ו⁠לא ׀ אֲנַ֣חְנוּ זֹבְחִ֗ים מִ⁠ימֵי֙ אֵסַ֤ר חַדֹּן֙ מֶ֣לֶךְ אַשּׁ֔וּר הַ⁠מַּעֲלֶ֥ה אֹתָ֖⁠נוּ פֹּֽה׃","wa⁠yi̇gĕ̇ş̌֨ẇ ʼel-zĕrubá̇be֜l wĕ⁠ʼel-ráʼşé֣̌y hֽá⁠ʼáb֗wòţ wa⁠yò̇ʼmĕr֤ẇ lá⁠hem֙ nibĕne֣h ʻimá̇⁠ke֔m ki֣̇y ká⁠ke֔m nidĕr֖wòş̌ lֽé⁠ʼlòhéy⁠ke֑m w⁠lʼ ׀ ʼàna֣ẖĕnẇ zòbĕẖi֗ym mi⁠yméy֙ ʼésa֤r ẖadò̇n֙ me֣lekĕ ʼaş̇̌֔ẇr ha⁠mȧʻàle֥h ʼòţá֖⁠nẇ pòֽ̇h׃"],[4,3,"וַ⁠יֹּאמֶר֩ לָ⁠הֶ֨ם זְרֻבָּבֶ֜ל וְ⁠יֵשׁ֗וּעַ וּ⁠שְׁאָ֨ר רָאשֵׁ֤י הָֽ⁠אָבוֹת֙ לְ⁠יִשְׂרָאֵ֔ל לֹֽא־לָ֣⁠כֶם וָ⁠לָ֔⁠נוּ לִ⁠בְנ֥וֹת בַּ֖יִת לֵ⁠אלֹהֵ֑י⁠נוּ כִּי֩ אֲנַ֨חְנוּ יַ֜חַד נִבְנֶ֗ה לַֽ⁠יהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל כַּ⁠אֲשֶׁ֣ר צִוָּ֔⁠נוּ הַ⁠מֶּ֖לֶךְ כּ֥וֹרֶשׁ מֶֽלֶךְ־פָּרָֽס׃","wa⁠yò̇ʼmer֩ lá⁠he֨m zĕrubá̇be֜l wĕ⁠yéş̌֗ẇʻa ẇ⁠şĕ̌ʼá֨r ráʼşé֤̌y háֽ⁠ʼábwòţ֙ lĕ⁠yişĕ̂ráʼé֔l lòֽʼ-lá֣⁠kem wá⁠lá֔⁠nẇ li⁠bĕn֥wòţ bȧ֖yiţ lé⁠ʼlòhé֑y⁠nẇ ki̇y֩ ʼàna֨ẖĕnẇ ya֜ẖad nibĕne֗h laֽ⁠yhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l kȧ⁠ʼàşě֣r ẕiwá̇֔⁠nẇ ha⁠mė֖lekĕ k֥̇wòreş̌ meֽlekĕ-pá̇ráֽs׃"],[4,4,"וַ⁠יְהִי֙ עַם־הָ⁠אָ֔רֶץ מְרַפִּ֖ים יְדֵ֣י עַם־יְהוּדָ֑ה ו⁠מבלהים אוֹתָ֖⁠ם לִ⁠בְנֽוֹת׃","wa⁠yĕhiy֙ ʻam-há⁠ʼá֔reẕ mĕrapi֖̇ym yĕdé֣y ʻam-yĕhẇdá֑h w⁠mblhym ʼwòţá֖⁠m li⁠bĕnֽwòţ׃"],[4,5,"וְ⁠סֹכְרִ֧ים עֲלֵי⁠הֶ֛ם יוֹעֲצִ֖ים לְ⁠הָפֵ֣ר עֲצָתָ֑⁠ם כָּל־יְמֵ֗י כּ֚וֹרֶשׁ מֶ֣לֶךְ פָּרַ֔ס וְ⁠עַד־מַלְכ֖וּת דָּרְיָ֥וֶשׁ מֶֽלֶךְ־פָּרָֽס׃","wĕ⁠sòkĕri֧ym ʻàléy⁠he֛m ywòʻàẕi֖ym lĕ⁠hápé֣r ʻàẕáţá֑⁠m ká̇l-yĕmé֗y k֚̇wòreş̌ me֣lekĕ pá̇ra֔s wĕ⁠ʻad-malĕk֖ẇţ dá̇rĕyá֥weş̌ meֽlekĕ-pá̇ráֽs׃"],[4,6,"וּ⁠בְ⁠מַלְכוּת֙ אֲחַשְׁוֵר֔וֹשׁ בִּ⁠תְחִלַּ֖ת מַלְכוּת֑⁠וֹ כָּתְב֣וּ שִׂטְנָ֔ה עַל־יֹשְׁבֵ֥י יְהוּדָ֖ה וִ⁠ירוּשָׁלִָֽם׃ס","ẇ⁠bĕ⁠malĕkẇţ֙ ʼàẖaşĕ̌wér֔wòş̌ bi̇⁠ţĕẖilȧ֖ţ malĕkẇţ֑⁠wò ká̇ţĕb֣ẇ şîtĕná֔h ʻal-yòşĕ̌bé֥y yĕhẇdá֖h wi⁠yrẇşá̌liáֽm׃s"],[4,7,"וּ⁠בִ⁠ימֵ֣י אַרְתַּחְשַׁ֗שְׂתָּא כָּתַ֨ב בִּשְׁלָ֜ם מִתְרְדָ֤ת טָֽבְאֵל֙ וּ⁠שְׁאָ֣ר כנותו עַל־ארתחששתא מֶ֣לֶךְ פָּרָ֑ס וּ⁠כְתָב֙ הַֽ⁠נִּשְׁתְּוָ֔ן כָּת֥וּב אֲרָמִ֖ית וּ⁠מְתֻרְגָּ֥ם אֲרָמִֽית׃פ","ẇ⁠bi⁠ymé֣y ʼarĕţȧẖĕşǎ֗şĕ̂ţá̇ʼ ká̇ţa֨b bi̇şĕ̌lá֜m miţĕrĕdá֤ţ táֽbĕʼél֙ ẇ⁠şĕ̌ʼá֣r knwţw ʻal-ʼrţẖşşţʼ me֣lekĕ pá̇rá֑s ẇ⁠kĕţáb֙ haֽ⁠ni̇şĕ̌ţĕ̇wá֔n ká̇ţ֥ẇb ʼàrámi֖yţ ẇ⁠mĕţurĕgá֥̇m ʼàrámiֽyţ׃p"],[4,8,"רְח֣וּם בְּעֵל־טְעֵ֗ם וְ⁠שִׁמְשַׁי֙ סָֽפְרָ֔⁠א כְּתַ֛בוּ אִגְּרָ֥ה חֲדָ֖ה עַל־יְרוּשְׁלֶ֑ם לְ⁠אַרְתַּחְשַׁ֥שְׂתְּא מַלְכָּ֖⁠א כְּנֵֽמָא׃","rĕẖ֣ẇm bĕ̇ʻél-tĕʻé֗m wĕ⁠şǐmĕşǎy֙ sáֽpĕrá֔⁠ʼ kĕ̇ţa֛bẇ ʼigĕ̇rá֥h ẖàdá֖h ʻal-yĕrẇşĕ̌le֑m lĕ⁠ʼarĕţȧẖĕşǎ֥şĕ̂ţĕ̇ʼ malĕká֖̇⁠ʼ kĕ̇néֽmáʼ׃"],[4,9,"אֱדַ֜יִן רְח֣וּם בְּעֵל־טְעֵ֗ם וְ⁠שִׁמְשַׁי֙ סָֽפְרָ֔⁠א וּ⁠שְׁאָ֖ר כְּנָוָתְ⁠ה֑וֹן דִּ֠ינָיֵ⁠א וַ⁠אֲפַרְסַתְכָיֵ֞⁠א טַרְפְּלָיֵ֣⁠א אֲפָֽרְסָיֵ֗⁠א ארכוי בָבְלָיֵ⁠א֙ שֽׁוּשַׁנְכָיֵ֔⁠א ד⁠הוא עֵלְמָיֵֽ⁠א׃","ʼèda֜yin rĕẖ֣ẇm bĕ̇ʻél-tĕʻé֗m wĕ⁠şǐmĕşǎy֙ sáֽpĕrá֔⁠ʼ ẇ⁠şĕ̌ʼá֖r kĕ̇náwáţĕ⁠h֑wòn di̇֠ynáyé⁠ʼ wa⁠ʼàparĕsaţĕkáyé֞⁠ʼ tarĕpĕ̇láyé֣⁠ʼ ʼàpáֽrĕsáyé֗⁠ʼ ʼrkwy bábĕláyé⁠ʼ֙ şֽ̌ẇşǎnĕkáyé֔⁠ʼ d⁠hwʼ ʻélĕmáyéֽ⁠ʼ׃"],[4,10,"וּ⁠שְׁאָ֣ר אֻמַּיָּ֗⁠א דִּ֤י הַגְלִי֙ אָסְנַפַּר֙ רַבָּ֣⁠א וְ⁠יַקִּירָ֔⁠א וְ⁠הוֹתֵ֣ב הִמּ֔וֹ בְּ⁠קִרְיָ֖ה דִּ֣י שָׁמְרָ֑יִן וּ⁠שְׁאָ֥ר עֲבַֽר־נַהֲרָ֖⁠ה וּ⁠כְעֶֽנֶת׃","ẇ⁠şĕ̌ʼá֣r ʼumȧyá̇֗⁠ʼ di֤̇y hagĕliy֙ ʼásĕnapȧr֙ rabá֣̇⁠ʼ wĕ⁠yaqi̇yrá֔⁠ʼ wĕ⁠hwòţé֣b hiṁ֔wò bĕ̇⁠qirĕyá֖h di֣̇y şá̌mĕrá֑yin ẇ⁠şĕ̌ʼá֥r ʻàbaֽr-nahàrá֖⁠h ẇ⁠kĕʻeֽneţ׃"],[4,11,"דְּנָה֙ פַּרְשֶׁ֣גֶן אִגַּרְתָּ֔⁠א דִּ֚י שְׁלַ֣חוּ עֲל֔וֹ⁠הִי עַל־אַרְתַּחְשַׁ֖שְׂתְּא מַלְכָּ֑⁠א עַבְדָ֛י⁠ךְ אֱנָ֥שׁ עֲבַֽר־נַהֲרָ֖⁠ה וּ⁠כְעֶֽנֶת׃פ","dĕ̇náh֙ pȧrĕşě֣gen ʼigȧrĕţá̇֔⁠ʼ di֚̇y şĕ̌la֣ẖẇ ʻàl֔wò⁠hiy ʻal-ʼarĕţȧẖĕşǎ֖şĕ̂ţĕ̇ʼ malĕká֑̇⁠ʼ ʻabĕdá֛y⁠kĕ ʼèná֥ş̌ ʻàbaֽr-nahàrá֖⁠h ẇ⁠kĕʻeֽneţ׃p"],[4,12,"יְדִ֨יעַ֙ לֶהֱוֵ֣א לְ⁠מַלְכָּ֔⁠א דִּ֣י יְהוּדָיֵ֗⁠א דִּ֤י סְלִ֨קוּ֙ מִן־לְוָתָ֔⁠ךְ עֲלֶ֥י⁠נָא אֲת֖וֹ לִ⁠ירוּשְׁלֶ֑ם קִרְיְתָ֨⁠א מָֽרָדְתָּ֤⁠א ו⁠באישת⁠א בָּנַ֔יִן ו⁠שורי אשכללו וְ⁠אֻשַּׁיָּ֖⁠א יַחִֽיטוּ׃","yĕdi֨yʻa֙ lehèwé֣ʼ lĕ⁠malĕká̇֔⁠ʼ di֣̇y yĕhẇdáyé֗⁠ʼ di֤̇y sĕli֨qẇ֙ min-lĕwáţá֔⁠kĕ ʻàle֥y⁠náʼ ʼàţ֖wò li⁠yrẇşĕ̌le֑m qirĕyĕţá֨⁠ʼ máֽrádĕţá֤̇⁠ʼ w⁠bʼyşţ⁠ʼ bá̇na֔yin w⁠şwry ʼşkllw wĕ⁠ʼuşȧ̌yá֖̇⁠ʼ yaẖiֽytẇ׃"],[4,13,"כְּעַ֗ן יְדִ֨יעַ֙ לֶהֱוֵ֣א לְ⁠מַלְכָּ֔⁠א דִּ֠י הֵ֣ן קִרְיְתָ֥⁠א דָךְ֙ תִּתְבְּנֵ֔א וְ⁠שׁוּרַיָּ֖⁠ה יִֽשְׁתַּכְלְל֑וּן מִנְדָּֽה־בְל֤וֹ וַ⁠הֲלָךְ֙ לָ֣א יִנְתְּנ֔וּן וְ⁠אַפְּתֹ֥ם מַלְכִ֖ים תְּהַנְזִֽק׃","kĕ̇ʻa֗n yĕdi֨yʻa֙ lehèwé֣ʼ lĕ⁠malĕká̇֔⁠ʼ di̇֠y hé֣n qirĕyĕţá֥⁠ʼ dákĕ֙ ţi̇ţĕbĕ̇né֔ʼ wĕ⁠ş̌ẇrayá֖̇⁠h yiֽşĕ̌ţȧkĕlĕl֑ẇn minĕdáֽ̇h-bĕl֤wò wa⁠hàlákĕ֙ lá֣ʼ yinĕţĕ̇n֔ẇn wĕ⁠ʼapĕ̇ţò֥m malĕki֖ym ţĕ̇hanĕziֽq׃"],[4,14,"כְּעַ֗ן כָּ⁠ל־קֳבֵל֙ דִּֽי־מְלַ֤ח הֵֽיכְלָ⁠א֙ מְלַ֔חְנָא וְ⁠עַרְוַ֣ת מַלְכָּ֔⁠א לָ֥א אֲֽרִֽיךְ לַ֖⁠נָא לְ⁠מֶֽחֱזֵ֑א עַ֨ל־דְּנָ֔ה שְׁלַ֖חְנָא וְ⁠הוֹדַ֥עְנָא לְ⁠מַלְכָּֽ⁠א׃","kĕ̇ʻa֗n ká̇⁠l-qobél֙ diֽ̇y-mĕla֤ẖ héֽykĕlá⁠ʼ֙ mĕla֔ẖĕnáʼ wĕ⁠ʻarĕwa֣ţ malĕká̇֔⁠ʼ lá֥ʼ ʼàֽriֽykĕ la֖⁠náʼ lĕ⁠meֽẖèzé֑ʼ ʻa֨l-dĕ̇ná֔h şĕ̌la֖ẖĕnáʼ wĕ⁠hwòda֥ʻĕnáʼ lĕ⁠malĕkáֽ̇⁠ʼ׃"],[4,15,"דִּ֡י יְבַקַּר֩ בִּֽ⁠סְפַר־דָּכְרָ֨נַיָּ֜⁠א דִּ֣י אֲבָהָתָ֗⁠ךְ וּ֠⁠תְהַשְׁכַּח בִּ⁠סְפַ֣ר דָּכְרָנַיָּ⁠א֮ וְ⁠תִנְדַּע֒ דִּי֩ קִרְיְתָ֨⁠א דָ֜ךְ קִרְיָ֣א מָֽרָדָ֗א וּֽ⁠מְהַנְזְקַ֤ת מַלְכִין֙ וּ⁠מְדִנָ֔ן וְ⁠אֶשְׁתַּדּוּר֙ עָבְדִ֣ין בְּ⁠גַוַּ֔⁠הּ מִן־יוֹמָ֖ת עָלְמָ֑⁠א עַ֨ל־דְּנָ֔ה קִרְיְתָ֥⁠א דָ֖ךְ הָֽחָרְבַֽת׃","di̇֡y yĕbaqȧr֩ biֽ̇⁠sĕpar-dá̇kĕrá֨nayá̇֜⁠ʼ di֣̇y ʼàbáháţá֗⁠kĕ ẇ֠⁠ţĕhaşĕ̌kȧẖ bi̇⁠sĕpa֣r dá̇kĕránayá̇⁠ʼ֮ wĕ⁠ţinĕdȧʻ֒ di̇y֩ qirĕyĕţá֨⁠ʼ dá֜kĕ qirĕyá֣ʼ máֽrádá֗ʼ ẇֽ⁠mĕhanĕzĕqa֤ţ malĕkiyn֙ ẇ⁠mĕdiná֔n wĕ⁠ʼeşĕ̌ţȧḋẇr֙ ʻábĕdi֣yn bĕ̇⁠gawȧ֔⁠ḣ min-ywòmá֖ţ ʻálĕmá֑⁠ʼ ʻa֨l-dĕ̇ná֔h qirĕyĕţá֥⁠ʼ dá֖kĕ háֽẖárĕbaֽţ׃"],[4,16,"מְהוֹדְעִ֤ין אֲנַ֨חְנָה֙ לְ⁠מַלְכָּ֔⁠א דִּ֠י הֵ֣ן קִרְיְתָ֥⁠א דָךְ֙ תִּתְבְּנֵ֔א וְ⁠שׁוּרַיָּ֖⁠ה יִֽשְׁתַּכְלְל֑וּן לָ⁠קֳבֵ֣ל דְּנָ֔ה חֲלָק֙ בַּ⁠עֲבַ֣ר נַהֲרָ֔⁠א לָ֥א אִיתַ֖י לָֽ⁠ךְ׃פ","mĕhwòdĕʻi֤yn ʼàna֨ẖĕnáh֙ lĕ⁠malĕká̇֔⁠ʼ di̇֠y hé֣n qirĕyĕţá֥⁠ʼ dákĕ֙ ţi̇ţĕbĕ̇né֔ʼ wĕ⁠ş̌ẇrayá֖̇⁠h yiֽşĕ̌ţȧkĕlĕl֑ẇn lá⁠qobé֣l dĕ̇ná֔h ẖàláq֙ bȧ⁠ʻàba֣r nahàrá֔⁠ʼ lá֥ʼ ʼiyţa֖y láֽ⁠kĕ׃p"],[4,17,"פִּתְגָמָ֞⁠א שְׁלַ֣ח מַלְכָּ֗⁠א עַל־רְח֤וּם בְּעֵל־טְעֵם֙ וְ⁠שִׁמְשַׁ֣י סָֽפְרָ֔⁠א וּ⁠שְׁאָר֙ כְּנָוָ֣תְ⁠ה֔וֹן דִּ֥י יָתְבִ֖ין בְּ⁠שָֽׁמְרָ֑יִן וּ⁠שְׁאָ֧ר עֲבַֽר־נַהֲרָ֛⁠ה שְׁלָ֖ם וּ⁠כְעֶֽת׃ס","pi̇ţĕgámá֞⁠ʼ şĕ̌la֣ẖ malĕká̇֗⁠ʼ ʻal-rĕẖ֤ẇm bĕ̇ʻél-tĕʻém֙ wĕ⁠şǐmĕşǎ֣y sáֽpĕrá֔⁠ʼ ẇ⁠şĕ̌ʼár֙ kĕ̇náwá֣ţĕ⁠h֔wòn di֥̇y yáţĕbi֖yn bĕ̇⁠şáֽ̌mĕrá֑yin ẇ⁠şĕ̌ʼá֧r ʻàbaֽr-nahàrá֛⁠h şĕ̌lá֖m ẇ⁠kĕʻeֽţ׃s"],[4,18,"נִשְׁתְּוָנָ֕⁠א דִּ֥י שְׁלַחְתּ֖וּן עֲלֶ֑י⁠נָא מְפָרַ֥שׁ קֱרִ֖י קָדָמָֽ⁠י׃","nişĕ̌ţĕ̇wáná֕⁠ʼ di֥̇y şĕ̌laẖĕţ֖̇ẇn ʻàle֑y⁠náʼ mĕpára֥ş̌ qèri֖y qádámáֽ⁠y׃"],[4,19,"וּ⁠מִנִּ⁠י֮ שִׂ֣ים טְעֵם֒ וּ⁠בַקַּ֣רוּ וְ⁠הַשְׁכַּ֔חוּ דִּ֚י קִרְיְתָ֣⁠א דָ֔ךְ מִן־יוֹמָת֙ עָֽלְמָ֔⁠א עַל־מַלְכִ֖ין מִֽתְנַשְּׂאָ֑ה וּ⁠מְרַ֥ד וְ⁠אֶשְׁתַּדּ֖וּר מִתְעֲבֶד־בַּֽ⁠הּ׃","ẇ⁠mini̇⁠y֮ şî֣ym tĕʻém֒ ẇ⁠baqȧ֣rẇ wĕ⁠haşĕ̌kȧ֔ẖẇ di֚̇y qirĕyĕţá֣⁠ʼ dá֔kĕ min-ywòmáţ֙ ʻֽálĕmá֔⁠ʼ ʻal-malĕki֖yn miֽţĕnaşĕ̇̂ʼá֑h ẇ⁠mĕra֥d wĕ⁠ʼeşĕ̌ţȧḋ֖ẇr miţĕʻàbed-bȧֽ⁠ḣ׃"],[4,20,"וּ⁠מַלְכִ֣ין תַּקִּיפִ֗ין הֲווֹ֙ עַל־יְר֣וּשְׁלֶ֔ם וְ⁠שַׁ֨לִּיטִ֔ין בְּ⁠כֹ֖ל עֲבַ֣ר נַהֲרָ֑⁠ה וּ⁠מִדָּ֥ה בְל֛וֹ וַ⁠הֲלָ֖ךְ מִתְיְהֵ֥ב לְ⁠הֽוֹן׃","ẇ⁠malĕki֣yn ţȧqi̇ypi֗yn hàwwò֙ ʻal-yĕr֣ẇşĕ̌le֔m wĕ⁠şǎ֨li̇yti֔yn bĕ̇⁠kò֖l ʻàba֣r nahàrá֑⁠h ẇ⁠midá֥̇h bĕl֛wò wa⁠hàlá֖kĕ miţĕyĕhé֥b lĕ⁠hֽwòn׃"],[4,21,"כְּעַן֙ שִׂ֣ימוּ טְּעֵ֔ם לְ⁠בַטָּלָ֖א גֻּבְרַיָּ֣⁠א אִלֵּ֑ךְ וְ⁠קִרְיְתָ֥⁠א דָךְ֙ לָ֣א תִתְבְּנֵ֔א עַד־מִנִּ֖⁠י טַעְמָ֥⁠א יִתְּשָֽׂם׃","kĕ̇ʻan֙ şî֣ymẇ tĕ̇ʻé֔m lĕ⁠batá̇lá֖ʼ gu̇bĕrayá֣̇⁠ʼ ʼilé֑̇kĕ wĕ⁠qirĕyĕţá֥⁠ʼ dákĕ֙ lá֣ʼ ţiţĕbĕ̇né֔ʼ ʻad-mini֖̇⁠y taʻĕmá֥⁠ʼ yiţĕ̇şáֽ̂m׃"],[4,22,"וּ⁠זְהִירִ֥ין הֱו֛וֹ שָׁל֖וּ לְ⁠מֶעְבַּ֣ד עַל־דְּנָ֑ה לְ⁠מָה֙ יִשְׂגֵּ֣א חֲבָלָ֔⁠א לְ⁠הַנְזָקַ֖ת מַלְכִֽין׃ס","ẇ⁠zĕhiyri֥yn hèw֛wò şá̌l֖ẇ lĕ⁠meʻĕbȧ֣d ʻal-dĕ̇ná֑h lĕ⁠máh֙ yişĕ̂gé֣̇ʼ ẖàbálá֔⁠ʼ lĕ⁠hanĕzáqa֖ţ malĕkiֽyn׃s"],[4,23,"אֱדַ֗יִן מִן־דִּ֞י פַּרְשֶׁ֤גֶן נִשְׁתְּוָנָ⁠א֙ דִּ֚י ארתחששתא מַלְכָּ֔⁠א קֱרִ֧י קֳדָם־רְח֛וּם וְ⁠שִׁמְשַׁ֥י סָפְרָ֖⁠א וּ⁠כְנָוָתְ⁠ה֑וֹן אֲזַ֨לוּ בִ⁠בְהִיל֤וּ לִ⁠ירֽוּשְׁלֶם֙ עַל־יְה֣וּדָיֵ֔⁠א וּ⁠בַטִּ֥לוּ הִמּ֖וֹ בְּ⁠אֶדְרָ֥ע וְ⁠חָֽיִל׃ס","ʼèda֗yin min-di̇֞y pȧrĕşě֤gen nişĕ̌ţĕ̇wáná⁠ʼ֙ di֚̇y ʼrţẖşşţʼ malĕká̇֔⁠ʼ qèri֧y qodám-rĕẖ֛ẇm wĕ⁠şǐmĕşǎ֥y sápĕrá֖⁠ʼ ẇ⁠kĕnáwáţĕ⁠h֑wòn ʼàza֨lẇ bi⁠bĕhiyl֤ẇ li⁠yrֽẇşĕ̌lem֙ ʻal-yĕh֣ẇdáyé֔⁠ʼ ẇ⁠bati֥̇lẇ hiṁ֖wò bĕ̇⁠ʼedĕrá֥ʻ wĕ⁠ẖáֽyil׃s"],[4,24,"בֵּ⁠אדַ֗יִן בְּטֵלַת֙ עֲבִידַ֣ת בֵּית־אֱלָהָ֔⁠א דִּ֖י בִּ⁠ירוּשְׁלֶ֑ם וַ⁠הֲוָת֙ בָּֽטְלָ֔א עַ֚ד שְׁנַ֣ת תַּרְתֵּ֔ין לְ⁠מַלְכ֖וּת דָּרְיָ֥וֶשׁ מֶֽלֶךְ־פָּרָֽס׃פ","bé̇⁠ʼda֗yin bĕ̇télaţ֙ ʻàbiyda֣ţ bé̇yţ-ʼèláhá֔⁠ʼ di֖̇y bi̇⁠yrẇşĕ̌le֑m wa⁠hàwáţ֙ báֽ̇tĕlá֔ʼ ʻa֚d şĕ̌na֣ţ ţȧrĕţé̇֔yn lĕ⁠malĕk֖ẇţ dá̇rĕyá֥weş̌ meֽlekĕ-pá̇ráֽs׃p"],[5,1,"וְ⁠הִתְנַבִּ֞י חַגַּ֣י נביא⁠ה וּ⁠זְכַרְיָ֤ה בַר־עִדּוֹא֙ נביאי⁠א עַל־יְה֣וּדָיֵ֔⁠א דִּ֥י בִ⁠יה֖וּד וּ⁠בִ⁠ירוּשְׁלֶ֑ם בְּ⁠שֻׁ֛ם אֱלָ֥הּ יִשְׂרָאֵ֖ל עֲלֵי⁠הֽוֹן׃ס","wĕ⁠hiţĕnabi̇֞y ẖagȧ֣y nbyʼ⁠h ẇ⁠zĕkarĕyá֤h bar-ʻiḋwòʼ֙ nbyʼy⁠ʼ ʻal-yĕh֣ẇdáyé֔⁠ʼ di֥̇y bi⁠yh֖ẇd ẇ⁠bi⁠yrẇşĕ̌le֑m bĕ̇⁠şǔ֛m ʼèlá֥ḣ yişĕ̂ráʼé֖l ʻàléy⁠hֽwòn׃s"],[5,2,"בֵּ⁠אדַ֡יִן קָ֠מוּ זְרֻבָּבֶ֤ל בַּר־שְׁאַלְתִּיאֵל֙ וְ⁠יֵשׁ֣וּעַ בַּר־יֽוֹצָדָ֔ק וְ⁠שָׁרִ֣יו לְ⁠מִבְנֵ֔א בֵּ֥ית אֱלָהָ֖⁠א דִּ֣י בִ⁠ירֽוּשְׁלֶ֑ם וְ⁠עִמְּ⁠ה֛וֹן נביאי⁠א דִֽי־אֱלָהָ֖⁠א מְסָעֲדִ֥ין לְ⁠הֽוֹן׃פ","bé̇⁠ʼda֡yin qá֠mẇ zĕrubá̇be֤l bȧr-şĕ̌ʼalĕţi̇yʼél֙ wĕ⁠yéş֣̌ẇʻa bȧr-yֽwòẕádá֔q wĕ⁠şá̌ri֣yw lĕ⁠mibĕné֔ʼ bé֥̇yţ ʼèláhá֖⁠ʼ di֣̇y bi⁠yrֽẇşĕ̌le֑m wĕ⁠ʻimĕ̇⁠h֛wòn nbyʼy⁠ʼ diֽy-ʼèláhá֖⁠ʼ mĕsáʻàdi֥yn lĕ⁠hֽwòn׃p"],[5,3,"בֵּ⁠הּ־זִמְנָ⁠א֩ אֲתָ֨א עֲלֵי⁠ה֜וֹן תַּ֠תְּנַי פַּחַ֧ת עֲבַֽר־נַהֲרָ֛⁠ה וּ⁠שְׁתַ֥ר בּוֹזְנַ֖י וּ⁠כְנָוָתְ⁠ה֑וֹן וְ⁠כֵן֙ אָמְרִ֣ין לְ⁠הֹ֔ם מַן־שָׂ֨ם לְ⁠כֹ֜ם טְעֵ֗ם בַּיְתָ֤⁠א דְנָה֙ לִ⁠בְּנֵ֔א וְ⁠אֻשַּׁרְנָ֥⁠א דְנָ֖ה לְ⁠שַׁכְלָלָֽה׃ס","bé̇⁠ḣ-zimĕná⁠ʼ֩ ʼàţá֨ʼ ʻàléy⁠h֜wòn ţȧ֠ţĕ̇nay pȧẖa֧ţ ʻàbaֽr-nahàrá֛⁠h ẇ⁠şĕ̌ţa֥r ḃwòzĕna֖y ẇ⁠kĕnáwáţĕ⁠h֑wòn wĕ⁠kén֙ ʼámĕri֣yn lĕ⁠hò֔m man-şá̂֨m lĕ⁠kò֜m tĕʻé֗m bȧyĕţá֤⁠ʼ dĕnáh֙ li⁠bĕ̇né֔ʼ wĕ⁠ʼuşȧ̌rĕná֥⁠ʼ dĕná֖h lĕ⁠şǎkĕláláֽh׃s"],[5,4,"אֱדַ֥יִן כְּנֵ֖מָא אֲמַ֣רְנָא לְּ⁠הֹ֑ם מַן־אִנּוּן֙ שְׁמָהָ֣ת גֻּבְרַיָּ֔⁠א דִּֽי־דְנָ֥ה בִנְיָנָ֖⁠א בָּנַֽיִן׃","ʼèda֥yin kĕ̇né֖máʼ ʼàma֣rĕnáʼ lĕ̇⁠hò֑m man-ʼiṅẇn֙ şĕ̌máhá֣ţ gu̇bĕrayá̇֔⁠ʼ diֽ̇y-dĕná֥h binĕyáná֖⁠ʼ bá̇naֽyin׃"],[5,5,"וְ⁠עֵ֣ין אֱלָהֲ⁠הֹ֗ם הֲוָת֙ עַל־שָׂבֵ֣י יְהוּדָיֵ֔⁠א וְ⁠לָא־בַטִּ֣לוּ הִמּ֔וֹ עַד־טַעְמָ֖⁠א לְ⁠דָרְיָ֣וֶשׁ יְהָ֑ךְ וֶ⁠אֱדַ֛יִן יְתִיב֥וּן נִשְׁתְּוָנָ֖⁠א עַל־דְּנָֽה׃פ","wĕ⁠ʻé֣yn ʼèláhà⁠hò֗m hàwáţ֙ ʻal-şá̂bé֣y yĕhẇdáyé֔⁠ʼ wĕ⁠láʼ-bati֣̇lẇ hiṁ֔wò ʻad-taʻĕmá֖⁠ʼ lĕ⁠dárĕyá֣weş̌ yĕhá֑kĕ we⁠ʼèda֛yin yĕţiyb֥ẇn nişĕ̌ţĕ̇wáná֖⁠ʼ ʻal-dĕ̇náֽh׃p"],[5,6,"פַּרְשֶׁ֣גֶן אִ֠גַּרְתָּ⁠א דִּֽי־שְׁלַ֞ח תַּתְּנַ֣י ׀ פַּחַ֣ת עֲבַֽר־נַהֲרָ֗⁠ה וּ⁠שְׁתַ֤ר בּוֹזְנַי֙ וּ⁠כְנָ֣וָתֵ֔⁠הּ אֲפַ֨רְסְכָיֵ֔⁠א דִּ֖י בַּ⁠עֲבַ֣ר נַהֲרָ֑⁠ה עַל־דָּרְיָ֖וֶשׁ מַלְכָּֽ⁠א׃","pȧrĕşě֣gen ʼi֠gȧrĕţá̇⁠ʼ diֽ̇y-şĕ̌la֞ẖ ţȧţĕ̇na֣y ׀ pȧẖa֣ţ ʻàbaֽr-nahàrá֗⁠h ẇ⁠şĕ̌ţa֤r ḃwòzĕnay֙ ẇ⁠kĕná֣wáţé֔⁠ḣ ʼàpa֨rĕsĕkáyé֔⁠ʼ di֖̇y bȧ⁠ʻàba֣r nahàrá֑⁠h ʻal-dá̇rĕyá֖weş̌ malĕkáֽ̇⁠ʼ׃"],[5,7,"פִּתְגָמָ֖⁠א שְׁלַ֣חוּ עֲל֑וֹ⁠הִי וְ⁠כִ⁠דְנָה֙ כְּתִ֣יב בְּ⁠גַוֵּ֔⁠הּ לְ⁠דָרְיָ֥וֶשׁ מַלְכָּ֖⁠א שְׁלָמָ֥⁠א כֹֽלָּ⁠א׃ס","pi̇ţĕgámá֖⁠ʼ şĕ̌la֣ẖẇ ʻàl֑wò⁠hiy wĕ⁠ki⁠dĕnáh֙ kĕ̇ţi֣yb bĕ̇⁠gawé̇֔⁠ḣ lĕ⁠dárĕyá֥weş̌ malĕká֖̇⁠ʼ şĕ̌lámá֥⁠ʼ kòֽlá̇⁠ʼ׃s"],[5,8,"יְדִ֣יעַ ׀ לֶהֱוֵ֣א לְ⁠מַלְכָּ֗⁠א דִּֽי־אֲזַ֜לְנָא לִ⁠יה֤וּד מְדִֽינְתָּ⁠א֙ לְ⁠בֵית֙ אֱלָהָ֣⁠א רַבָּ֔⁠א וְ⁠ה֤וּא מִתְבְּנֵא֙ אֶ֣בֶן גְּלָ֔ל וְ⁠אָ֖ע מִתְּשָׂ֣ם בְּ⁠כֻתְלַיָּ֑⁠א וַ⁠עֲבִ֥ידְתָּ⁠א דָ֛ךְ אָסְפַּ֥רְנָא מִתְעַבְדָ֖א וּ⁠מַצְלַ֥ח בְּ⁠יֶדְ⁠הֹֽם׃ס","yĕdi֣yʻa ׀ lehèwé֣ʼ lĕ⁠malĕká̇֗⁠ʼ diֽ̇y-ʼàza֜lĕnáʼ li⁠yh֤ẇd mĕdiֽynĕţá̇⁠ʼ֙ lĕ⁠béyţ֙ ʼèláhá֣⁠ʼ rabá̇֔⁠ʼ wĕ⁠h֤ẇʼ miţĕbĕ̇néʼ֙ ʼe֣ben gĕ̇lá֔l wĕ⁠ʼá֖ʻ miţĕ̇şá֣̂m bĕ̇⁠kuţĕlayá֑̇⁠ʼ wa⁠ʻàbi֥ydĕţá̇⁠ʼ dá֛kĕ ʼásĕpȧ֥rĕnáʼ miţĕʻabĕdá֖ʼ ẇ⁠maẕĕla֥ẖ bĕ̇⁠yedĕ⁠hòֽm׃s"],[5,9,"אֱדַ֗יִן שְׁאֵ֨לְנָא֙ לְ⁠שָׂבַיָּ֣⁠א אִלֵּ֔ךְ כְּנֵ֖מָא אֲמַ֣רְנָא לְּ⁠הֹ֑ם מַן־שָׂ֨ם לְ⁠כֹ֜ם טְעֵ֗ם בַּיְתָ֤⁠א דְנָה֙ לְ⁠מִבְנְיָ֔ה וְ⁠אֻשַּׁרְנָ֥⁠א דְנָ֖ה לְ⁠שַׁכְלָלָֽה׃","ʼèda֗yin şĕ̌ʼé֨lĕnáʼ֙ lĕ⁠şá̂bayá֣̇⁠ʼ ʼilé̇֔kĕ kĕ̇né֖máʼ ʼàma֣rĕnáʼ lĕ̇⁠hò֑m man-şá̂֨m lĕ⁠kò֜m tĕʻé֗m bȧyĕţá֤⁠ʼ dĕnáh֙ lĕ⁠mibĕnĕyá֔h wĕ⁠ʼuşȧ̌rĕná֥⁠ʼ dĕná֖h lĕ⁠şǎkĕláláֽh׃"],[5,10,"וְ⁠אַ֧ף שְׁמָהָתְ⁠הֹ֛ם שְׁאֵ֥לְנָא לְּ⁠הֹ֖ם לְ⁠הוֹדָעוּתָ֑⁠ךְ דִּ֛י נִכְתֻּ֥ב שֻׁם־גֻּבְרַיָּ֖⁠א דִּ֥י בְ⁠רָאשֵׁי⁠הֹֽם׃ס","wĕ⁠ʼa֧p şĕ̌máháţĕ⁠hò֛m şĕ̌ʼé֥lĕnáʼ lĕ̇⁠hò֖m lĕ⁠hwòdáʻẇţá֑⁠kĕ di֛̇y nikĕţu֥̇b şǔm-gu̇bĕrayá֖̇⁠ʼ di֥̇y bĕ⁠ráʼşé̌y⁠hòֽm׃s"],[5,11,"וּ⁠כְנֵ֥מָא פִתְגָמָ֖⁠א הֲתִיב֣וּ⁠נָא לְ⁠מֵמַ֑ר אֲנַ֣חְנָא הִמּ֡וֹ עַבְדוֹ⁠הִי֩ דִֽי־אֱלָ֨הּ שְׁמַיָּ֜⁠א וְ⁠אַרְעָ֗⁠א וּ⁠בָנַ֤יִן בַּיְתָ⁠א֙ דִּֽי־הֲוָ֨א בְנֵ֜ה מִ⁠קַּדְמַ֤ת דְּנָה֙ שְׁנִ֣ין שַׂגִּיאָ֔ן וּ⁠מֶ֤לֶךְ לְ⁠יִשְׂרָאֵל֙ רַ֔ב בְּנָ֖⁠הִי וְ⁠שַׁכְלְלֵֽ⁠הּ׃","ẇ⁠kĕné֥máʼ piţĕgámá֖⁠ʼ hàţiyb֣ẇ⁠náʼ lĕ⁠méma֑r ʼàna֣ẖĕnáʼ hiṁ֡wò ʻabĕdwò⁠hiy֩ diֽy-ʼèlá֨ḣ şĕ̌mayá̇֜⁠ʼ wĕ⁠ʼarĕʻá֗⁠ʼ ẇ⁠bána֤yin bȧyĕţá⁠ʼ֙ diֽ̇y-hàwá֨ʼ bĕné֜h mi⁠qȧdĕma֤ţ dĕ̇náh֙ şĕ̌ni֣yn şâgi̇yʼá֔n ẇ⁠me֤lekĕ lĕ⁠yişĕ̂ráʼél֙ ra֔b bĕ̇ná֖⁠hiy wĕ⁠şǎkĕlĕléֽ⁠ḣ׃"],[5,12,"לָהֵ֗ן מִן־דִּ֨י הַרְגִּ֤זוּ אֲבָהֳתַ֨⁠נָא֙ לֶ⁠אֱלָ֣הּ שְׁמַיָּ֔⁠א יְהַ֣ב הִמּ֔וֹ בְּ⁠יַ֛ד נְבוּכַדְנֶצַּ֥ר מֶֽלֶךְ־בָּבֶ֖ל כסדי⁠א וּ⁠בַיְתָ֤⁠ה דְנָה֙ סַתְרֵ֔⁠הּ וְ⁠עַמָּ֖⁠ה הַגְלִ֥י לְ⁠בָבֶֽל׃ס","láhé֗n min-di̇֨y harĕgi֤̇zẇ ʼàbáhoţa֨⁠náʼ֙ le⁠ʼèlá֣ḣ şĕ̌mayá̇֔⁠ʼ yĕha֣b hiṁ֔wò bĕ̇⁠ya֛d nĕbẇkadĕneẕȧ֥r meֽlekĕ-bá̇be֖l ksdy⁠ʼ ẇ⁠bayĕţá֤⁠h dĕnáh֙ saţĕré֔⁠ḣ wĕ⁠ʻamá֖̇⁠h hagĕli֥y lĕ⁠bábeֽl׃s"],[5,13,"בְּרַם֙ בִּ⁠שְׁנַ֣ת חֲדָ֔ה לְ⁠כ֥וֹרֶשׁ מַלְכָּ֖⁠א דִּ֣י בָבֶ֑ל כּ֤וֹרֶשׁ מַלְכָּ⁠א֙ שָׂ֣ם טְעֵ֔ם בֵּית־אֱלָהָ֥⁠א דְנָ֖ה לִ⁠בְּנֵֽא׃","bĕ̇ram֙ bi̇⁠şĕ̌na֣ţ ẖàdá֔h lĕ⁠k֥wòreş̌ malĕká֖̇⁠ʼ di֣̇y bábe֑l k֤̇wòreş̌ malĕká̇⁠ʼ֙ şá֣̂m tĕʻé֔m bé̇yţ-ʼèláhá֥⁠ʼ dĕná֖h li⁠bĕ̇néֽʼ׃"],[5,14,"וְ֠⁠אַף מָאנַיָּ֣⁠א דִֽי־בֵית־אֱלָהָ⁠א֮ דִּ֣י דַהֲבָ֣⁠ה וְ⁠כַסְפָּ⁠א֒ דִּ֣י נְבוּכַדְנֶצַּ֗ר הַנְפֵּק֙ מִן־הֵֽיכְלָ⁠א֙ דִּ֣י בִֽ⁠ירוּשְׁלֶ֔ם וְ⁠הֵיבֵ֣ל הִמּ֔וֹ לְ⁠הֵיכְלָ֖⁠א דִּ֣י בָבֶ֑ל הַנְפֵּ֨ק הִמּ֜וֹ כּ֣וֹרֶשׁ מַלְכָּ֗⁠א מִן־הֵֽיכְלָ⁠א֙ דִּ֣י בָבֶ֔ל וִ⁠יהִ֨יבוּ֙ לְ⁠שֵׁשְׁבַּצַּ֣ר שְׁמֵ֔⁠הּ דִּ֥י פֶחָ֖ה שָׂמֵֽ⁠הּ׃","wĕ֠⁠ʼap máʼnayá֣̇⁠ʼ diֽy-béyţ-ʼèláhá⁠ʼ֮ di֣̇y dahàbá֣⁠h wĕ⁠kasĕpá̇⁠ʼ֒ di֣̇y nĕbẇkadĕneẕȧ֗r hanĕpé̇q֙ min-héֽykĕlá⁠ʼ֙ di֣̇y biֽ⁠yrẇşĕ̌le֔m wĕ⁠héybé֣l hiṁ֔wò lĕ⁠héykĕlá֖⁠ʼ di֣̇y bábe֑l hanĕpé̇֨q hiṁ֜wò k֣̇wòreş̌ malĕká̇֗⁠ʼ min-héֽykĕlá⁠ʼ֙ di֣̇y bábe֔l wi⁠yhi֨ybẇ֙ lĕ⁠şé̌şĕ̌bȧẕȧ֣r şĕ̌mé֔⁠ḣ di֥̇y peẖá֖h şá̂méֽ⁠ḣ׃"],[5,15,"וַ⁠אֲמַר־לֵ֓⁠הּ ׀ אלה מָֽאנַיָּ֔⁠א שֵׂ֚א אֵֽזֶל־אֲחֵ֣ת הִמּ֔וֹ בְּ⁠הֵיכְלָ֖⁠א דִּ֣י בִ⁠ירוּשְׁלֶ֑ם וּ⁠בֵ֥ית אֱלָהָ֖⁠א יִתְבְּנֵ֥א עַל־אַתְרֵֽ⁠הּ׃ס","wa⁠ʼàmar-lé֓⁠ḣ ׀ ʼlh máֽʼnayá̇֔⁠ʼ şé֚̂ʼ ʼéֽzel-ʼàẖé֣ţ hiṁ֔wò bĕ̇⁠héykĕlá֖⁠ʼ di֣̇y bi⁠yrẇşĕ̌le֑m ẇ⁠bé֥yţ ʼèláhá֖⁠ʼ yiţĕbĕ̇né֥ʼ ʻal-ʼaţĕréֽ⁠ḣ׃s"],[5,16,"אֱדַ֨יִן֙ שֵׁשְׁבַּצַּ֣ר דֵּ֔ךְ אֲתָ֗א יְהַ֧ב אֻשַּׁיָּ֛⁠א דִּי־בֵ֥ית אֱלָהָ֖⁠א דִּ֣י בִ⁠ירוּשְׁלֶ֑ם וּ⁠מִן־אֱדַ֧יִן וְ⁠עַד־כְּעַ֛ן מִתְבְּנֵ֖א וְ⁠לָ֥א שְׁלִֽם׃","ʼèda֨yin֙ şé̌şĕ̌bȧẕȧ֣r dé̇֔kĕ ʼàţá֗ʼ yĕha֧b ʼuşȧ̌yá֛̇⁠ʼ di̇y-bé֥yţ ʼèláhá֖⁠ʼ di֣̇y bi⁠yrẇşĕ̌le֑m ẇ⁠min-ʼèda֧yin wĕ⁠ʻad-kĕ̇ʻa֛n miţĕbĕ̇né֖ʼ wĕ⁠lá֥ʼ şĕ̌liֽm׃"],[5,17,"וּ⁠כְעַ֞ן הֵ֧ן עַל־מַלְכָּ֣⁠א טָ֗ב יִ֠תְבַּקַּר בְּ⁠בֵ֨ית גִּנְזַיָּ֜⁠א דִּי־מַלְכָּ֣⁠א תַמָּה֮ דִּ֣י בְּ⁠בָבֶל֒ הֵ֣ן אִיתַ֗י דִּֽי־מִן־כּ֤וֹרֶשׁ מַלְכָּ⁠א֙ שִׂ֣ים טְעֵ֔ם לְ⁠מִבְנֵ֛א בֵּית־אֱלָהָ֥⁠א דֵ֖ךְ בִּ⁠ירוּשְׁלֶ֑ם וּ⁠רְע֥וּת מַלְכָּ֛⁠א עַל־דְּנָ֖ה יִשְׁלַ֥ח עֲלֶֽי⁠נָא׃ס","ẇ⁠kĕʻa֞n hé֧n ʻal-malĕká֣̇⁠ʼ tá֗b yi֠ţĕbȧqȧr bĕ̇⁠bé֨yţ gi̇nĕzayá̇֜⁠ʼ di̇y-malĕká֣̇⁠ʼ ţamá̇h֮ di֣̇y bĕ̇⁠bábel֒ hé֣n ʼiyţa֗y diֽ̇y-min-k֤̇wòreş̌ malĕká̇⁠ʼ֙ şî֣ym tĕʻé֔m lĕ⁠mibĕné֛ʼ bé̇yţ-ʼèláhá֥⁠ʼ dé֖kĕ bi̇⁠yrẇşĕ̌le֑m ẇ⁠rĕʻ֥ẇţ malĕká֛̇⁠ʼ ʻal-dĕ̇ná֖h yişĕ̌la֥ẖ ʻàleֽy⁠náʼ׃s"],[6,1,"בֵּ⁠אדַ֛יִן דָּרְיָ֥וֶשׁ מַלְכָּ֖⁠א שָׂ֣ם טְעֵ֑ם וּ⁠בַקַּ֣רוּ ׀ בְּ⁠בֵ֣ית סִפְרַיָּ֗⁠א דִּ֧י גִנְזַיָּ֛⁠א מְהַחֲתִ֥ין תַּמָּ֖ה בְּ⁠בָבֶֽל׃","bé̇⁠ʼda֛yin dá̇rĕyá֥weş̌ malĕká֖̇⁠ʼ şá֣̂m tĕʻé֑m ẇ⁠baqȧ֣rẇ ׀ bĕ̇⁠bé֣yţ sipĕrayá̇֗⁠ʼ di֧̇y ginĕzayá֛̇⁠ʼ mĕhaẖàţi֥yn ţȧmá֖̇h bĕ̇⁠bábeֽl׃"],[6,2,"וְ⁠הִשְׁתְּכַ֣ח בְּ⁠אַחְמְתָ֗א בְּ⁠בִֽירְתָ֛⁠א דִּ֛י בְּ⁠מָדַ֥י מְדִינְתָּ֖⁠ה מְגִלָּ֣ה חֲדָ֑ה וְ⁠כֵן־כְּתִ֥יב בְּ⁠גַוַּ֖⁠הּ דִּכְרוֹנָֽ⁠ה׃פ","wĕ⁠hişĕ̌ţĕ̇ka֣ẖ bĕ̇⁠ʼaẖĕmĕţá֗ʼ bĕ̇⁠biֽyrĕţá֛⁠ʼ di֛̇y bĕ̇⁠máda֥y mĕdiynĕţá֖̇⁠h mĕgilá֣̇h ẖàdá֑h wĕ⁠kén-kĕ̇ţi֥yb bĕ̇⁠gawȧ֖⁠ḣ di̇kĕrwònáֽ⁠h׃p"],[6,3,"בִּ⁠שְׁנַ֨ת חֲדָ֜ה לְ⁠כ֣וֹרֶשׁ מַלְכָּ֗⁠א כּ֣וֹרֶשׁ מַלְכָּ⁠א֮ שָׂ֣ם טְעֵם֒ בֵּית־אֱלָהָ֤⁠א בִֽ⁠ירוּשְׁלֶם֙ בַּיְתָ֣⁠א יִתְבְּנֵ֔א אֲתַר֙ דִּֽי־דָבְחִ֣ין דִּבְחִ֔ין וְ⁠אֻשּׁ֖וֹ⁠הִי מְסֽוֹבְלִ֑ין רוּמֵ⁠הּ֙ אַמִּ֣ין שִׁתִּ֔ין פְּתָיֵ֖⁠הּ אַמִּ֥ין שִׁתִּֽין׃","bi̇⁠şĕ̌na֨ţ ẖàdá֜h lĕ⁠k֣wòreş̌ malĕká̇֗⁠ʼ k֣̇wòreş̌ malĕká̇⁠ʼ֮ şá֣̂m tĕʻém֒ bé̇yţ-ʼèláhá֤⁠ʼ biֽ⁠yrẇşĕ̌lem֙ bȧyĕţá֣⁠ʼ yiţĕbĕ̇né֔ʼ ʼàţar֙ diֽ̇y-dábĕẖi֣yn di̇bĕẖi֔yn wĕ⁠ʼuş֖̇̌wò⁠hiy mĕsֽwòbĕli֑yn rẇmé⁠ḣ֙ ʼami֣̇yn şǐţi̇֔yn pĕ̇ţáyé֖⁠ḣ ʼami֥̇yn şǐţiֽ̇yn׃"],[6,4,"נִדְבָּכִ֞ין דִּי־אֶ֤בֶן גְּלָל֙ תְּלָתָ֔א וְ⁠נִדְבָּ֖ךְ דִּי־אָ֣ע חֲדַ֑ת וְ⁠נִ֨פְקְתָ֔⁠א מִן־בֵּ֥ית מַלְכָּ֖⁠א תִּתְיְהִֽב׃","nidĕbá̇ki֞yn di̇y-ʼe֤ben gĕ̇lál֙ ţĕ̇láţá֔ʼ wĕ⁠nidĕbá֖̇kĕ di̇y-ʼá֣ʻ ẖàda֑ţ wĕ⁠ni֨pĕqĕţá֔⁠ʼ min-bé֥̇yţ malĕká֖̇⁠ʼ ţi̇ţĕyĕhiֽb׃"],[6,5,"וְ֠⁠אַף מָאנֵ֣י בֵית־אֱלָהָ⁠א֮ דִּ֣י דַהֲבָ֣⁠ה וְ⁠כַסְפָּ⁠א֒ דִּ֣י נְבֽוּכַדְנֶצַּ֗ר הַנְפֵּ֛ק מִן־הֵיכְלָ֥⁠א דִי־בִ⁠ירוּשְׁלֶ֖ם וְ⁠הֵיבֵ֣ל לְ⁠בָבֶ֑ל יַהֲתִיב֗וּן וִ֠⁠יהָךְ לְ⁠הֵיכְלָ֤⁠א דִי־בִ⁠ירֽוּשְׁלֶם֙ לְ⁠אַתְרֵ֔⁠הּ וְ⁠תַחֵ֖ת בְּ⁠בֵ֥ית אֱלָהָֽ⁠א׃ס","wĕ֠⁠ʼap máʼné֣y béyţ-ʼèláhá⁠ʼ֮ di֣̇y dahàbá֣⁠h wĕ⁠kasĕpá̇⁠ʼ֒ di֣̇y nĕbֽẇkadĕneẕȧ֗r hanĕpé֛̇q min-héykĕlá֥⁠ʼ diy-bi⁠yrẇşĕ̌le֖m wĕ⁠héybé֣l lĕ⁠bábe֑l yahàţiyb֗ẇn wi֠⁠yhákĕ lĕ⁠héykĕlá֤⁠ʼ diy-bi⁠yrֽẇşĕ̌lem֙ lĕ⁠ʼaţĕré֔⁠ḣ wĕ⁠ţaẖé֖ţ bĕ̇⁠bé֥yţ ʼèláháֽ⁠ʼ׃s"],[6,6,"כְּעַ֡ן תַּ֠תְּנַי פַּחַ֨ת עֲבַֽר־נַהֲרָ֜⁠ה שְׁתַ֤ר בּוֹזְנַי֙ וּ⁠כְנָוָ֣תְ⁠ה֔וֹן אֲפַרְסְכָיֵ֔⁠א דִּ֖י בַּ⁠עֲבַ֣ר נַהֲרָ֑⁠ה רַחִיקִ֥ין הֲו֖וֹ מִן־תַּמָּֽה׃","kĕ̇ʻa֡n ţȧ֠ţĕ̇nay pȧẖa֨ţ ʻàbaֽr-nahàrá֜⁠h şĕ̌ţa֤r ḃwòzĕnay֙ ẇ⁠kĕnáwá֣ţĕ⁠h֔wòn ʼàparĕsĕkáyé֔⁠ʼ di֖̇y bȧ⁠ʻàba֣r nahàrá֑⁠h raẖiyqi֥yn hàw֖wò min-ţȧmáֽ̇h׃"],[6,7,"שְׁבֻ֕קוּ לַ⁠עֲבִידַ֖ת בֵּית־אֱלָהָ֣⁠א דֵ֑ךְ פַּחַ֤ת יְהוּדָיֵ⁠א֙ וּ⁠לְ⁠שָׂבֵ֣י יְהוּדָיֵ֔⁠א בֵּית־אֱלָהָ֥⁠א דֵ֖ךְ יִבְנ֥וֹן עַל־אַתְרֵֽ⁠הּ׃","şĕ̌bu֕qẇ la⁠ʻàbiyda֖ţ bé̇yţ-ʼèláhá֣⁠ʼ dé֑kĕ pȧẖa֤ţ yĕhẇdáyé⁠ʼ֙ ẇ⁠lĕ⁠şá̂bé֣y yĕhẇdáyé֔⁠ʼ bé̇yţ-ʼèláhá֥⁠ʼ dé֖kĕ yibĕn֥wòn ʻal-ʼaţĕréֽ⁠ḣ׃"],[6,8,"וּ⁠מִנִּ⁠י֮ שִׂ֣ים טְעֵם֒ לְ⁠מָ֣א דִֽי־תַֽעַבְד֗וּן עִם־שָׂבֵ֤י יְהוּדָיֵ⁠א֙ אִלֵּ֔ךְ לְ⁠מִבְנֵ֖א בֵּית־אֱלָהָ֣⁠א דֵ֑ךְ וּ⁠מִ⁠נִּכְסֵ֣י מַלְכָּ֗⁠א דִּ֚י מִדַּת֙ עֲבַ֣ר נַהֲרָ֔⁠ה אָסְפַּ֗רְנָא נִפְקְתָ֛⁠א תֶּהֱוֵ֧א מִֽתְיַהֲבָ֛א לְ⁠גֻבְרַיָּ֥⁠א אִלֵּ֖ךְ דִּי־לָ֥א לְ⁠בַטָּלָֽא׃","ẇ⁠mini̇⁠y֮ şî֣ym tĕʻém֒ lĕ⁠má֣ʼ diֽy-ţֽaʻabĕd֗ẇn ʻim-şá̂bé֤y yĕhẇdáyé⁠ʼ֙ ʼilé̇֔kĕ lĕ⁠mibĕné֖ʼ bé̇yţ-ʼèláhá֣⁠ʼ dé֑kĕ ẇ⁠mi⁠ni̇kĕsé֣y malĕká̇֗⁠ʼ di֚̇y midȧţ֙ ʻàba֣r nahàrá֔⁠h ʼásĕpȧ֗rĕnáʼ nipĕqĕţá֛⁠ʼ ţėhèwé֧ʼ miֽţĕyahàbá֛ʼ lĕ⁠gubĕrayá֥̇⁠ʼ ʼilé֖̇kĕ di̇y-lá֥ʼ lĕ⁠batá̇láֽʼ׃"],[6,9,"וּ⁠מָ֣ה חַשְׁחָ֡ן וּ⁠בְנֵ֣י תוֹרִ֣ין וְ⁠דִכְרִ֣ין וְ⁠אִמְּרִ֣ין ׀ לַ⁠עֲלָוָ֣ן ׀ לֶ⁠אֱלָ֪הּ שְׁמַיָּ֟⁠א חִנְטִ֞ין מְלַ֣ח ׀ חֲמַ֣ר וּ⁠מְשַׁ֗ח כְּ⁠מֵאמַ֨ר כָּהֲנַיָּ֤⁠א דִי־בִ⁠ירֽוּשְׁלֶם֙ לֶהֱוֵ֨א מִתְיְהֵ֥ב לְ⁠הֹ֛ם י֥וֹם ׀ בְּ⁠י֖וֹם דִּי־לָ֥א שָׁלֽוּ׃","ẇ⁠má֣h ẖaşĕ̌ẖá֡n ẇ⁠bĕné֣y ţwòri֣yn wĕ⁠dikĕri֣yn wĕ⁠ʼimĕ̇ri֣yn ׀ la⁠ʻàláwá֣n ׀ le⁠ʼèlá֪ḣ şĕ̌mayá̇֟⁠ʼ ẖinĕti֞yn mĕla֣ẖ ׀ ẖàma֣r ẇ⁠mĕşǎ֗ẖ kĕ̇⁠méʼma֨r ká̇hànayá֤̇⁠ʼ diy-bi⁠yrֽẇşĕ̌lem֙ lehèwé֨ʼ miţĕyĕhé֥b lĕ⁠hò֛m y֥wòm ׀ bĕ̇⁠y֖wòm di̇y-lá֥ʼ şá̌lֽẇ׃"],[6,10,"דִּֽי־לֶהֱוֺ֧ן מְהַקְרְבִ֛ין נִיחוֹחִ֖ין לֶ⁠אֱלָ֣הּ שְׁמַיָּ֑⁠א וּ⁠מְצַלַּ֕יִן לְ⁠חַיֵּ֥י מַלְכָּ֖⁠א וּ⁠בְנֽוֹ⁠הִי׃","diֽ̇y-lehèwֺ֧n mĕhaqĕrĕbi֛yn niyẖwòẖi֖yn le⁠ʼèlá֣ḣ şĕ̌mayá֑̇⁠ʼ ẇ⁠mĕẕalȧ֕yin lĕ⁠ẖayé֥̇y malĕká֖̇⁠ʼ ẇ⁠bĕnֽwò⁠hiy׃"],[6,11,"וּ⁠מִנִּ⁠י֮ שִׂ֣ים טְעֵם֒ דִּ֣י כָל־אֱנָ֗שׁ דִּ֤י יְהַשְׁנֵא֙ פִּתְגָמָ֣⁠א דְנָ֔ה יִתְנְסַ֥ח אָע֙ מִן־בַּיְתֵ֔⁠הּ וּ⁠זְקִ֖יף יִתְמְחֵ֣א עֲלֹ֑⁠הִי וּ⁠בַיְתֵ֛⁠הּ נְוָל֥וּ יִתְעֲבֵ֖ד עַל־דְּנָֽה׃","ẇ⁠mini̇⁠y֮ şî֣ym tĕʻém֒ di֣̇y kál-ʼèná֗ş̌ di֤̇y yĕhaşĕ̌néʼ֙ pi̇ţĕgámá֣⁠ʼ dĕná֔h yiţĕnĕsa֥ẖ ʼáʻ֙ min-bȧyĕţé֔⁠ḣ ẇ⁠zĕqi֖yp yiţĕmĕẖé֣ʼ ʻàlò֑⁠hiy ẇ⁠bayĕţé֛⁠ḣ nĕwál֥ẇ yiţĕʻàbé֖d ʻal-dĕ̇náֽh׃"],[6,12,"וֵֽ⁠אלָהָ֞⁠א דִּ֣י שַׁכִּ֧ן שְׁמֵ֣⁠הּ תַּמָּ֗ה יְמַגַּ֞ר כָּל־מֶ֤לֶךְ וְ⁠עַם֙ דִּ֣י ׀ יִשְׁלַ֣ח יְדֵ֗⁠הּ לְ⁠הַשְׁנָיָ֛ה לְ⁠חַבָּלָ֛ה בֵּית־אֱלָהָ֥⁠א דֵ֖ךְ דִּ֣י בִ⁠ירוּשְׁלֶ֑ם אֲנָ֤ה דָרְיָ֨וֶשׁ֙ שָׂ֣מֶת טְעֵ֔ם אָסְפַּ֖רְנָא יִתְעֲבִֽד׃פ","wéֽ⁠ʼláhá֞⁠ʼ di֣̇y şǎki֧̇n şĕ̌mé֣⁠ḣ ţȧmá̇֗h yĕmagȧ֞r ká̇l-me֤lekĕ wĕ⁠ʻam֙ di֣̇y ׀ yişĕ̌la֣ẖ yĕdé֗⁠ḣ lĕ⁠haşĕ̌náyá֛h lĕ⁠ẖabá̇lá֛h bé̇yţ-ʼèláhá֥⁠ʼ dé֖kĕ di֣̇y bi⁠yrẇşĕ̌le֑m ʼàná֤h dárĕyá֨weş̌֙ şá֣̂meţ tĕʻé֔m ʼásĕpȧ֖rĕnáʼ yiţĕʻàbiֽd׃p"],[6,13,"אֱ֠דַיִן תַּתְּנַ֞י פַּחַ֧ת עֲבַֽר־נַהֲרָ֛⁠ה שְׁתַ֥ר בּוֹזְנַ֖י וּ⁠כְנָוָתְ⁠ה֑וֹן לָ⁠קֳבֵ֗ל דִּֽי־שְׁלַ֞ח דָּרְיָ֧וֶשׁ מַלְכָּ֛⁠א כְּנֵ֖מָא אָסְפַּ֥רְנָא עֲבַֽדוּ׃","ʼè֠dayin ţȧţĕ̇na֞y pȧẖa֧ţ ʻàbaֽr-nahàrá֛⁠h şĕ̌ţa֥r ḃwòzĕna֖y ẇ⁠kĕnáwáţĕ⁠h֑wòn lá⁠qobé֗l diֽ̇y-şĕ̌la֞ẖ dá̇rĕyá֧weş̌ malĕká֛̇⁠ʼ kĕ̇né֖máʼ ʼásĕpȧ֥rĕnáʼ ʻàbaֽdẇ׃"],[6,14,"וְ⁠שָׂבֵ֤י יְהוּדָיֵ⁠א֙ בָּנַ֣יִן וּ⁠מַצְלְחִ֔ין בִּ⁠נְבוּאַת֙ חַגַּ֣י נביא⁠ה וּ⁠זְכַרְיָ֖ה בַּר־עִדּ֑וֹא וּ⁠בְנ֣וֹ וְ⁠שַׁכְלִ֗לוּ מִן־טַ֨עַם֙ אֱלָ֣הּ יִשְׂרָאֵ֔ל וּ⁠מִ⁠טְּעֵם֙ כּ֣וֹרֶשׁ וְ⁠דָרְיָ֔וֶשׁ וְ⁠אַרְתַּחְשַׁ֖שְׂתְּא מֶ֥לֶךְ פָּרָֽס׃","wĕ⁠şá̂bé֤y yĕhẇdáyé⁠ʼ֙ bá̇na֣yin ẇ⁠maẕĕlĕẖi֔yn bi̇⁠nĕbẇʼaţ֙ ẖagȧ֣y nbyʼ⁠h ẇ⁠zĕkarĕyá֖h bȧr-ʻiḋ֑wòʼ ẇ⁠bĕn֣wò wĕ⁠şǎkĕli֗lẇ min-ta֨ʻam֙ ʼèlá֣ḣ yişĕ̂ráʼé֔l ẇ⁠mi⁠tĕ̇ʻém֙ k֣̇wòreş̌ wĕ⁠dárĕyá֔weş̌ wĕ⁠ʼarĕţȧẖĕşǎ֖şĕ̂ţĕ̇ʼ me֥lekĕ pá̇ráֽs׃"],[6,15,"וְ⁠שֵׁיצִיא֙ בַּיְתָ֣⁠ה דְנָ֔ה עַ֛ד י֥וֹם תְּלָתָ֖ה לִ⁠ירַ֣ח אֲדָ֑ר דִּי־הִ֣יא שְׁנַת־שֵׁ֔ת לְ⁠מַלְכ֖וּת דָּרְיָ֥וֶשׁ מַלְכָּֽ⁠א׃פ","wĕ⁠şé̌yẕiyʼ֙ bȧyĕţá֣⁠h dĕná֔h ʻa֛d y֥wòm ţĕ̇láţá֖h li⁠yra֣ẖ ʼàdá֑r di̇y-hi֣yʼ şĕ̌naţ-şé̌֔ţ lĕ⁠malĕk֖ẇţ dá̇rĕyá֥weş̌ malĕkáֽ̇⁠ʼ׃p"],[6,16,"וַ⁠עֲבַ֣דוּ בְנֵֽי־יִ֠שְׂרָאֵל כָּהֲנַיָּ֨⁠א וְ⁠לֵוָיֵ֜⁠א וּ⁠שְׁאָ֣ר בְּנֵי־גָלוּתָ֗⁠א חֲנֻכַּ֛ת בֵּית־אֱלָהָ֥⁠א דְנָ֖ה בְּ⁠חֶדְוָֽה׃","wa⁠ʻàba֣dẇ bĕnéֽy-yi֠şĕ̂ráʼél ká̇hànayá̇֨⁠ʼ wĕ⁠léwáyé֜⁠ʼ ẇ⁠şĕ̌ʼá֣r bĕ̇néy-gálẇţá֗⁠ʼ ẖànukȧ֛ţ bé̇yţ-ʼèláhá֥⁠ʼ dĕná֖h bĕ̇⁠ẖedĕwáֽh׃"],[6,17,"וְ⁠הַקְרִ֗בוּ לַ⁠חֲנֻכַּת֮ בֵּית־אֱלָהָ֣⁠א דְנָה֒ תּוֹרִ֣ין מְאָ֔ה דִּכְרִ֣ין מָאתַ֔יִן אִמְּרִ֖ין אַרְבַּ֣ע מְאָ֑ה וּ⁠צְפִירֵ֨י עִזִּ֜ין ל⁠חטיא עַל־כָּל־יִשְׂרָאֵל֙ תְּרֵֽי־עֲשַׂ֔ר לְ⁠מִנְיָ֖ן שִׁבְטֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠haqĕri֗bẇ la⁠ẖànukȧţ֮ bé̇yţ-ʼèláhá֣⁠ʼ dĕnáh֒ ţ̇wòri֣yn mĕʼá֔h di̇kĕri֣yn máʼţa֔yin ʼimĕ̇ri֖yn ʼarĕbȧ֣ʻ mĕʼá֑h ẇ⁠ẕĕpiyré֨y ʻizi̇֜yn l⁠ẖtyʼ ʻal-ká̇l-yişĕ̂ráʼél֙ ţĕ̇réֽy-ʻàşâ֔r lĕ⁠minĕyá֖n şǐbĕté֥y yişĕ̂ráʼéֽl׃"],[6,18,"וַ⁠הֲקִ֨ימוּ כָהֲנַיָּ֜⁠א בִּ⁠פְלֻגָּתְ⁠ה֗וֹן וְ⁠לֵוָיֵ⁠א֙ בְּ⁠מַחְלְקָ֣תְ⁠ה֔וֹן עַל־עֲבִידַ֥ת אֱלָהָ֖⁠א דִּ֣י בִ⁠ירוּשְׁלֶ֑ם כִּ⁠כְתָ֖ב סְפַ֥ר מֹשֶֽׁה׃פ","wa⁠hàqi֨ymẇ káhànayá̇֜⁠ʼ bi̇⁠pĕlugá̇ţĕ⁠h֗wòn wĕ⁠léwáyé⁠ʼ֙ bĕ̇⁠maẖĕlĕqá֣ţĕ⁠h֔wòn ʻal-ʻàbiyda֥ţ ʼèláhá֖⁠ʼ di֣̇y bi⁠yrẇşĕ̌le֑m ki̇⁠kĕţá֖b sĕpa֥r mòşěֽh׃p"],[6,19,"וַ⁠יַּעֲשׂ֥וּ בְנֵי־הַ⁠גּוֹלָ֖ה אֶת־הַ⁠פָּ֑סַח בְּ⁠אַרְבָּעָ֥ה עָשָׂ֖ר לַ⁠חֹ֥דֶשׁ הָ⁠רִאשֽׁוֹן׃","wa⁠yȧʻàş֥̂ẇ bĕnéy-ha⁠ġwòlá֖h ʼeţ-ha⁠pá֑̇saẖ bĕ̇⁠ʼarĕbá̇ʻá֥h ʻáşá֖̂r la⁠ẖò֥deş̌ há⁠riʼşֽ̌wòn׃"],[6,20,"כִּ֣י הִֽטַּהֲר֞וּ הַ⁠כֹּהֲנִ֧ים וְ⁠הַ⁠לְוִיִּ֛ם כְּ⁠אֶחָ֖ד כֻּלָּ֣⁠ם טְהוֹרִ֑ים וַ⁠יִּשְׁחֲט֤וּ הַ⁠פֶּ֨סַח֙ לְ⁠כָל־בְּנֵ֣י הַ⁠גּוֹלָ֔ה וְ⁠לַ⁠אֲחֵי⁠הֶ֥ם הַ⁠כֹּהֲנִ֖ים וְ⁠לָ⁠הֶֽם׃","ki֣̇y hiֽtȧhàr֞ẇ ha⁠kò̇hàni֧ym wĕ⁠ha⁠lĕwiyi֛̇m kĕ̇⁠ʼeẖá֖d ku̇lá֣̇⁠m tĕhwòri֑ym wa⁠yi̇şĕ̌ẖàt֤ẇ ha⁠pė֨saẖ֙ lĕ⁠kál-bĕ̇né֣y ha⁠ġwòlá֔h wĕ⁠la⁠ʼàẖéy⁠he֥m ha⁠kò̇hàni֖ym wĕ⁠lá⁠heֽm׃"],[6,21,"וַ⁠יֹּאכְל֣וּ בְנֵֽי־יִשְׂרָאֵ֗ל הַ⁠שָּׁבִים֙ מֵֽ⁠הַ⁠גּוֹלָ֔ה וְ⁠כֹ֗ל הַ⁠נִּבְדָּ֛ל מִ⁠טֻּמְאַ֥ת גּוֹיֵֽ־הָ⁠אָ֖רֶץ אֲלֵ⁠הֶ֑ם לִ⁠דְרֹ֕שׁ לַֽ⁠יהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","wa⁠yò̇ʼkĕl֣ẇ bĕnéֽy-yişĕ̂ráʼé֗l ha⁠şá̇̌biym֙ méֽ⁠ha⁠ġwòlá֔h wĕ⁠kò֗l ha⁠ni̇bĕdá֛̇l mi⁠tu̇mĕʼa֥ţ ġwòyéֽ-há⁠ʼá֖reẕ ʼàlé⁠he֑m li⁠dĕrò֕ş̌ laֽ⁠yhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[6,22,"וַ⁠יַּֽעֲשׂ֧וּ חַג־מַצּ֛וֹת שִׁבְעַ֥ת יָמִ֖ים בְּ⁠שִׂמְחָ֑ה כִּ֣י ׀ שִׂמְּחָ֣⁠ם יְהוָ֗ה וְֽ⁠הֵסֵ֞ב לֵ֤ב מֶֽלֶךְ־אַשּׁוּר֙ עֲלֵי⁠הֶ֔ם לְ⁠חַזֵּ֣ק יְדֵי⁠הֶ֔ם בִּ⁠מְלֶ֥אכֶת בֵּית־הָ⁠אֱלֹהִ֖ים אֱלֹהֵ֥י יִשְׂרָאֵֽל׃פ","wa⁠yȧֽʻàş֧̂ẇ ẖag-maẕ֛̇wòţ şǐbĕʻa֥ţ yámi֖ym bĕ̇⁠şîmĕẖá֑h ki֣̇y ׀ şîmĕ̇ẖá֣⁠m yĕhwá֗h wĕֽ⁠hésé֞b lé֤b meֽlekĕ-ʼaş̇̌ẇr֙ ʻàléy⁠he֔m lĕ⁠ẖazé֣̇q yĕdéy⁠he֔m bi̇⁠mĕle֥ʼkeţ bé̇yţ-há⁠ʼèlòhi֖ym ʼèlòhé֥y yişĕ̂ráʼéֽl׃p"],[7,1,"וְ⁠אַחַר֙ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה בְּ⁠מַלְכ֖וּת אַרְתַּחְשַׁ֣סְתְּא מֶֽלֶךְ־פָּרָ֑ס עֶזְרָא֙ בֶּן־שְׂרָיָ֔ה בֶּן־עֲזַרְיָ֖ה בֶּן־חִלְקִיָּֽה׃","wĕ⁠ʼaẖar֙ ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh bĕ̇⁠malĕk֖ẇţ ʼarĕţȧẖĕşǎ֣sĕţĕ̇ʼ meֽlekĕ-pá̇rá֑s ʻezĕráʼ֙ bėn-şĕ̂ráyá֔h bėn-ʻàzarĕyá֖h bėn-ẖilĕqiyáֽ̇h׃"],[7,2,"בֶּן־שַׁלּ֥וּם בֶּן־צָד֖וֹק בֶּן־אֲחִיטֽוּב׃","bėn-şǎl֥̇ẇm bėn-ẕád֖wòq bėn-ʼàẖiytֽẇb׃"],[7,3,"בֶּן־אֲמַרְיָ֥ה בֶן־עֲזַרְיָ֖ה בֶּן־מְרָיֽוֹת׃","bėn-ʼàmarĕyá֥h ben-ʻàzarĕyá֖h bėn-mĕráyֽwòţ׃"],[7,4,"בֶּן־זְרַֽחְיָ֥ה בֶן־עֻזִּ֖י בֶּן־בֻּקִּֽי׃","bėn-zĕraֽẖĕyá֥h ben-ʻuzi֖̇y bėn-bu̇qiֽ̇y׃"],[7,5,"בֶּן־אֲבִישׁ֗וּעַ בֶּן־פִּֽינְחָס֙ בֶּן־אֶלְעָזָ֔ר בֶּן־אַהֲרֹ֥ן הַ⁠כֹּהֵ֖ן הָ⁠רֹֽאשׁ׃","bėn-ʼàbiyş̌֗ẇʻa bėn-piֽ̇ynĕẖás֙ bėn-ʼelĕʻázá֔r bėn-ʼahàrò֥n ha⁠kò̇hé֖n há⁠ròֽʼş̌׃"],[7,6,"ה֤וּא עֶזְרָא֙ עָלָ֣ה מִ⁠בָּבֶ֔ל וְ⁠הֽוּא־סֹפֵ֤ר מָהִיר֙ בְּ⁠תוֹרַ֣ת מֹשֶׁ֔ה אֲשֶׁר־נָתַ֥ן יְהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל וַ⁠יִּתֶּן־ל֣⁠וֹ הַ⁠מֶּ֗לֶךְ כְּ⁠יַד־יְהוָ֤ה אֱלֹהָי⁠ו֙ עָלָ֔י⁠ו כֹּ֖ל בַּקָּשָׁתֽ⁠וֹ׃פ","h֤ẇʼ ʻezĕráʼ֙ ʻálá֣h mi⁠bá̇be֔l wĕ⁠hֽẇʼ-sòpé֤r máhiyr֙ bĕ̇⁠ţwòra֣ţ mòşě֔h ʼàşěr-náţa֥n yĕhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l wa⁠yi̇ţėn-l֣⁠wò ha⁠mė֗lekĕ kĕ̇⁠yad-yĕhwá֤h ʼèlòháy⁠w֙ ʻálá֔y⁠w kò֖̇l bȧqá̇şá̌ţֽ⁠wò׃p"],[7,7,"וַ⁠יַּֽעֲל֣וּ מִ⁠בְּנֵֽי־יִ֠שְׂרָאֵל וּ⁠מִן־הַ⁠כֹּהֲנִ֨ים וְ⁠הַ⁠לְוִיִּ֜ם וְ⁠הַ⁠מְשֹׁרְרִ֧ים וְ⁠הַ⁠שֹּׁעֲרִ֛ים וְ⁠הַ⁠נְּתִינִ֖ים אֶל־יְרוּשָׁלִָ֑ם בִּ⁠שְׁנַת־שֶׁ֖בַע לְ⁠אַרְתַּחְשַׁ֥סְתְּא הַ⁠מֶּֽלֶךְ׃","wa⁠yȧֽʻàl֣ẇ mi⁠bĕ̇néֽy-yi֠şĕ̂ráʼél ẇ⁠min-ha⁠kò̇hàni֨ym wĕ⁠ha⁠lĕwiyi̇֜m wĕ⁠ha⁠mĕşò̌rĕri֧ym wĕ⁠ha⁠şò̇̌ʻàri֛ym wĕ⁠ha⁠nĕ̇ţiyni֖ym ʼel-yĕrẇşá̌liá֑m bi̇⁠şĕ̌naţ-şě֖baʻ lĕ⁠ʼarĕţȧẖĕşǎ֥sĕţĕ̇ʼ ha⁠mėֽlekĕ׃"],[7,8,"וַ⁠יָּבֹ֥א יְרוּשָׁלִַ֖ם בַּ⁠חֹ֣דֶשׁ הַ⁠חֲמִישִׁ֑י הִ֛יא שְׁנַ֥ת הַ⁠שְּׁבִיעִ֖ית לַ⁠מֶּֽלֶךְ׃","wa⁠yá̇bò֥ʼ yĕrẇşá̌lia֖m bȧ⁠ẖò֣deş̌ ha⁠ẖàmiyşǐ֑y hi֛yʼ şĕ̌na֥ţ ha⁠şĕ̇̌biyʻi֖yţ la⁠mėֽlekĕ׃"],[7,9,"כִּ֗י בְּ⁠אֶחָד֙ לַ⁠חֹ֣דֶשׁ הָ⁠רִאשׁ֔וֹן ה֣וּא יְסֻ֔ד הַֽ⁠מַּעֲלָ֖ה מִ⁠בָּבֶ֑ל וּ⁠בְ⁠אֶחָ֞ד לַ⁠חֹ֣דֶשׁ הַ⁠חֲמִישִׁ֗י בָּ֚א אֶל־יְר֣וּשָׁלִַ֔ם כְּ⁠יַד־אֱלֹהָ֖י⁠ו הַ⁠טּוֹבָ֥ה עָלָֽי⁠ו׃","ki̇֗y bĕ̇⁠ʼeẖád֙ la⁠ẖò֣deş̌ há⁠riʼş̌֔wòn h֣ẇʼ yĕsu֔d haֽ⁠mȧʻàlá֖h mi⁠bá̇be֑l ẇ⁠bĕ⁠ʼeẖá֞d la⁠ẖò֣deş̌ ha⁠ẖàmiyşǐ֗y bá֚̇ʼ ʼel-yĕr֣ẇşá̌lia֔m kĕ̇⁠yad-ʼèlòhá֖y⁠w ha⁠ṫwòbá֥h ʻáláֽy⁠w׃"],[7,10,"כִּ֤י עֶזְרָא֙ הֵכִ֣ין לְבָב֔⁠וֹ לִ⁠דְר֛וֹשׁ אֶת־תּוֹרַ֥ת יְהוָ֖ה וְ⁠לַ⁠עֲשֹׂ֑ת וּ⁠לְ⁠לַמֵּ֥ד בְּ⁠יִשְׂרָאֵ֖ל חֹ֥ק וּ⁠מִשְׁפָּֽט׃ס","ki֤̇y ʻezĕráʼ֙ héki֣yn lĕbáb֔⁠wò li⁠dĕr֛wòş̌ ʼeţ-ţ̇wòra֥ţ yĕhwá֖h wĕ⁠la⁠ʻàşò֑̂ţ ẇ⁠lĕ⁠lamé֥̇d bĕ̇⁠yişĕ̂ráʼé֖l ẖò֥q ẇ⁠mişĕ̌páֽ̇t׃s"],[7,11,"וְ⁠זֶ֣ה ׀ פַּרְשֶׁ֣גֶן הַֽ⁠נִּשְׁתְּוָ֗ן אֲשֶׁ֤ר נָתַן֙ הַ⁠מֶּ֣לֶךְ אַרְתַּחְשַׁ֔סְתְּא לְ⁠עֶזְרָ֥א הַ⁠כֹּהֵ֖ן הַ⁠סֹּפֵ֑ר סֹפֵ֞ר דִּבְרֵ֧י מִצְוֺת־יְהוָ֛ה וְ⁠חֻקָּ֖י⁠ו עַל־יִשְׂרָאֵֽל׃פ","wĕ⁠ze֣h ׀ pȧrĕşě֣gen haֽ⁠ni̇şĕ̌ţĕ̇wá֗n ʼàşě֤r náţan֙ ha⁠mė֣lekĕ ʼarĕţȧẖĕşǎ֔sĕţĕ̇ʼ lĕ⁠ʻezĕrá֥ʼ ha⁠kò̇hé֖n ha⁠sò̇pé֑r sòpé֞r di̇bĕré֧y miẕĕwֺţ-yĕhwá֛h wĕ⁠ẖuqá֖̇y⁠w ʻal-yişĕ̂ráʼéֽl׃p"],[7,12,"אַ֨רְתַּחְשַׁ֔סְתְּא מֶ֖לֶךְ מַלְכַיָּ֑⁠א לְ⁠עֶזְרָ֣א כָ֠הֲנָ⁠א סָפַ֨ר דָּתָ֜⁠א דִּֽי־אֱלָ֧הּ שְׁמַיָּ֛⁠א גְּמִ֖יר וּ⁠כְעֶֽנֶת׃","ʼa֨rĕţȧẖĕşǎ֔sĕţĕ̇ʼ me֖lekĕ malĕkayá֑̇⁠ʼ lĕ⁠ʻezĕrá֣ʼ ká֠hàná⁠ʼ sápa֨r dá̇ţá֜⁠ʼ diֽ̇y-ʼèlá֧ḣ şĕ̌mayá֛̇⁠ʼ gĕ̇mi֖yr ẇ⁠kĕʻeֽneţ׃"],[7,13,"מִנִּ⁠י֮ שִׂ֣ים טְעֵם֒ דִּ֣י כָל־מִתְנַדַּ֣ב בְּ⁠מַלְכוּתִ⁠י֩ מִן־עַמָּ֨⁠ה יִשְׂרָאֵ֜ל וְ⁠כָהֲנ֣וֹ⁠הִי וְ⁠לֵוָיֵ֗⁠א לִ⁠מְהָ֧ךְ לִֽ⁠ירוּשְׁלֶ֛ם עִמָּ֖⁠ךְ יְהָֽךְ׃","mini̇⁠y֮ şî֣ym tĕʻém֒ di֣̇y kál-miţĕnadȧ֣b bĕ̇⁠malĕkẇţi⁠y֩ min-ʻamá̇֨⁠h yişĕ̂ráʼé֜l wĕ⁠káhàn֣wò⁠hiy wĕ⁠léwáyé֗⁠ʼ li⁠mĕhá֧kĕ liֽ⁠yrẇşĕ̌le֛m ʻimá֖̇⁠kĕ yĕháֽkĕ׃"],[7,14,"כָּ⁠ל־קֳבֵ֗ל דִּי֩ מִן־קֳדָ֨ם מַלְכָּ֜⁠א וְ⁠שִׁבְעַ֤ת יָעֲטֹ֨⁠הִי֙ שְׁלִ֔יחַ לְ⁠בַקָּרָ֥א עַל־יְה֖וּד וְ⁠לִֽ⁠ירוּשְׁלֶ֑ם בְּ⁠דָ֥ת אֱלָהָ֖⁠ךְ דִּ֥י בִ⁠ידָֽ⁠ךְ׃","ká̇⁠l-qobé֗l di̇y֩ min-qodá֨m malĕká̇֜⁠ʼ wĕ⁠şǐbĕʻa֤ţ yáʻàtò֨⁠hiy֙ şĕ̌li֔yẖa lĕ⁠baqá̇rá֥ʼ ʻal-yĕh֖ẇd wĕ⁠liֽ⁠yrẇşĕ̌le֑m bĕ̇⁠dá֥ţ ʼèláhá֖⁠kĕ di֥̇y bi⁠ydáֽ⁠kĕ׃"],[7,15,"וּ⁠לְ⁠הֵיבָלָ֖ה כְּסַ֣ף וּ⁠דְהַ֑ב דִּֽי־מַלְכָּ֣⁠א וְ⁠יָעֲט֗וֹ⁠הִי הִתְנַדַּ֨בוּ֙ לֶ⁠אֱלָ֣הּ יִשְׂרָאֵ֔ל דִּ֥י בִֽ⁠ירוּשְׁלֶ֖ם מִשְׁכְּנֵֽ⁠הּ׃","ẇ⁠lĕ⁠héybálá֖h kĕ̇sa֣p ẇ⁠dĕha֑b diֽ̇y-malĕká֣̇⁠ʼ wĕ⁠yáʻàt֗wò⁠hiy hiţĕnadȧ֨bẇ֙ le⁠ʼèlá֣ḣ yişĕ̂ráʼé֔l di֥̇y biֽ⁠yrẇşĕ̌le֖m mişĕ̌kĕ̇néֽ⁠ḣ׃"],[7,16,"וְ⁠כֹל֙ כְּסַ֣ף וּ⁠דְהַ֔ב דִּ֣י תְהַשְׁכַּ֔ח בְּ⁠כֹ֖ל מְדִינַ֣ת בָּבֶ֑ל עִם֩ הִתְנַדָּב֨וּת עַמָּ֤⁠א וְ⁠כָֽהֲנַיָּ⁠א֙ מִֽתְנַדְּבִ֔ין לְ⁠בֵ֥ית אֱלָהֲ⁠הֹ֖ם דִּ֥י בִ⁠ירוּשְׁלֶֽם׃","wĕ⁠kòl֙ kĕ̇sa֣p ẇ⁠dĕha֔b di֣̇y ţĕhaşĕ̌kȧ֔ẖ bĕ̇⁠kò֖l mĕdiyna֣ţ bá̇be֑l ʻim֩ hiţĕnadá̇b֨ẇţ ʻamá֤̇⁠ʼ wĕ⁠káֽhànayá̇⁠ʼ֙ miֽţĕnadĕ̇bi֔yn lĕ⁠bé֥yţ ʼèláhà⁠hò֖m di֥̇y bi⁠yrẇşĕ̌leֽm׃"],[7,17,"כָּ⁠ל־קֳבֵ֣ל דְּנָה֩ אָסְפַּ֨רְנָא תִקְנֵ֜א בְּ⁠כַסְפָּ֣⁠א דְנָ֗ה תּוֹרִ֤ין ׀ דִּכְרִין֙ אִמְּרִ֔ין וּ⁠מִנְחָתְ⁠ה֖וֹן וְ⁠נִסְכֵּי⁠ה֑וֹן וּ⁠תְקָרֵ֣ב הִמּ֔וֹ עַֽל־מַדְבְּחָ֔⁠ה דִּ֛י בֵּ֥ית אֱלָהֲ⁠כֹ֖ם דִּ֥י בִ⁠ירוּשְׁלֶֽם׃","ká̇⁠l-qobé֣l dĕ̇náh֩ ʼásĕpȧ֨rĕnáʼ ţiqĕné֜ʼ bĕ̇⁠kasĕpá֣̇⁠ʼ dĕná֗h ţ̇wòri֤yn ׀ di̇kĕriyn֙ ʼimĕ̇ri֔yn ẇ⁠minĕẖáţĕ⁠h֖wòn wĕ⁠nisĕké̇y⁠h֑wòn ẇ⁠ţĕqáré֣b hiṁ֔wò ʻaֽl-madĕbĕ̇ẖá֔⁠h di֛̇y bé֥̇yţ ʼèláhà⁠kò֖m di֥̇y bi⁠yrẇşĕ̌leֽm׃"],[7,18,"וּ⁠מָ֣ה דִי֩ עלי⁠ך וְ⁠עַל־אחי⁠ך יֵיטַ֗ב בִּ⁠שְׁאָ֛ר כַּסְפָּ֥⁠א וְ⁠דַהֲבָ֖⁠ה לְ⁠מֶעְבַּ֑ד כִּ⁠רְע֥וּת אֱלָהֲ⁠כֹ֖ם תַּעַבְדֽוּן׃","ẇ⁠má֣h diy֩ ʻly⁠k wĕ⁠ʻal-ʼẖy⁠k yéyta֗b bi̇⁠şĕ̌ʼá֛r kȧsĕpá֥̇⁠ʼ wĕ⁠dahàbá֖⁠h lĕ⁠meʻĕbȧ֑d ki̇⁠rĕʻ֥ẇţ ʼèláhà⁠kò֖m ţȧʻabĕdֽẇn׃"],[7,19,"וּ⁠מָֽאנַיָּ⁠א֙ דִּֽי־מִתְיַהֲבִ֣ין לָ֔⁠ךְ לְ⁠פָלְחָ֖ן בֵּ֣ית אֱלָהָ֑⁠ךְ הַשְׁלֵ֕ם קֳדָ֖ם אֱלָ֥הּ יְרוּשְׁלֶֽם׃","ẇ⁠máֽʼnayá̇⁠ʼ֙ diֽ̇y-miţĕyahàbi֣yn lá֔⁠kĕ lĕ⁠pálĕẖá֖n bé֣̇yţ ʼèláhá֑⁠kĕ haşĕ̌lé֕m qodá֖m ʼèlá֥ḣ yĕrẇşĕ̌leֽm׃"],[7,20,"וּ⁠שְׁאָ֗ר חַשְׁחוּת֙ בֵּ֣ית אֱלָהָ֔⁠ךְ דִּ֥י יִפֶּל־לָ֖⁠ךְ לְ⁠מִנְתַּ֑ן תִּנְתֵּ֕ן מִן־בֵּ֖ית גִּנְזֵ֥י מַלְכָּֽ⁠א׃","ẇ⁠şĕ̌ʼá֗r ẖaşĕ̌ẖẇţ֙ bé֣̇yţ ʼèláhá֔⁠kĕ di֥̇y yipėl-lá֖⁠kĕ lĕ⁠minĕţȧ֑n ţi̇nĕţé̇֕n min-bé֖̇yţ gi̇nĕzé֥y malĕkáֽ̇⁠ʼ׃"],[7,21,"וּ֠⁠מִנִּ⁠י אֲנָ֞ה אַרְתַּחְשַׁ֤סְתְּא מַלְכָּ⁠א֙ שִׂ֣ים טְעֵ֔ם לְ⁠כֹל֙ גִּזַּֽבְרַיָּ֔⁠א דִּ֖י בַּ⁠עֲבַ֣ר נַהֲרָ֑⁠ה דִּ֣י כָל־דִּ֣י יִ֠שְׁאֲלֶנְ⁠כוֹן עֶזְרָ֨א כָהֲנָ֜⁠ה סָפַ֤ר דָּתָ⁠א֙ דִּֽי־אֱלָ֣הּ שְׁמַיָּ֔⁠א אָסְפַּ֖רְנָא יִתְעֲבִֽד׃","ẇ֠⁠mini̇⁠y ʼàná֞h ʼarĕţȧẖĕşǎ֤sĕţĕ̇ʼ malĕká̇⁠ʼ֙ şî֣ym tĕʻé֔m lĕ⁠kòl֙ gi̇zȧֽbĕrayá̇֔⁠ʼ di֖̇y bȧ⁠ʻàba֣r nahàrá֑⁠h di֣̇y kál-di֣̇y yi֠şĕ̌ʼàlenĕ⁠kwòn ʻezĕrá֨ʼ káhàná֜⁠h sápa֤r dá̇ţá⁠ʼ֙ diֽ̇y-ʼèlá֣ḣ şĕ̌mayá̇֔⁠ʼ ʼásĕpȧ֖rĕnáʼ yiţĕʻàbiֽd׃"],[7,22,"עַד־כְּסַף֮ כַּכְּרִ֣ין מְאָה֒ וְ⁠עַד־חִנְטִין֙ כֹּרִ֣ין מְאָ֔ה וְ⁠עַד־חֲמַר֙ בַּתִּ֣ין מְאָ֔ה וְ⁠עַד־בַּתִּ֥ין מְשַׁ֖ח מְאָ֑ה וּ⁠מְלַ֖ח דִּי־לָ֥א כְתָֽב׃","ʻad-kĕ̇sap֮ kȧkĕ̇ri֣yn mĕʼáh֒ wĕ⁠ʻad-ẖinĕtiyn֙ kò̇ri֣yn mĕʼá֔h wĕ⁠ʻad-ẖàmar֙ bȧţi֣̇yn mĕʼá֔h wĕ⁠ʻad-bȧţi֥̇yn mĕşǎ֖ẖ mĕʼá֑h ẇ⁠mĕla֖ẖ di̇y-lá֥ʼ kĕţáֽb׃"],[7,23,"כָּל־דִּ֗י מִן־טַ֨עַם֙ אֱלָ֣הּ שְׁמַיָּ֔⁠א יִתְעֲבֵד֙ אַדְרַזְדָּ֔א לְ⁠בֵ֖ית אֱלָ֣הּ שְׁמַיָּ֑⁠א דִּֽי־לְ⁠מָ֤ה לֶֽהֱוֵא֙ קְצַ֔ף עַל־מַלְכ֥וּת מַלְכָּ֖⁠א וּ⁠בְנֽוֹ⁠הִי׃","ká̇l-di̇֗y min-ta֨ʻam֙ ʼèlá֣ḣ şĕ̌mayá̇֔⁠ʼ yiţĕʻàbéd֙ ʼadĕrazĕdá̇֔ʼ lĕ⁠bé֖yţ ʼèlá֣ḣ şĕ̌mayá֑̇⁠ʼ diֽ̇y-lĕ⁠má֤h leֽhèwéʼ֙ qĕẕa֔p ʻal-malĕk֥ẇţ malĕká֖̇⁠ʼ ẇ⁠bĕnֽwò⁠hiy׃"],[7,24,"וּ⁠לְ⁠כֹ֣ם מְהוֹדְעִ֗ין דִּ֣י כָל־כָּהֲנַיָּ֣⁠א וְ֠⁠לֵוָיֵ⁠א זַמָּ֨רַיָּ֤⁠א תָרָֽעַיָּ⁠א֙ נְתִ֣ינַיָּ֔⁠א וּ⁠פָ֣לְחֵ֔י בֵּ֖ית אֱלָהָ֣⁠א דְנָ֑ה מִנְדָּ֤ה בְלוֹ֙ וַ⁠הֲלָ֔ךְ לָ֥א שַׁלִּ֖יט לְ⁠מִרְמֵ֥א עֲלֵי⁠הֹֽם׃","ẇ⁠lĕ⁠kò֣m mĕhwòdĕʻi֗yn di֣̇y kál-ká̇hànayá֣̇⁠ʼ wĕ֠⁠léwáyé⁠ʼ zamá̇֨rayá֤̇⁠ʼ ţáráֽʻayá̇⁠ʼ֙ nĕţi֣ynayá̇֔⁠ʼ ẇ⁠pá֣lĕẖé֔y bé֖̇yţ ʼèláhá֣⁠ʼ dĕná֑h minĕdá֤̇h bĕlwò֙ wa⁠hàlá֔kĕ lá֥ʼ şǎli֖̇yt lĕ⁠mirĕmé֥ʼ ʻàléy⁠hòֽm׃"],[7,25,"וְ⁠אַ֣נְתְּ עֶזְרָ֗א כְּ⁠חָכְמַ֨ת אֱלָהָ֤⁠ךְ דִּֽי־בִ⁠ידָ⁠ךְ֙ מֶ֣נִּי שָׁפְטִ֞ין וְ⁠דַיָּנִ֗ין דִּי־לֶהֱוֺ֤ן דאנין לְ⁠כָל־עַמָּ⁠ה֙ דִּ֚י בַּ⁠עֲבַ֣ר נַהֲרָ֔⁠ה לְ⁠כָל־יָדְעֵ֖י דָּתֵ֣י אֱלָהָ֑⁠ךְ וְ⁠דִ֧י לָ֦א יָדַ֖ע תְּהוֹדְעֽוּן׃","wĕ⁠ʼa֣nĕţĕ̇ ʻezĕrá֗ʼ kĕ̇⁠ẖákĕma֨ţ ʼèláhá֤⁠kĕ diֽ̇y-bi⁠ydá⁠kĕ֙ me֣ni̇y şá̌pĕti֞yn wĕ⁠dayá̇ni֗yn di̇y-lehèwֺ֤n dʼnyn lĕ⁠kál-ʻamá̇⁠h֙ di֚̇y bȧ⁠ʻàba֣r nahàrá֔⁠h lĕ⁠kál-yádĕʻé֖y dá̇ţé֣y ʼèláhá֑⁠kĕ wĕ⁠di֧y lá֦ʼ yáda֖ʻ ţĕ̇hwòdĕʻֽẇn׃"],[7,26,"וְ⁠כָל־דִּי־לָא֩ לֶהֱוֵ֨א עָבֵ֜ד דָּתָ֣⁠א דִֽי־אֱלָהָ֗⁠ךְ וְ⁠דָתָ⁠א֙ דִּ֣י מַלְכָּ֔⁠א אָסְפַּ֕רְנָא דִּינָ֕⁠ה לֶהֱוֵ֥א מִתְעֲבֵ֖ד מִנֵּ֑⁠הּ הֵ֤ן לְ⁠מוֹת֙ הֵ֣ן ל⁠שרשו הֵן־לַ⁠עֲנָ֥שׁ נִכְסִ֖ין וְ⁠לֶ⁠אֱסוּרִֽין׃פ","wĕ⁠kál-di̇y-láʼ֩ lehèwé֨ʼ ʻábé֜d dá̇ţá֣⁠ʼ diֽy-ʼèláhá֗⁠kĕ wĕ⁠dáţá⁠ʼ֙ di֣̇y malĕká̇֔⁠ʼ ʼásĕpȧ֕rĕnáʼ di̇yná֕⁠h lehèwé֥ʼ miţĕʻàbé֖d miné֑̇⁠ḣ hé֤n lĕ⁠mwòţ֙ hé֣n l⁠şrşw hén-la⁠ʻàná֥ş̌ nikĕsi֖yn wĕ⁠le⁠ʼèsẇriֽyn׃p"],[7,27,"בָּר֥וּךְ יְהוָ֖ה אֱלֹהֵ֣י אֲבוֹתֵ֑י⁠נוּ אֲשֶׁ֨ר נָתַ֤ן כָּ⁠זֹאת֙ בְּ⁠לֵ֣ב הַ⁠מֶּ֔לֶךְ לְ⁠פָאֵ֕ר אֶת־בֵּ֥ית יְהוָ֖ה אֲשֶׁ֥ר בִּ⁠ירוּשָׁלִָֽם׃","bá̇r֥ẇkĕ yĕhwá֖h ʼèlòhé֣y ʼàbwòţé֑y⁠nẇ ʼàşě֨r náţa֤n ká̇⁠zòʼţ֙ bĕ̇⁠lé֣b ha⁠mė֔lekĕ lĕ⁠páʼé֕r ʼeţ-bé֥̇yţ yĕhwá֖h ʼàşě֥r bi̇⁠yrẇşá̌liáֽm׃"],[7,28,"וְ⁠עָלַ֣⁠י הִטָּה־חֶ֗סֶד לִ⁠פְנֵ֤י הַ⁠מֶּ֨לֶךְ֙ וְ⁠יֽוֹעֲצָ֔י⁠ו וּ⁠לְ⁠כָל־שָׂרֵ֥י הַ⁠מֶּ֖לֶךְ הַ⁠גִּבֹּרִ֑ים וַ⁠אֲנִ֣י הִתְחַזַּ֗קְתִּי כְּ⁠יַד־יְהוָ֤ה אֱלֹהַ⁠י֙ עָלַ֔⁠י וָ⁠אֶקְבְּצָ֧⁠ה מִ⁠יִּשְׂרָאֵ֛ל רָאשִׁ֖ים לַ⁠עֲל֥וֹת עִמִּֽ⁠י׃פ","wĕ⁠ʻála֣⁠y hitá̇h-ẖe֗sed li⁠pĕné֤y ha⁠mė֨lekĕ֙ wĕ⁠yֽwòʻàẕá֔y⁠w ẇ⁠lĕ⁠kál-şá̂ré֥y ha⁠mė֖lekĕ ha⁠gi̇bò̇ri֑ym wa⁠ʼàni֣y hiţĕẖazȧ֗qĕţi̇y kĕ̇⁠yad-yĕhwá֤h ʼèlòha⁠y֙ ʻála֔⁠y wá⁠ʼeqĕbĕ̇ẕá֧⁠h mi⁠yi̇şĕ̂ráʼé֛l ráʼşǐ֖ym la⁠ʻàl֥wòţ ʻimiֽ̇⁠y׃p"],[8,1,"וְ⁠אֵ֛לֶּה רָאשֵׁ֥י אֲבֹתֵי⁠הֶ֖ם וְ⁠הִתְיַחְשָׂ֑⁠ם הָ⁠עֹלִ֣ים עִמִּ֗⁠י בְּ⁠מַלְכ֛וּת אַרְתַּחְשַׁ֥סְתְּא הַ⁠מֶּ֖לֶךְ מִ⁠בָּבֶֽל׃ס","wĕ⁠ʼé֛lėh ráʼşé֥̌y ʼàbòţéy⁠he֖m wĕ⁠hiţĕyaẖĕşá֑̂⁠m há⁠ʻòli֣ym ʻimi̇֗⁠y bĕ̇⁠malĕk֛ẇţ ʼarĕţȧẖĕşǎ֥sĕţĕ̇ʼ ha⁠mė֖lekĕ mi⁠bá̇beֽl׃s"],[8,2,"מִ⁠בְּנֵ֤י פִֽינְחָס֙ גֵּֽרְשֹׁ֔ם ס מִ⁠בְּנֵ֥י אִיתָמָ֖ר דָּנִיֵּ֑אל ס מִ⁠בְּנֵ֥י דָוִ֖יד חַטּֽוּשׁ׃ס","mi⁠bĕ̇né֤y piֽynĕẖás֙ géֽ̇rĕşò̌֔m s mi⁠bĕ̇né֥y ʼiyţámá֖r dá̇niyé֑̇ʼl s mi⁠bĕ̇né֥y dáwi֖yd ẖaṫֽẇş̌׃s"],[8,3,"מִ⁠בְּנֵ֣י שְׁכַנְיָ֔ה ס מִ⁠בְּנֵ֥י פַרְעֹ֖שׁ זְכַרְיָ֑ה וְ⁠עִמּ֛⁠וֹ הִתְיַחֵ֥שׂ לִ⁠זְכָרִ֖ים מֵאָ֥ה וַ⁠חֲמִשִּֽׁים׃ס","mi⁠bĕ̇né֣y şĕ̌kanĕyá֔h s mi⁠bĕ̇né֥y parĕʻò֖ş̌ zĕkarĕyá֑h wĕ⁠ʻiṁ֛⁠wò hiţĕyaẖé֥ş̂ li⁠zĕkári֖ym méʼá֥h wa⁠ẖàmişiֽ̇̌ym׃s"],[8,4,"מִ⁠בְּנֵי֙ פַּחַ֣ת מוֹאָ֔ב אֶלְיְהֽוֹעֵינַ֖י בֶּן־זְרַֽחְיָ֑ה וְ⁠עִמּ֖⁠וֹ מָאתַ֥יִם הַ⁠זְּכָרִֽים׃ס","mi⁠bĕ̇néy֙ pȧẖa֣ţ mwòʼá֔b ʼelĕyĕhֽwòʻéyna֖y bėn-zĕraֽẖĕyá֑h wĕ⁠ʻiṁ֖⁠wò máʼţa֥yim ha⁠zĕ̇káriֽym׃s"],[8,5,"מִ⁠בְּנֵ֥י שְׁכַנְיָ֖ה בֶּן־יַחֲזִיאֵ֑ל וְ⁠עִמּ֕⁠וֹ שְׁלֹ֥שׁ מֵא֖וֹת הַ⁠זְּכָרִֽים׃ס","mi⁠bĕ̇né֥y şĕ̌kanĕyá֖h bėn-yaẖàziyʼé֑l wĕ⁠ʻiṁ֕⁠wò şĕ̌lò֥ş̌ méʼ֖wòţ ha⁠zĕ̇káriֽym׃s"],[8,6,"וּ⁠מִ⁠בְּנֵ֣י עָדִ֔ין עֶ֖בֶד בֶּן־יוֹנָתָ֑ן וְ⁠עִמּ֖⁠וֹ חֲמִשִּׁ֥ים הַ⁠זְּכָרִֽים׃ס","ẇ⁠mi⁠bĕ̇né֣y ʻádi֔yn ʻe֖bed bėn-ywònáţá֑n wĕ⁠ʻiṁ֖⁠wò ẖàmişi֥̇̌ym ha⁠zĕ̇káriֽym׃s"],[8,7,"וּ⁠מִ⁠בְּנֵ֣י עֵילָ֔ם יְשַֽׁעְיָ֖ה בֶּן־עֲתַלְיָ֑ה וְ⁠עִמּ֖⁠וֹ שִׁבְעִ֥ים הַ⁠זְּכָרִֽים׃ס","ẇ⁠mi⁠bĕ̇né֣y ʻéylá֔m yĕşǎֽʻĕyá֖h bėn-ʻàţalĕyá֑h wĕ⁠ʻiṁ֖⁠wò şǐbĕʻi֥ym ha⁠zĕ̇káriֽym׃s"],[8,8,"וּ⁠מִ⁠בְּנֵ֣י שְׁפַטְיָ֔ה זְבַדְיָ֖ה בֶּן־מִֽיכָאֵ֑ל וְ⁠עִמּ֖⁠וֹ שְׁמֹנִ֥ים הַ⁠זְּכָרִֽים׃ס","ẇ⁠mi⁠bĕ̇né֣y şĕ̌patĕyá֔h zĕbadĕyá֖h bėn-miֽykáʼé֑l wĕ⁠ʻiṁ֖⁠wò şĕ̌mòni֥ym ha⁠zĕ̇káriֽym׃s"],[8,9,"מִ⁠בְּנֵ֣י יוֹאָ֔ב עֹבַדְיָ֖ה בֶּן־יְחִיאֵ֑ל וְ⁠עִמּ֕⁠וֹ מָאתַ֛יִם וּ⁠שְׁמֹנָ֥ה עָשָׂ֖ר הַ⁠זְּכָרִֽים׃ס","mi⁠bĕ̇né֣y ywòʼá֔b ʻòbadĕyá֖h bėn-yĕẖiyʼé֑l wĕ⁠ʻiṁ֕⁠wò máʼţa֛yim ẇ⁠şĕ̌mòná֥h ʻáşá֖̂r ha⁠zĕ̇káriֽym׃s"],[8,10,"וּ⁠מִ⁠בְּנֵ֥י שְׁלוֹמִ֖ית בֶּן־יוֹסִפְיָ֑ה וְ⁠עִמּ֕⁠וֹ מֵאָ֥ה וְ⁠שִׁשִּׁ֖ים הַ⁠זְּכָרִֽים׃ס","ẇ⁠mi⁠bĕ̇né֥y şĕ̌lwòmi֖yţ bėn-ywòsipĕyá֑h wĕ⁠ʻiṁ֕⁠wò méʼá֥h wĕ⁠şǐşi֖̇̌ym ha⁠zĕ̇káriֽym׃s"],[8,11,"וּ⁠מִ⁠בְּנֵ֣י בֵבַ֔י זְכַרְיָ֖ה בֶּן־בֵּבָ֑י וְ⁠עִמּ֕⁠וֹ עֶשְׂרִ֥ים וּ⁠שְׁמֹנָ֖ה הַ⁠זְּכָרִֽים׃ס","ẇ⁠mi⁠bĕ̇né֣y béba֔y zĕkarĕyá֖h bėn-bé̇bá֑y wĕ⁠ʻiṁ֕⁠wò ʻeşĕ̂ri֥ym ẇ⁠şĕ̌mòná֖h ha⁠zĕ̇káriֽym׃s"],[8,12,"וּ⁠מִ⁠בְּנֵ֣י עַזְגָּ֔ד יוֹחָנָ֖ן בֶּן־הַ⁠קָּטָ֑ן וְ⁠עִמּ֕⁠וֹ מֵאָ֥ה וַ⁠עֲשָׂרָ֖ה הַ⁠זְּכָרִֽים׃ס","ẇ⁠mi⁠bĕ̇né֣y ʻazĕgá̇֔d ywòẖáná֖n bėn-ha⁠qá̇tá֑n wĕ⁠ʻiṁ֕⁠wò méʼá֥h wa⁠ʻàşá̂rá֖h ha⁠zĕ̇káriֽym׃s"],[8,13,"וּ⁠מִ⁠בְּנֵ֣י אֲדֹנִיקָם֮ אַחֲרֹנִים֒ וְ⁠אֵ֣לֶּה שְׁמוֹתָ֔⁠ם אֱלִיפֶ֖לֶט יְעִיאֵ֣ל וּֽ⁠שְׁמַעְיָ֑ה וְ⁠עִמָּ⁠הֶ֖ם שִׁשִּׁ֥ים הַ⁠זְּכָרִֽים׃ס","ẇ⁠mi⁠bĕ̇né֣y ʼàdòniyqám֮ ʼaẖàròniym֒ wĕ⁠ʼé֣lėh şĕ̌mwòţá֔⁠m ʼèliype֖let yĕʻiyʼé֣l ẇֽ⁠şĕ̌maʻĕyá֑h wĕ⁠ʻimá̇⁠he֖m şǐşi֥̇̌ym ha⁠zĕ̇káriֽym׃s"],[8,14,"וּ⁠מִ⁠בְּנֵ֥י בִגְוַ֖י עוּתַ֣י ו⁠זבוד וְ⁠עִמּ֖⁠וֹ שִׁבְעִ֥ים הַ⁠זְּכָרִֽים׃פ","ẇ⁠mi⁠bĕ̇né֥y bigĕwa֖y ʻẇţa֣y w⁠zbwd wĕ⁠ʻiṁ֖⁠wò şǐbĕʻi֥ym ha⁠zĕ̇káriֽym׃p"],[8,15,"וָֽ⁠אֶקְבְּצֵ֗⁠ם אֶל־הַ⁠נָּהָר֙ הַ⁠בָּ֣א אֶֽל־אַהֲוָ֔א וַ⁠נַּחֲנֶ֥ה שָׁ֖ם יָמִ֣ים שְׁלֹשָׁ֑ה וָ⁠אָבִ֤ינָ⁠ה בָ⁠עָם֙ וּ⁠בַ⁠כֹּ֣הֲנִ֔ים וּ⁠מִ⁠בְּנֵ֥י לֵוִ֖י לֹא־מָצָ֥אתִי שָֽׁם׃","wáֽ⁠ʼeqĕbĕ̇ẕé֗⁠m ʼel-ha⁠ná̇hár֙ ha⁠bá֣̇ʼ ʼeֽl-ʼahàwá֔ʼ wa⁠nȧẖàne֥h şá֖̌m yámi֣ym şĕ̌lòşá֑̌h wá⁠ʼábi֤yná⁠h bá⁠ʻám֙ ẇ⁠ba⁠kò֣̇hàni֔ym ẇ⁠mi⁠bĕ̇né֥y léwi֖y lòʼ-máẕá֥ʼţiy şáֽ̌m׃"],[8,16,"וָ⁠אֶשְׁלְחָ֡⁠ה לֶ⁠אֱלִיעֶ֡זֶר לַ⁠אֲרִיאֵ֡ל לִֽ֠⁠שְׁמַעְיָה וּ⁠לְ⁠אֶלְנָתָ֨ן וּ⁠לְ⁠יָרִ֜יב וּ⁠לְ⁠אֶלְנָתָ֧ן וּ⁠לְ⁠נָתָ֛ן וְ⁠לִ⁠זְכַרְיָ֥ה וְ⁠לִ⁠מְשֻׁלָּ֖ם רָאשִׁ֑ים וּ⁠לְ⁠יוֹיָרִ֥יב וּ⁠לְ⁠אֶלְנָתָ֖ן מְבִינִֽים׃","wá⁠ʼeşĕ̌lĕẖá֡⁠h le⁠ʼèliyʻe֡zer la⁠ʼàriyʼé֡l liֽ֠⁠şĕ̌maʻĕyáh ẇ⁠lĕ⁠ʼelĕnáţá֨n ẇ⁠lĕ⁠yári֜yb ẇ⁠lĕ⁠ʼelĕnáţá֧n ẇ⁠lĕ⁠náţá֛n wĕ⁠li⁠zĕkarĕyá֥h wĕ⁠li⁠mĕşǔlá֖̇m ráʼşǐ֑ym ẇ⁠lĕ⁠ywòyári֥yb ẇ⁠lĕ⁠ʼelĕnáţá֖n mĕbiyniֽym׃"],[8,17,"ו⁠אוצא⁠ה אוֹתָ⁠ם֙ עַל־אִדּ֣וֹ הָ⁠רֹ֔אשׁ בְּ⁠כָסִפְיָ֖א הַ⁠מָּק֑וֹם וָ⁠אָשִׂימָ⁠ה֩ בְּ⁠פִי⁠הֶ֨ם דְּבָרִ֜ים לְ֠⁠דַבֵּר אֶל־אִדּ֨וֹ אָחִ֤י⁠ו ה⁠נתונים בְּ⁠כָסִפְיָ֣א הַ⁠מָּק֔וֹם לְ⁠הָֽבִיא־לָ֥⁠נוּ מְשָׁרְתִ֖ים לְ⁠בֵ֥ית אֱלֹהֵֽי⁠נוּ׃","w⁠ʼwẕʼ⁠h ʼwòţá⁠m֙ ʻal-ʼiḋ֣wò há⁠rò֔ʼş̌ bĕ̇⁠kásipĕyá֖ʼ ha⁠má̇q֑wòm wá⁠ʼáşîymá⁠h֩ bĕ̇⁠piy⁠he֨m dĕ̇bári֜ym lĕ֠⁠dabé̇r ʼel-ʼiḋ֨wò ʼáẖi֤y⁠w h⁠nţwnym bĕ̇⁠kásipĕyá֣ʼ ha⁠má̇q֔wòm lĕ⁠háֽbiyʼ-lá֥⁠nẇ mĕşá̌rĕţi֖ym lĕ⁠bé֥yţ ʼèlòhéֽy⁠nẇ׃"],[8,18,"וַ⁠יָּבִ֨יאּוּ לָ֜⁠נוּ כְּ⁠יַד־אֱלֹהֵ֨י⁠נוּ הַ⁠טּוֹבָ֤ה עָלֵ֨י⁠נוּ֙ אִ֣ישׁ שֶׂ֔כֶל מִ⁠בְּנֵ֣י מַחְלִ֔י בֶּן־לֵוִ֖י בֶּן־יִשְׂרָאֵ֑ל וְ⁠שֵׁרֵֽבְיָ֛ה וּ⁠בָנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁמֹנָ֥ה עָשָֽׂר׃","wa⁠yá̇bi֨yʼ̇ẇ lá֜⁠nẇ kĕ̇⁠yad-ʼèlòhé֨y⁠nẇ ha⁠ṫwòbá֤h ʻálé֨y⁠nẇ֙ ʼi֣yş̌ şê֔kel mi⁠bĕ̇né֣y maẖĕli֔y bėn-léwi֖y bėn-yişĕ̂ráʼé֑l wĕ⁠şé̌réֽbĕyá֛h ẇ⁠báná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌mòná֥h ʻáşáֽ̂r׃"],[8,19,"וְ⁠אֶת־חֲשַׁבְיָ֔ה וְ⁠אִתּ֥⁠וֹ יְשַֽׁעְיָ֖ה מִ⁠בְּנֵ֣י מְרָרִ֑י אֶחָ֥י⁠ו וּ⁠בְנֵי⁠הֶ֖ם עֶשְׂרִֽים׃ס","wĕ⁠ʼeţ-ẖàşǎbĕyá֔h wĕ⁠ʼiţ֥̇⁠wò yĕşǎֽʻĕyá֖h mi⁠bĕ̇né֣y mĕrári֑y ʼeẖá֥y⁠w ẇ⁠bĕnéy⁠he֖m ʻeşĕ̂riֽym׃s"],[8,20,"וּ⁠מִן־הַ⁠נְּתִינִ֗ים שֶׁ⁠נָּתַ֨ן דָּוִ֤יד וְ⁠הַ⁠שָּׂרִים֙ לַ⁠עֲבֹדַ֣ת הַ⁠לְוִיִּ֔ם נְתִינִ֖ים מָאתַ֣יִם וְ⁠עֶשְׂרִ֑ים כֻּלָּ֖⁠ם נִקְּב֥וּ בְ⁠שֵׁמֽוֹת׃","ẇ⁠min-ha⁠nĕ̇ţiyni֗ym şě⁠ná̇ţa֨n dá̇wi֤yd wĕ⁠ha⁠şá̇̂riym֙ la⁠ʻàbòda֣ţ ha⁠lĕwiyi̇֔m nĕţiyni֖ym máʼţa֣yim wĕ⁠ʻeşĕ̂ri֑ym ku̇lá֖̇⁠m niqĕ̇b֥ẇ bĕ⁠şé̌mֽwòţ׃"],[8,21,"וָ⁠אֶקְרָ֨א שָׁ֥ם צוֹם֙ עַל־הַ⁠נָּהָ֣ר אַהֲוָ֔א לְ⁠הִתְעַנּ֖וֹת לִ⁠פְנֵ֣י אֱלֹהֵ֑י⁠נוּ לְ⁠בַקֵּ֤שׁ מִמֶּ֨⁠נּוּ֙ דֶּ֣רֶךְ יְשָׁרָ֔ה לָ֥⁠נוּ וּ⁠לְ⁠טַפֵּ֖⁠נוּ וּ⁠לְ⁠כָל־רְכוּשֵֽׁ⁠נוּ׃","wá⁠ʼeqĕrá֨ʼ şá֥̌m ẕwòm֙ ʻal-ha⁠ná̇há֣r ʼahàwá֔ʼ lĕ⁠hiţĕʻaṅ֖wòţ li⁠pĕné֣y ʼèlòhé֑y⁠nẇ lĕ⁠baqé֤̇ş̌ mimė֨⁠ṅẇ֙ dė֣rekĕ yĕşá̌rá֔h lá֥⁠nẇ ẇ⁠lĕ⁠tapé֖̇⁠nẇ ẇ⁠lĕ⁠kál-rĕkẇşéֽ̌⁠nẇ׃"],[8,22,"כִּ֣י בֹ֗שְׁתִּי לִ⁠שְׁא֤וֹל מִן־הַ⁠מֶּ֨לֶךְ֙ חַ֣יִל וּ⁠פָרָשִׁ֔ים לְ⁠עָזְרֵ֥⁠נוּ מֵ⁠אוֹיֵ֖ב בַּ⁠דָּ֑רֶךְ כִּֽי־אָמַ֨רְנוּ לַ⁠מֶּ֜לֶךְ לֵ⁠אמֹ֗ר יַד־אֱלֹהֵ֤י⁠נוּ עַל־כָּל־מְבַקְשָׁי⁠ו֙ לְ⁠טוֹבָ֔ה וְ⁠עֻזּ֣⁠וֹ וְ⁠אַפּ֔⁠וֹ עַ֖ל כָּל־עֹזְבָֽי⁠ו׃","ki֣̇y bò֗şĕ̌ţi̇y li⁠şĕ̌ʼ֤wòl min-ha⁠mė֨lekĕ֙ ẖa֣yil ẇ⁠páráşǐ֔ym lĕ⁠ʻázĕré֥⁠nẇ mé⁠ʼwòyé֖b bȧ⁠dá֑̇rekĕ kiֽ̇y-ʼáma֨rĕnẇ la⁠mė֜lekĕ lé⁠ʼmò֗r yad-ʼèlòhé֤y⁠nẇ ʻal-ká̇l-mĕbaqĕşá̌y⁠w֙ lĕ⁠twòbá֔h wĕ⁠ʻuż֣⁠wò wĕ⁠ʼaṗ֔⁠wò ʻa֖l ká̇l-ʻòzĕbáֽy⁠w׃"],[8,23,"וַ⁠נָּצ֛וּמָ⁠ה וַ⁠נְּבַקְשָׁ֥⁠ה מֵ⁠אֱלֹהֵ֖י⁠נוּ עַל־זֹ֑את וַ⁠יֵּעָתֵ֖ר לָֽ⁠נוּ׃","wa⁠ná̇ẕ֛ẇmá⁠h wa⁠nĕ̇baqĕşá֥̌⁠h mé⁠ʼèlòhé֖y⁠nẇ ʻal-zò֑ʼţ wa⁠yé̇ʻáţé֖r láֽ⁠nẇ׃"],[8,24,"וָ⁠אַבְדִּ֛ילָ⁠ה מִ⁠שָּׂרֵ֥י הַ⁠כֹּהֲנִ֖ים שְׁנֵ֣ים עָשָׂ֑ר לְ⁠שֵׁרֵֽבְיָ֣ה חֲשַׁבְיָ֔ה וְ⁠עִמָּ⁠הֶ֥ם מֵ⁠אֲחֵי⁠הֶ֖ם עֲשָׂרָֽה׃","wá⁠ʼabĕdi֛̇ylá⁠h mi⁠şá̇̂ré֥y ha⁠kò̇hàni֖ym şĕ̌né֣ym ʻáşá֑̂r lĕ⁠şé̌réֽbĕyá֣h ẖàşǎbĕyá֔h wĕ⁠ʻimá̇⁠he֥m mé⁠ʼàẖéy⁠he֖m ʻàşá̂ráֽh׃"],[8,25,"ו⁠אשקול⁠ה לָ⁠הֶ֔ם אֶת־הַ⁠כֶּ֥סֶף וְ⁠אֶת־הַ⁠זָּהָ֖ב וְ⁠אֶת־הַ⁠כֵּלִ֑ים תְּרוּמַ֣ת בֵּית־אֱלֹהֵ֗י⁠נוּ הַ⁠הֵרִ֨ימוּ֙ הַ⁠מֶּ֨לֶךְ֙ וְ⁠יֹעֲצָ֣י⁠ו וְ⁠שָׂרָ֔י⁠ו וְ⁠כָל־יִשְׂרָאֵ֖ל הַ⁠נִּמְצָאִֽים׃","w⁠ʼşqwl⁠h lá⁠he֔m ʼeţ-ha⁠kė֥sep wĕ⁠ʼeţ-ha⁠zá̇há֖b wĕ⁠ʼeţ-ha⁠ké̇li֑ym ţĕ̇rẇma֣ţ bé̇yţ-ʼèlòhé֗y⁠nẇ ha⁠héri֨ymẇ֙ ha⁠mė֨lekĕ֙ wĕ⁠yòʻàẕá֣y⁠w wĕ⁠şá̂rá֔y⁠w wĕ⁠kál-yişĕ̂ráʼé֖l ha⁠ni̇mĕẕáʼiֽym׃"],[8,26,"וָ⁠אֶשְׁקֲלָ֨⁠ה עַל־יָדָ֜⁠ם כֶּ֗סֶף כִּכָּרִים֙ שֵֽׁשׁ־מֵא֣וֹת וַ⁠חֲמִשִּׁ֔ים וּ⁠כְלֵי־כֶ֥סֶף מֵאָ֖ה לְ⁠כִכָּרִ֑ים זָהָ֖ב מֵאָ֥ה כִכָּֽר׃","wá⁠ʼeşĕ̌qàlá֨⁠h ʻal-yádá֜⁠m kė֗sep ki̇ká̇riym֙ şéֽ̌ş̌-méʼ֣wòţ wa⁠ẖàmişi̇̌֔ym ẇ⁠kĕléy-ke֥sep méʼá֖h lĕ⁠kiká̇ri֑ym záhá֖b méʼá֥h kikáֽ̇r׃"],[8,27,"וּ⁠כְפֹרֵ֤י זָהָב֙ עֶשְׂרִ֔ים לַ⁠אֲדַרְכֹנִ֖ים אָ֑לֶף וּ⁠כְלֵ֨י נְחֹ֜שֶׁת מֻצְהָ֤ב טוֹבָה֙ שְׁנַ֔יִם חֲמוּדֹ֖ת כַּ⁠זָּהָֽב׃","ẇ⁠kĕpòré֤y záháb֙ ʻeşĕ̂ri֔ym la⁠ʼàdarĕkòni֖ym ʼá֑lep ẇ⁠kĕlé֨y nĕẖò֜şěţ muẕĕhá֤b twòbáh֙ şĕ̌na֔yim ẖàmẇdò֖ţ kȧ⁠zá̇háֽb׃"],[8,28,"וָ⁠אֹמְרָ֣⁠ה אֲלֵ⁠הֶ֗ם אַתֶּ֥ם קֹ֨דֶשׁ֙ לַ⁠יהוָ֔ה וְ⁠הַ⁠כֵּלִ֖ים קֹ֑דֶשׁ וְ⁠הַ⁠כֶּ֤סֶף וְ⁠הַ⁠זָּהָב֙ נְדָבָ֔ה לַ⁠יהוָ֖ה אֱלֹהֵ֥י אֲבֹתֵי⁠כֶֽם׃","wá⁠ʼòmĕrá֣⁠h ʼàlé⁠he֗m ʼaţė֥m qò֨deş̌֙ la⁠yhwá֔h wĕ⁠ha⁠ké̇li֖ym qò֑deş̌ wĕ⁠ha⁠kė֤sep wĕ⁠ha⁠zá̇háb֙ nĕdábá֔h la⁠yhwá֖h ʼèlòhé֥y ʼàbòţéy⁠keֽm׃"],[8,29,"שִׁקְד֣וּ וְ⁠שִׁמְר֗וּ עַֽד־תִּשְׁקְל֡וּ לִ⁠פְנֵי֩ שָׂרֵ֨י הַ⁠כֹּהֲנִ֧ים וְ⁠הַ⁠לְוִיִּ֛ם וְ⁠שָׂרֵֽי־הָ⁠אָב֥וֹת לְ⁠יִשְׂרָאֵ֖ל בִּ⁠ירוּשָׁלִָ֑ם הַ⁠לִּשְׁכ֖וֹת בֵּ֥ית יְהוָֽה׃","şǐqĕd֣ẇ wĕ⁠şǐmĕr֗ẇ ʻaֽd-ţi̇şĕ̌qĕl֡ẇ li⁠pĕnéy֩ şá̂ré֨y ha⁠kò̇hàni֧ym wĕ⁠ha⁠lĕwiyi֛̇m wĕ⁠şá̂réֽy-há⁠ʼáb֥wòţ lĕ⁠yişĕ̂ráʼé֖l bi̇⁠yrẇşá̌liá֑m ha⁠li̇şĕ̌k֖wòţ bé֥̇yţ yĕhwáֽh׃"],[8,30,"וְ⁠קִבְּלוּ֙ הַ⁠כֹּהֲנִ֣ים וְ⁠הַ⁠לְוִיִּ֔ם מִשְׁקַ֛ל הַ⁠כֶּ֥סֶף וְ⁠הַ⁠זָּהָ֖ב וְ⁠הַ⁠כֵּלִ֑ים לְ⁠הָבִ֥יא לִ⁠ירוּשָׁלִַ֖ם לְ⁠בֵ֥ית אֱלֹהֵֽי⁠נוּ׃פ","wĕ⁠qibĕ̇lẇ֙ ha⁠kò̇hàni֣ym wĕ⁠ha⁠lĕwiyi̇֔m mişĕ̌qa֛l ha⁠kė֥sep wĕ⁠ha⁠zá̇há֖b wĕ⁠ha⁠ké̇li֑ym lĕ⁠hábi֥yʼ li⁠yrẇşá̌lia֖m lĕ⁠bé֥yţ ʼèlòhéֽy⁠nẇ׃p"],[8,31,"וַֽ⁠נִּסְעָ֞⁠ה מִ⁠נְּהַ֣ר אַֽהֲוָ֗א בִּ⁠שְׁנֵ֤ים עָשָׂר֙ לַ⁠חֹ֣דֶשׁ הָ⁠רִאשׁ֔וֹן לָ⁠לֶ֖כֶת יְרוּשָׁלִָ֑ם וְ⁠יַד־אֱלֹהֵ֨י⁠נוּ֙ הָיְתָ֣ה עָלֵ֔י⁠נוּ וַ⁠יַּ֨צִּילֵ֔⁠נוּ מִ⁠כַּ֥ף אוֹיֵ֛ב וְ⁠אוֹרֵ֖ב עַל־הַ⁠דָּֽרֶךְ׃","waֽ⁠ni̇sĕʻá֞⁠h mi⁠nĕ̇ha֣r ʼֽahàwá֗ʼ bi̇⁠şĕ̌né֤ym ʻáşá̂r֙ la⁠ẖò֣deş̌ há⁠riʼş̌֔wòn lá⁠le֖keţ yĕrẇşá̌liá֑m wĕ⁠yad-ʼèlòhé֨y⁠nẇ֙ háyĕţá֣h ʻálé֔y⁠nẇ wa⁠yȧ֨ẕi̇ylé֔⁠nẇ mi⁠kȧ֥p ʼwòyé֛b wĕ⁠ʼwòré֖b ʻal-ha⁠dáֽ̇rekĕ׃"],[8,32,"וַ⁠נָּב֖וֹא יְרוּשָׁלִָ֑ם וַ⁠נֵּ֥שֶׁב שָׁ֖ם יָמִ֥ים שְׁלֹשָֽׁה׃","wa⁠ná̇b֖wòʼ yĕrẇşá̌liá֑m wa⁠né֥̇şěb şá֖̌m yámi֥ym şĕ̌lòşáֽ̌h׃"],[8,33,"וּ⁠בַ⁠יּ֣וֹם הָ⁠רְבִיעִ֡י נִשְׁקַ֣ל הַ⁠כֶּסֶף֩ וְ⁠הַ⁠זָּהָ֨ב וְ⁠הַ⁠כֵּלִ֜ים בְּ⁠בֵ֣ית אֱלֹהֵ֗י⁠נוּ עַ֠ל יַד־מְרֵמ֤וֹת בֶּן־אֽוּרִיָּה֙ הַ⁠כֹּהֵ֔ן וְ⁠עִמּ֖⁠וֹ אֶלְעָזָ֣ר בֶּן־פִּֽינְחָ֑ס וְ⁠עִמָּ⁠הֶ֞ם יוֹזָבָ֧ד בֶּן־יֵשׁ֛וּעַ וְ⁠נֽוֹעַדְיָ֥ה בֶן־בִּנּ֖וּי הַ⁠לְוִיִּֽם׃","ẇ⁠ba⁠ẏ֣wòm há⁠rĕbiyʻi֡y nişĕ̌qa֣l ha⁠kėsep֩ wĕ⁠ha⁠zá̇há֨b wĕ⁠ha⁠ké̇li֜ym bĕ̇⁠bé֣yţ ʼèlòhé֗y⁠nẇ ʻa֠l yad-mĕrém֤wòţ bėn-ʼֽẇriyá̇h֙ ha⁠kò̇hé֔n wĕ⁠ʻiṁ֖⁠wò ʼelĕʻázá֣r bėn-piֽ̇ynĕẖá֑s wĕ⁠ʻimá̇⁠he֞m ywòzábá֧d bėn-yéş֛̌ẇʻa wĕ⁠nֽwòʻadĕyá֥h ben-bi̇ṅ֖ẇy ha⁠lĕwiyiֽ̇m׃"],[8,34,"בְּ⁠מִסְפָּ֥ר בְּ⁠מִשְׁקָ֖ל לַ⁠כֹּ֑ל וַ⁠יִּכָּתֵ֥ב כָּֽל־הַ⁠מִּשְׁקָ֖ל בָּ⁠עֵ֥ת הַ⁠הִֽיא׃פ","bĕ̇⁠misĕpá֥̇r bĕ̇⁠mişĕ̌qá֖l la⁠kò֑̇l wa⁠yi̇ká̇ţé֥b káֽ̇l-ha⁠mi̇şĕ̌qá֖l bá̇⁠ʻé֥ţ ha⁠hiֽyʼ׃p"],[8,35,"הַ֠⁠בָּאִים מֵֽ⁠הַ⁠שְּׁבִ֨י בְנֵֽי־הַ⁠גּוֹלָ֜ה הִקְרִ֥יבוּ עֹל֣וֹת ׀ לֵ⁠אלֹהֵ֣י יִשְׂרָאֵ֗ל פָּרִ֨ים שְׁנֵים־עָשָׂ֤ר עַל־כָּל־יִשְׂרָאֵל֙ אֵילִ֣ים ׀ תִּשְׁעִ֣ים וְ⁠שִׁשָּׁ֗ה כְּבָשִׂים֙ שִׁבְעִ֣ים וְ⁠שִׁבְעָ֔ה צְפִירֵ֥י חַטָּ֖את שְׁנֵ֣ים עָשָׂ֑ר הַ⁠כֹּ֖ל עוֹלָ֥ה לַ⁠יהוָֽה׃פ","ha֠⁠bá̇ʼiym méֽ⁠ha⁠şĕ̇̌bi֨y bĕnéֽy-ha⁠ġwòlá֜h hiqĕri֥ybẇ ʻòl֣wòţ ׀ lé⁠ʼlòhé֣y yişĕ̂ráʼé֗l pá̇ri֨ym şĕ̌néym-ʻáşá֤̂r ʻal-ká̇l-yişĕ̂ráʼél֙ ʼéyli֣ym ׀ ţi̇şĕ̌ʻi֣ym wĕ⁠şǐşá̇̌֗h kĕ̇báşîym֙ şǐbĕʻi֣ym wĕ⁠şǐbĕʻá֔h ẕĕpiyré֥y ẖatá֖̇ʼţ şĕ̌né֣ym ʻáşá֑̂r ha⁠kò֖̇l ʻwòlá֥h la⁠yhwáֽh׃p"],[8,36,"וַֽ⁠יִּתְּנ֣וּ ׀ אֶת־דָּתֵ֣י הַ⁠מֶּ֗לֶךְ לַ⁠אֲחַשְׁדַּרְפְּנֵי֙ הַ⁠מֶּ֔לֶךְ וּ⁠פַחֲו֖וֹת עֵ֣בֶר הַ⁠נָּהָ֑ר וְ⁠נִשְּׂא֥וּ אֶת־הָ⁠עָ֖ם וְ⁠אֶת־בֵּֽית־הָ⁠אֱלֹהִֽים׃ס","waֽ⁠yi̇ţĕ̇n֣ẇ ׀ ʼeţ-dá̇ţé֣y ha⁠mė֗lekĕ la⁠ʼàẖaşĕ̌dȧrĕpĕ̇néy֙ ha⁠mė֔lekĕ ẇ⁠paẖàw֖wòţ ʻé֣ber ha⁠ná̇há֑r wĕ⁠nişĕ̇̂ʼ֥ẇ ʼeţ-há⁠ʻá֖m wĕ⁠ʼeţ-béֽ̇yţ-há⁠ʼèlòhiֽym׃s"],[9,1,"וּ⁠כְ⁠כַלּ֣וֹת אֵ֗לֶּה נִגְּשׁ֨וּ אֵלַ֤⁠י הַ⁠שָּׂרִים֙ לֵ⁠אמֹ֔ר לֹֽא־נִבְדְּל֞וּ הָ⁠עָ֤ם יִשְׂרָאֵל֙ וְ⁠הַ⁠כֹּהֲנִ֣ים וְ⁠הַ⁠לְוִיִּ֔ם מֵ⁠עַמֵּ֖י הָ⁠אֲרָצ֑וֹת כְּ֠⁠תוֹעֲבֹֽתֵי⁠הֶם לַ⁠כְּנַעֲנִ֨י הַ⁠חִתִּ֜י הַ⁠פְּרִזִּ֣י הַ⁠יְבוּסִ֗י הָֽ⁠עַמֹּנִי֙ הַ⁠מֹּ֣אָבִ֔י הַ⁠מִּצְרִ֖י וְ⁠הָ⁠אֱמֹרִֽי׃","ẇ⁠kĕ⁠kal֣̇wòţ ʼé֗lėh nigĕ̇ş̌֨ẇ ʼéla֤⁠y ha⁠şá̇̂riym֙ lé⁠ʼmò֔r lòֽʼ-nibĕdĕ̇l֞ẇ há⁠ʻá֤m yişĕ̂ráʼél֙ wĕ⁠ha⁠kò̇hàni֣ym wĕ⁠ha⁠lĕwiyi̇֔m mé⁠ʻamé֖̇y há⁠ʼàráẕ֑wòţ kĕ̇֠⁠ţwòʻàbòֽţéy⁠hem la⁠kĕ̇naʻàni֨y ha⁠ẖiţi̇֜y ha⁠pĕ̇rizi֣̇y ha⁠yĕbẇsi֗y háֽ⁠ʻamò̇niy֙ ha⁠mò֣̇ʼábi֔y ha⁠mi̇ẕĕri֖y wĕ⁠há⁠ʼèmòriֽy׃"],[9,2,"כִּֽי־נָשְׂא֣וּ מִ⁠בְּנֹֽתֵי⁠הֶ֗ם לָ⁠הֶם֙ וְ⁠לִ⁠בְנֵי⁠הֶ֔ם וְ⁠הִתְעָֽרְבוּ֙ זֶ֣רַע הַ⁠קֹּ֔דֶשׁ בְּ⁠עַמֵּ֖י הָ⁠אֲרָצ֑וֹת וְ⁠יַ֧ד הַ⁠שָּׂרִ֣ים וְ⁠הַ⁠סְּגָנִ֗ים הָֽיְתָ֛ה בַּ⁠מַּ֥עַל הַ⁠זֶּ֖ה רִאשׁוֹנָֽה׃ס","kiֽ̇y-náşĕ̂ʼ֣ẇ mi⁠bĕ̇nòֽţéy⁠he֗m lá⁠hem֙ wĕ⁠li⁠bĕnéy⁠he֔m wĕ⁠hiţĕʻáֽrĕbẇ֙ ze֣raʻ ha⁠qò̇֔deş̌ bĕ̇⁠ʻamé֖̇y há⁠ʼàráẕ֑wòţ wĕ⁠ya֧d ha⁠şá̇̂ri֣ym wĕ⁠ha⁠sĕ̇gáni֗ym háֽyĕţá֛h bȧ⁠mȧ֥ʻal ha⁠zė֖h riʼş̌wònáֽh׃s"],[9,3,"וּ⁠כְ⁠שָׁמְעִ⁠י֙ אֶת־הַ⁠דָּבָ֣ר הַ⁠זֶּ֔ה קָרַ֥עְתִּי אֶת־בִּגְדִ֖⁠י וּ⁠מְעִילִ֑⁠י וָ⁠אֶמְרְטָ֞⁠ה מִ⁠שְּׂעַ֤ר רֹאשִׁ⁠י֙ וּ⁠זְקָנִ֔⁠י וָ⁠אֵשְׁבָ֖⁠ה מְשׁוֹמֵֽם׃","ẇ⁠kĕ⁠şá̌mĕʻi⁠y֙ ʼeţ-ha⁠dá̇bá֣r ha⁠zė֔h qára֥ʻĕţi̇y ʼeţ-bi̇gĕdi֖⁠y ẇ⁠mĕʻiyli֑⁠y wá⁠ʼemĕrĕtá֞⁠h mi⁠şĕ̇̂ʻa֤r ròʼşǐ⁠y֙ ẇ⁠zĕqáni֔⁠y wá⁠ʼéşĕ̌bá֖⁠h mĕş̌wòméֽm׃"],[9,4,"וְ⁠אֵלַ֣⁠י יֵאָסְפ֗וּ כֹּ֤ל חָרֵד֙ בְּ⁠דִבְרֵ֣י אֱלֹהֵֽי־יִשְׂרָאֵ֔ל עַ֖ל מַ֣עַל הַ⁠גּוֹלָ֑ה וַ⁠אֲנִי֙ יֹשֵׁ֣ב מְשׁוֹמֵ֔ם עַ֖ד לְ⁠מִנְחַ֥ת הָ⁠עָֽרֶב׃","wĕ⁠ʼéla֣⁠y yéʼásĕp֗ẇ kò֤̇l ẖáréd֙ bĕ̇⁠dibĕré֣y ʼèlòhéֽy-yişĕ̂ráʼé֔l ʻa֖l ma֣ʻal ha⁠ġwòlá֑h wa⁠ʼàniy֙ yòşé֣̌b mĕş̌wòmé֔m ʻa֖d lĕ⁠minĕẖa֥ţ há⁠ʻáֽreb׃"],[9,5,"וּ⁠בְ⁠מִנְחַ֣ת הָ⁠עֶ֗רֶב קַ֚מְתִּי מִ⁠תַּֽעֲנִיתִ֔⁠י וּ⁠בְ⁠קָרְעִ֥⁠י בִגְדִ֖⁠י וּ⁠מְעִילִ֑⁠י וָֽ⁠אֶכְרְעָ⁠ה֙ עַל־בִּרְכַּ֔⁠י וָ⁠אֶפְרְשָׂ֥⁠ה כַפַּ֖⁠י אֶל־יְהוָ֥ה אֱלֹהָֽ⁠י׃","ẇ⁠bĕ⁠minĕẖa֣ţ há⁠ʻe֗reb qa֚mĕţi̇y mi⁠ţȧֽʻàniyţi֔⁠y ẇ⁠bĕ⁠qárĕʻi֥⁠y bigĕdi֖⁠y ẇ⁠mĕʻiyli֑⁠y wáֽ⁠ʼekĕrĕʻá⁠h֙ ʻal-bi̇rĕkȧ֔⁠y wá⁠ʼepĕrĕşá֥̂⁠h kapȧ֖⁠y ʼel-yĕhwá֥h ʼèlòháֽ⁠y׃"],[9,6,"וָ⁠אֹמְרָ֗⁠ה אֱלֹהַ⁠י֙ בֹּ֣שְׁתִּי וְ⁠נִכְלַ֔מְתִּי לְ⁠הָרִ֧ים אֱלֹהַ֛⁠י פָּנַ֖⁠י אֵלֶ֑י⁠ךָ כִּ֣י עֲוֺנֹתֵ֤י⁠נוּ רָבוּ֙ לְ⁠מַ֣עְלָ⁠ה רֹּ֔אשׁ וְ⁠אַשְׁמָתֵ֥⁠נוּ גָדְלָ֖ה עַ֥ד לַ⁠שָּׁמָֽיִם׃","wá⁠ʼòmĕrá֗⁠h ʼèlòha⁠y֙ bò֣̇şĕ̌ţi̇y wĕ⁠nikĕla֔mĕţi̇y lĕ⁠hári֧ym ʼèlòha֛⁠y pá̇na֖⁠y ʼéle֑y⁠ká ki֣̇y ʻàwֺnòţé֤y⁠nẇ rábẇ֙ lĕ⁠ma֣ʻĕlá⁠h rò̇֔ʼş̌ wĕ⁠ʼaşĕ̌máţé֥⁠nẇ gádĕlá֖h ʻa֥d la⁠şá̇̌máֽyim׃"],[9,7,"מִ⁠ימֵ֣י אֲבֹתֵ֗י⁠נוּ אֲנַ֨חְנוּ֙ בְּ⁠אַשְׁמָ֣ה גְדֹלָ֔ה עַ֖ד הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה וּ⁠בַ⁠עֲוֺנֹתֵ֡י⁠נוּ נִתַּ֡נּוּ אֲנַחְנוּ֩ מְלָכֵ֨י⁠נוּ כֹהֲנֵ֜י⁠נוּ בְּ⁠יַ֣ד ׀ מַלְכֵ֣י הָ⁠אֲרָצ֗וֹת בַּ⁠חֶ֜רֶב בַּ⁠שְּׁבִ֧י וּ⁠בַ⁠בִּזָּ֛ה וּ⁠בְ⁠בֹ֥שֶׁת פָּנִ֖ים כְּ⁠הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","mi⁠ymé֣y ʼàbòţé֗y⁠nẇ ʼàna֨ẖĕnẇ֙ bĕ̇⁠ʼaşĕ̌má֣h gĕdòlá֔h ʻa֖d ha⁠ẏ֣wòm ha⁠zė֑h ẇ⁠ba⁠ʻàwֺnòţé֡y⁠nẇ niţȧ֡ṅẇ ʼànaẖĕnẇ֩ mĕláké֨y⁠nẇ kòhàné֜y⁠nẇ bĕ̇⁠ya֣d ׀ malĕké֣y há⁠ʼàráẕ֗wòţ bȧ⁠ẖe֜reb bȧ⁠şĕ̇̌bi֧y ẇ⁠ba⁠bi̇zá֛̇h ẇ⁠bĕ⁠bò֥şěţ pá̇ni֖ym kĕ̇⁠ha⁠ẏ֥wòm ha⁠zėֽh׃"],[9,8,"וְ⁠עַתָּ֡ה כִּ⁠מְעַט־רֶגַע֩ הָיְתָ֨ה תְחִנָּ֜ה מֵ⁠אֵ֣ת ׀ יְהוָ֣ה אֱלֹהֵ֗י⁠נוּ לְ⁠הַשְׁאִ֥יר לָ֨⁠נוּ֙ פְּלֵיטָ֔ה וְ⁠לָ⁠תֶת־לָ֥⁠נוּ יָתֵ֖ד בִּ⁠מְק֣וֹם קָדְשׁ֑⁠וֹ לְ⁠הָאִ֤יר עֵינֵ֨י⁠נוּ֙ אֱלֹהֵ֔י⁠נוּ וּ⁠לְ⁠תִתֵּ֛⁠נוּ מִֽחְיָ֥ה מְעַ֖ט בְּ⁠עַבְדֻתֵֽ⁠נוּ׃","wĕ⁠ʻaţá̇֡h ki̇⁠mĕʻat-regaʻ֩ háyĕţá֨h ţĕẖiná̇֜h mé⁠ʼé֣ţ ׀ yĕhwá֣h ʼèlòhé֗y⁠nẇ lĕ⁠haşĕ̌ʼi֥yr lá֨⁠nẇ֙ pĕ̇léytá֔h wĕ⁠lá⁠ţeţ-lá֥⁠nẇ yáţé֖d bi̇⁠mĕq֣wòm qádĕş֑̌⁠wò lĕ⁠háʼi֤yr ʻéyné֨y⁠nẇ֙ ʼèlòhé֔y⁠nẇ ẇ⁠lĕ⁠ţiţé֛̇⁠nẇ miֽẖĕyá֥h mĕʻa֖t bĕ̇⁠ʻabĕduţéֽ⁠nẇ׃"],[9,9,"כִּֽי־עֲבָדִ֣ים אֲנַ֔חְנוּ וּ⁠בְ⁠עַבְדֻ֔תֵ⁠נוּ לֹ֥א עֲזָבָ֖⁠נוּ אֱלֹהֵ֑י⁠נוּ וַֽ⁠יַּט־עָלֵ֣י⁠נוּ חֶ֡סֶד לִ⁠פְנֵי֩ מַלְכֵ֨י פָרַ֜ס לָֽ⁠תֶת־לָ֣⁠נוּ מִֽחְיָ֗ה לְ⁠רוֹמֵ֞ם אֶת־בֵּ֤ית אֱלֹהֵ֨י⁠נוּ֙ וּ⁠לְ⁠הַעֲמִ֣יד אֶת־חָרְבֹתָ֔י⁠ו וְ⁠לָֽ⁠תֶת־לָ֣⁠נוּ גָדֵ֔ר בִּֽ⁠יהוּדָ֖ה וּ⁠בִ⁠ירוּשָׁלִָֽם׃ס","kiֽ̇y-ʻàbádi֣ym ʼàna֔ẖĕnẇ ẇ⁠bĕ⁠ʻabĕdu֔ţé⁠nẇ lò֥ʼ ʻàzábá֖⁠nẇ ʼèlòhé֑y⁠nẇ wֽa⁠yȧt-ʻálé֣y⁠nẇ ẖe֡sed li⁠pĕnéy֩ malĕké֨y pára֜s láֽ⁠ţeţ-lá֣⁠nẇ miֽẖĕyá֗h lĕ⁠rwòmé֞m ʼeţ-bé֤̇yţ ʼèlòhé֨y⁠nẇ֙ ẇ⁠lĕ⁠haʻàmi֣yd ʼeţ-ẖárĕbòţá֔y⁠w wĕ⁠láֽ⁠ţeţ-lá֣⁠nẇ gádé֔r biֽ̇⁠yhẇdá֖h ẇ⁠bi⁠yrẇşá̌liáֽm׃s"],[9,10,"וְ⁠עַתָּ֛ה מַה־נֹּאמַ֥ר אֱלֹהֵ֖י⁠נוּ אַֽחֲרֵי־זֹ֑את כִּ֥י עָזַ֖בְנוּ מִצְוֺתֶֽי⁠ךָ׃","wĕ⁠ʻaţá֛̇h mah-nò̇ʼma֥r ʼèlòhé֖y⁠nẇ ʼֽaẖàréy-zò֑ʼţ ki֥̇y ʻáza֖bĕnẇ miẕĕwֺţeֽy⁠ká׃"],[9,11,"אֲשֶׁ֣ר צִוִּ֗יתָ בְּ⁠יַ֨ד עֲבָדֶ֣י⁠ךָ הַ⁠נְּבִיאִים֮ לֵ⁠אמֹר֒ הָ⁠אָ֗רֶץ אֲשֶׁ֨ר אַתֶּ֤ם בָּאִים֙ לְ⁠רִשְׁתָּ֔⁠הּ אֶ֤רֶץ נִדָּה֙ הִ֔יא בְּ⁠נִדַּ֖ת עַמֵּ֣י הָ⁠אֲרָצ֑וֹת בְּ⁠תוֹעֲבֹֽתֵי⁠הֶ֗ם אֲשֶׁ֥ר מִלְא֛וּ⁠הָ מִ⁠פֶּ֥ה אֶל־פֶּ֖ה בְּ⁠טֻמְאָתָֽ⁠ם׃","ʼàşě֣r ẕiwi̇֗yţá bĕ̇⁠ya֨d ʻàbáde֣y⁠ká ha⁠nĕ̇biyʼiym֮ lé⁠ʼmòr֒ há⁠ʼá֗reẕ ʼàşě֨r ʼaţė֤m bá̇ʼiym֙ lĕ⁠rişĕ̌ţá̇֔⁠ḣ ʼe֤reẕ nidá̇h֙ hi֔yʼ bĕ̇⁠nidȧ֖ţ ʻamé֣̇y há⁠ʼàráẕ֑wòţ bĕ̇⁠ţwòʻàbòֽţéy⁠he֗m ʼàşě֥r milĕʼ֛ẇ⁠há mi⁠pė֥h ʼel-pė֖h bĕ̇⁠tumĕʼáţáֽ⁠m׃"],[9,12,"וְ֠⁠עַתָּה בְּֽנוֹתֵי⁠כֶ֞ם אַל־תִּתְּנ֣וּ לִ⁠בְנֵי⁠הֶ֗ם וּ⁠בְנֹֽתֵי⁠הֶם֙ אַל־תִּשְׂא֣וּ לִ⁠בְנֵי⁠כֶ֔ם וְ⁠לֹֽא־תִדְרְשׁ֧וּ שְׁלֹמָ֛⁠ם וְ⁠טוֹבָתָ֖⁠ם עַד־עוֹלָ֑ם לְמַ֣עַן תֶּחֶזְק֗וּ וַ⁠אֲכַלְתֶּם֙ אֶת־ט֣וּב הָ⁠אָ֔רֶץ וְ⁠הוֹרַשְׁתֶּ֥ם לִ⁠בְנֵי⁠כֶ֖ם עַד־עוֹלָֽם׃","wĕ֠⁠ʻaţá̇h bĕֽ̇nwòţéy⁠ke֞m ʼal-ţi̇ţĕ̇n֣ẇ li⁠bĕnéy⁠he֗m ẇ⁠bĕnòֽţéy⁠hem֙ ʼal-ţi̇şĕ̂ʼ֣ẇ li⁠bĕnéy⁠ke֔m wĕ⁠lòֽʼ-ţidĕrĕş֧̌ẇ şĕ̌lòmá֛⁠m wĕ⁠twòbáţá֖⁠m ʻad-ʻwòlá֑m lĕma֣ʻan ţėẖezĕq֗ẇ wa⁠ʼàkalĕţėm֙ ʼeţ-t֣ẇb há⁠ʼá֔reẕ wĕ⁠hwòraşĕ̌ţė֥m li⁠bĕnéy⁠ke֖m ʻad-ʻwòláֽm׃"],[9,13,"וְ⁠אַֽחֲרֵי֙ כָּל־הַ⁠בָּ֣א עָלֵ֔י⁠נוּ בְּ⁠מַעֲשֵׂ֨י⁠נוּ֙ הָ⁠רָעִ֔ים וּ⁠בְ⁠אַשְׁמָתֵ֖⁠נוּ הַ⁠גְּדֹלָ֑ה כִּ֣י ׀ אַתָּ֣ה אֱלֹהֵ֗י⁠נוּ חָשַׂ֤כְתָּֽ לְ⁠מַ֨טָּה֙ מֵֽ⁠עֲוֺנֵ֔⁠נוּ וְ⁠נָתַ֥תָּה לָּ֛⁠נוּ פְּלֵיטָ֖ה כָּ⁠זֹֽאת׃","wĕ⁠ʼaֽẖàréy֙ ká̇l-ha⁠bá֣̇ʼ ʻálé֔y⁠nẇ bĕ̇⁠maʻàşé̂֨y⁠nẇ֙ há⁠ráʻi֔ym ẇ⁠bĕ⁠ʼaşĕ̌máţé֖⁠nẇ ha⁠gĕ̇dòlá֑h ki֣̇y ׀ ʼaţá֣̇h ʼèlòhé֗y⁠nẇ ẖáşâ֤kĕţáֽ̇ lĕ⁠ma֨tá̇h֙ méֽ⁠ʻàwֺné֔⁠nẇ wĕ⁠náţa֥ţá̇h lá֛̇⁠nẇ pĕ̇léytá֖h ká̇⁠zòֽʼţ׃"],[9,14,"הֲ⁠נָשׁוּב֙ לְ⁠הָפֵ֣ר מִצְוֺתֶ֔י⁠ךָ וּ֨⁠לְ⁠הִתְחַתֵּ֔ן בְּ⁠עַמֵּ֥י הַ⁠תֹּעֵב֖וֹת הָ⁠אֵ֑לֶּה הֲ⁠ל֤וֹא תֶֽאֱנַף־בָּ֨⁠נוּ֙ עַד־כַּלֵּ֔ה לְ⁠אֵ֥ין שְׁאֵרִ֖ית וּ⁠פְלֵיטָֽה׃פ","hà⁠náş̌ẇb֙ lĕ⁠hápé֣r miẕĕwֺţe֔y⁠ká ẇ֨⁠lĕ⁠hiţĕẖaţé̇֔n bĕ̇⁠ʻamé֥̇y ha⁠ţò̇ʻéb֖wòţ há⁠ʼé֑lėh hà⁠l֤wòʼ ţeֽʼènap-bá̇֨⁠nẇ֙ ʻad-kȧlé̇֔h lĕ⁠ʼé֥yn şĕ̌ʼéri֖yţ ẇ⁠pĕléytáֽh׃p"],[9,15,"יְהוָ֞ה אֱלֹהֵ֤י יִשְׂרָאֵל֙ צַדִּ֣יק אַ֔תָּה כִּֽי־נִשְׁאַ֥רְנוּ פְלֵיטָ֖ה כְּ⁠הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה הִנְ⁠נ֤וּ לְ⁠פָנֶ֨י⁠ךָ֙ בְּ⁠אַשְׁמָתֵ֔י⁠נוּ כִּ֣י אֵ֥ין לַ⁠עֲמ֛וֹד לְ⁠פָנֶ֖י⁠ךָ עַל־זֹֽאת׃פ","yĕhwá֞h ʼèlòhé֤y yişĕ̂ráʼél֙ ẕadi֣̇yq ʼa֔ţá̇h kiֽ̇y-nişĕ̌ʼa֥rĕnẇ pĕléytá֖h kĕ̇⁠ha⁠ẏ֣wòm ha⁠zė֑h hinĕ⁠n֤ẇ lĕ⁠páne֨y⁠ká֙ bĕ̇⁠ʼaşĕ̌máţé֔y⁠nẇ ki֣̇y ʼé֥yn la⁠ʻàm֛wòd lĕ⁠páne֖y⁠ká ʻal-zòֽʼţ׃p"],[10,1,"וּ⁠כְ⁠הִתְפַּלֵּ֤ל עֶזְרָא֙ וּ⁠כְ֨⁠הִתְוַדֹּת֔⁠וֹ בֹּכֶה֙ וּ⁠מִתְנַפֵּ֔ל לִ⁠פְנֵ֖י בֵּ֣ית הָ⁠אֱלֹהִ֑ים נִקְבְּצוּ֩ אֵלָ֨י⁠ו מִ⁠יִּשְׂרָאֵ֜ל קָהָ֣ל רַב־מְאֹ֗ד אֲנָשִׁ֤ים וְ⁠נָשִׁים֙ וִֽ⁠ילָדִ֔ים כִּֽי־בָכ֥וּ הָ⁠עָ֖ם הַרְבֵּה־בֶֽכֶה׃ס","ẇ⁠kĕ⁠hiţĕpȧlé֤̇l ʻezĕráʼ֙ ẇ⁠kĕ֨⁠hiţĕwadò̇ţ֔⁠wò bò̇keh֙ ẇ⁠miţĕnapé̇֔l li⁠pĕné֖y bé֣̇yţ há⁠ʼèlòhi֑ym niqĕbĕ̇ẕẇ֩ ʼélá֨y⁠w mi⁠yi̇şĕ̂ráʼé֜l qáhá֣l rab-mĕʼò֗d ʼànáşǐ֤ym wĕ⁠náşǐym֙ wiֽ⁠yládi֔ym kiֽ̇y-bák֥ẇ há⁠ʻá֖m harĕbé̇h-beֽkeh׃s"],[10,2,"וַ⁠יַּעַן֩ שְׁכַנְיָ֨ה בֶן־יְחִיאֵ֜ל מִ⁠בְּנֵ֤י עולם וַ⁠יֹּ֣אמֶר לְ⁠עֶזְרָ֔א אֲנַ֨חְנוּ֙ מָעַ֣לְנוּ בֵ⁠אלֹהֵ֔י⁠נוּ וַ⁠נֹּ֛שֶׁב נָשִׁ֥ים נָכְרִיּ֖וֹת מֵ⁠עַמֵּ֣י הָ⁠אָ֑רֶץ וְ⁠עַתָּ֛ה יֵשׁ־מִקְוֶ֥ה לְ⁠יִשְׂרָאֵ֖ל עַל־זֹֽאת׃","wa⁠yȧʻan֩ şĕ̌kanĕyá֨h ben-yĕẖiyʼé֜l mi⁠bĕ̇né֤y ʻwlm wa⁠yò֣̇ʼmer lĕ⁠ʻezĕrá֔ʼ ʼàna֨ẖĕnẇ֙ máʻa֣lĕnẇ bé⁠ʼlòhé֔y⁠nẇ wa⁠nò֛̇şěb náşǐ֥ym nákĕriẏ֖wòţ mé⁠ʻamé֣̇y há⁠ʼá֑reẕ wĕ⁠ʻaţá֛̇h yéş̌-miqĕwe֥h lĕ⁠yişĕ̂ráʼé֖l ʻal-zòֽʼţ׃"],[10,3,"וְ⁠עַתָּ֣ה נִֽכְרָת־בְּרִ֣ית לֵ֠⁠אלֹהֵי⁠נוּ לְ⁠הוֹצִ֨יא כָל־נָשִׁ֜ים וְ⁠הַ⁠נּוֹלָ֤ד מֵ⁠הֶם֙ בַּ⁠עֲצַ֣ת אֲדֹנָ֔⁠י וְ⁠הַ⁠חֲרֵדִ֖ים בְּ⁠מִצְוַ֣ת אֱלֹהֵ֑י⁠נוּ וְ⁠כַ⁠תּוֹרָ֖ה יֵעָשֶֽׂה׃","wĕ⁠ʻaţá֣̇h niֽkĕráţ-bĕ̇ri֣yţ lé֠⁠ʼlòhéy⁠nẇ lĕ⁠hwòẕi֨yʼ kál-náşǐ֜ym wĕ⁠ha⁠ṅwòlá֤d mé⁠hem֙ bȧ⁠ʻàẕa֣ţ ʼàdòná֔⁠y wĕ⁠ha⁠ẖàrédi֖ym bĕ̇⁠miẕĕwa֣ţ ʼèlòhé֑y⁠nẇ wĕ⁠ka⁠ţ̇wòrá֖h yéʻáşêֽh׃"],[10,4,"ק֛וּם כִּֽי־עָלֶ֥י⁠ךָ הַ⁠דָּבָ֖ר וַ⁠אֲנַ֣חְנוּ עִמָּ֑⁠ךְ חֲזַ֖ק וַ⁠עֲשֵֽׂה׃פ","q֛ẇm kiֽ̇y-ʻále֥y⁠ká ha⁠dá̇bá֖r wa⁠ʼàna֣ẖĕnẇ ʻimá֑̇⁠kĕ ẖàza֖q wa⁠ʻàşéֽ̂h׃p"],[10,5,"וַ⁠יָּ֣קָם עֶזְרָ֡א וַ⁠יַּשְׁבַּ֣ע אֶת־שָׂרֵי֩ הַ⁠כֹּהֲנִ֨ים הַ⁠לְוִיִּ֜ם וְ⁠כָל־יִשְׂרָאֵ֗ל לַ⁠עֲשׂ֛וֹת כַּ⁠דָּבָ֥ר הַ⁠זֶּ֖ה וַ⁠יִּשָּׁבֵֽעוּ׃","wa⁠yá֣̇qám ʻezĕrá֡ʼ wa⁠yȧşĕ̌bȧ֣ʻ ʼeţ-şá̂réy֩ ha⁠kò̇hàni֨ym ha⁠lĕwiyi̇֜m wĕ⁠kál-yişĕ̂ráʼé֗l la⁠ʻàş֛̂wòţ kȧ⁠dá̇bá֥r ha⁠zė֖h wa⁠yi̇şá̇̌béֽʻẇ׃"],[10,6,"וַ⁠יָּ֣קָם עֶזְרָ֗א מִ⁠לִּ⁠פְנֵי֙ בֵּ֣ית הָֽ⁠אֱלֹהִ֔ים וַ⁠יֵּ֕לֶךְ אֶל־לִשְׁכַּ֖ת יְהוֹחָנָ֣ן בֶּן־אֶלְיָשִׁ֑יב וַ⁠יֵּ֣לֶךְ שָׁ֗ם לֶ֤חֶם לֹֽא־אָכַל֙ וּ⁠מַ֣יִם לֹֽא־שָׁתָ֔ה כִּ֥י מִתְאַבֵּ֖ל עַל־מַ֥עַל הַ⁠גּוֹלָֽה׃ס","wa⁠yá֣̇qám ʻezĕrá֗ʼ mi⁠li̇⁠pĕnéy֙ bé֣̇yţ háֽ⁠ʼèlòhi֔ym wa⁠yé̇֕lekĕ ʼel-lişĕ̌kȧ֖ţ yĕhwòẖáná֣n bėn-ʼelĕyáşǐ֑yb wa⁠yé֣̇lekĕ şá̌֗m le֤ẖem lòֽʼ-ʼákal֙ ẇ⁠ma֣yim lòֽʼ-şá̌ţá֔h ki֥̇y miţĕʼabé֖̇l ʻal-ma֥ʻal ha⁠ġwòláֽh׃s"],[10,7,"וַ⁠יַּעֲבִ֨ירוּ ק֜וֹל בִּ⁠יהוּדָ֣ה וִ⁠ירֽוּשָׁלִַ֗ם לְ⁠כֹל֙ בְּנֵ֣י הַ⁠גּוֹלָ֔ה לְ⁠הִקָּבֵ֖ץ יְרוּשָׁלִָֽם׃","wa⁠yȧʻàbi֨yrẇ q֜wòl bi̇⁠yhẇdá֣h wi⁠yrֽẇşá̌lia֗m lĕ⁠kòl֙ bĕ̇né֣y ha⁠ġwòlá֔h lĕ⁠hiqá̇bé֖ẕ yĕrẇşá̌liáֽm׃"],[10,8,"וְ⁠כֹל֩ אֲשֶׁ֨ר לֹֽא־יָב֜וֹא לִ⁠שְׁלֹ֣שֶׁת הַ⁠יָּמִ֗ים כַּ⁠עֲצַ֤ת הַ⁠שָּׂרִים֙ וְ⁠הַ⁠זְּקֵנִ֔ים יָחֳרַ֖ם כָּל־רְכוּשׁ֑⁠וֹ וְ⁠ה֥וּא יִבָּדֵ֖ל מִ⁠קְּהַ֥ל הַ⁠גּוֹלָֽה׃ס","wĕ⁠kòl֩ ʼàşě֨r lòֽʼ-yáb֜wòʼ li⁠şĕ̌lò֣şěţ ha⁠yá̇mi֗ym kȧ⁠ʻàẕa֤ţ ha⁠şá̇̂riym֙ wĕ⁠ha⁠zĕ̇qéni֔ym yáẖora֖m ká̇l-rĕkẇş֑̌⁠wò wĕ⁠h֥ẇʼ yibá̇dé֖l mi⁠qĕ̇ha֥l ha⁠ġwòláֽh׃s"],[10,9,"וַ⁠יִּקָּבְצ֣וּ כָל־אַנְשֵֽׁי־יְהוּדָה֩ וּ⁠בִנְיָמִ֨ן ׀ יְרוּשָׁלִַ֜ם לִ⁠שְׁלֹ֣שֶׁת הַ⁠יָּמִ֗ים ה֛וּא חֹ֥דֶשׁ הַ⁠תְּשִׁיעִ֖י בְּ⁠עֶשְׂרִ֣ים בַּ⁠חֹ֑דֶשׁ וַ⁠יֵּשְׁב֣וּ כָל־הָ⁠עָ֗ם בִּ⁠רְחוֹב֙ בֵּ֣ית הָ⁠אֱלֹהִ֔ים מַרְעִידִ֥ים עַל־הַ⁠דָּבָ֖ר וּ⁠מֵ⁠הַ⁠גְּשָׁמִֽים׃פ","wa⁠yi̇qá̇bĕẕ֣ẇ kál-ʼanĕşéֽ̌y-yĕhẇdáh֩ ẇ⁠binĕyámi֨n ׀ yĕrẇşá̌lia֜m li⁠şĕ̌lò֣şěţ ha⁠yá̇mi֗ym h֛ẇʼ ẖò֥deş̌ ha⁠ţĕ̇şǐyʻi֖y bĕ̇⁠ʻeşĕ̂ri֣ym bȧ⁠ẖò֑deş̌ wa⁠yé̇şĕ̌b֣ẇ kál-há⁠ʻá֗m bi̇⁠rĕẖwòb֙ bé֣̇yţ há⁠ʼèlòhi֔ym marĕʻiydi֥ym ʻal-ha⁠dá̇bá֖r ẇ⁠mé⁠ha⁠gĕ̇şá̌miֽym׃p"],[10,10,"וַ⁠יָּ֨קָם עֶזְרָ֤א הַ⁠כֹּהֵן֙ וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֔ם אַתֶּ֣ם מְעַלְתֶּ֔ם וַ⁠תֹּשִׁ֖יבוּ נָשִׁ֣ים נָכְרִיּ֑וֹת לְ⁠הוֹסִ֖יף עַל־אַשְׁמַ֥ת יִשְׂרָאֵֽל׃","wa⁠yá̇֨qám ʻezĕrá֤ʼ ha⁠kò̇hén֙ wa⁠yò֣̇ʼmer ʼàlé⁠he֔m ʼaţė֣m mĕʻalĕţė֔m wa⁠ţò̇şǐ֖ybẇ náşǐ֣ym nákĕriẏ֑wòţ lĕ⁠hwòsi֖yp ʻal-ʼaşĕ̌ma֥ţ yişĕ̂ráʼéֽl׃"],[10,11,"וְ⁠עַתָּ֗ה תְּנ֥וּ תוֹדָ֛ה לַ⁠יהוָ֥ה אֱלֹהֵֽי־אֲבֹתֵי⁠כֶ֖ם וַ⁠עֲשׂ֣וּ רְצוֹנ֑⁠וֹ וְ⁠הִבָּֽדְלוּ֙ מֵ⁠עַמֵּ֣י הָ⁠אָ֔רֶץ וּ⁠מִן־הַ⁠נָּשִׁ֖ים הַ⁠נָּכְרִיּֽוֹת׃","wĕ⁠ʻaţá̇֗h ţĕ̇n֥ẇ ţwòdá֛h la⁠yhwá֥h ʼèlòhéֽy-ʼàbòţéy⁠ke֖m wa⁠ʻàş֣̂ẇ rĕẕwòn֑⁠wò wĕ⁠hibáֽ̇dĕlẇ֙ mé⁠ʻamé֣̇y há⁠ʼá֔reẕ ẇ⁠min-ha⁠ná̇şǐ֖ym ha⁠ná̇kĕriẏֽwòţ׃"],[10,12,"וַ⁠יַּֽעְנ֧וּ כָֽל־הַ⁠קָּהָ֛ל וַ⁠יֹּאמְר֖וּ ק֣וֹל גָּד֑וֹל כֵּ֛ן כ⁠דברי⁠ך עָלֵ֖י⁠נוּ לַ⁠עֲשֽׂוֹת׃","wa⁠yȧֽʻĕn֧ẇ káֽl-ha⁠qá̇há֛l wa⁠yò̇ʼmĕr֖ẇ q֣wòl gá̇d֑wòl ké֛̇n k⁠dbry⁠k ʻálé֖y⁠nẇ la⁠ʻàşֽ̂wòţ׃"],[10,13,"אֲבָ֞ל הָ⁠עָ֥ם רָב֙ וְ⁠הָ⁠עֵ֣ת גְּשָׁמִ֔ים וְ⁠אֵ֥ין כֹּ֖חַ לַ⁠עֲמ֣וֹד בַּ⁠ח֑וּץ וְ⁠הַ⁠מְּלָאכָ֗ה לֹֽא־לְ⁠י֤וֹם אֶחָד֙ וְ⁠לֹ֣א לִ⁠שְׁנַ֔יִם כִּֽי־הִרְבִּ֥ינוּ לִ⁠פְשֹׁ֖עַ בַּ⁠דָּבָ֥ר הַ⁠זֶּֽה׃","ʼàbá֞l há⁠ʻá֥m ráb֙ wĕ⁠há⁠ʻé֣ţ gĕ̇şá̌mi֔ym wĕ⁠ʼé֥yn kò֖̇ẖa la⁠ʻàm֣wòd bȧ⁠ẖ֑ẇẕ wĕ⁠ha⁠mĕ̇láʼká֗h lòֽʼ-lĕ⁠y֤wòm ʼeẖád֙ wĕ⁠lò֣ʼ li⁠şĕ̌na֔yim kiֽ̇y-hirĕbi֥̇ynẇ li⁠pĕşò֖̌ʻa bȧ⁠dá̇bá֥r ha⁠zėֽh׃"],[10,14,"יַֽעֲמְדוּ־נָ֣א שָׂ֠רֵי⁠נוּ לְֽ⁠כָל־הַ⁠קָּהָ֞ל וְ⁠כֹ֣ל ׀ אֲשֶׁ֣ר בֶּ⁠עָרֵ֗י⁠נוּ הַ⁠הֹשִׁ֞יב נָשִׁ֤ים נָכְרִיּוֹת֙ יָבֹא֙ לְ⁠עִתִּ֣ים מְזֻמָּנִ֔ים וְ⁠עִמָּ⁠הֶ֛ם זִקְנֵי־עִ֥יר וָ⁠עִ֖יר וְ⁠שֹׁפְטֶ֑י⁠הָ עַ֠ד לְ⁠הָשִׁ֞יב חֲר֤וֹן אַף־אֱלֹהֵ֨י⁠נוּ֙ מִמֶּ֔⁠נּוּ עַ֖ד לַ⁠דָּבָ֥ר הַ⁠זֶּֽה׃פ","yaֽʻàmĕdẇ-ná֣ʼ şá̂֠réy⁠nẇ lĕֽ⁠kál-ha⁠qá̇há֞l wĕ⁠kò֣l ׀ ʼàşě֣r bė⁠ʻáré֗y⁠nẇ ha⁠hòşǐ֞yb náşǐ֤ym nákĕriẏwòţ֙ yábòʼ֙ lĕ⁠ʻiţi֣̇ym mĕzumá̇ni֔ym wĕ⁠ʻimá̇⁠he֛m ziqĕnéy-ʻi֥yr wá⁠ʻi֖yr wĕ⁠şò̌pĕte֑y⁠há ʻa֠d lĕ⁠háşǐ֞yb ẖàr֤wòn ʼap-ʼèlòhé֨y⁠nẇ֙ mimė֔⁠ṅẇ ʻa֖d la⁠dá̇bá֥r ha⁠zėֽh׃p"],[10,15,"אַ֣ךְ יוֹנָתָ֧ן בֶּן־עֲשָׂהאֵ֛ל וְ⁠יַחְזְיָ֥ה בֶן־תִּקְוָ֖ה עָמְד֣וּ עַל־זֹ֑את וּ⁠מְשֻׁלָּ֛ם וְ⁠שַׁבְּתַ֥י הַ⁠לֵּוִ֖י עֲזָרֻֽ⁠ם׃","ʼa֣kĕ ywònáţá֧n bėn-ʻàşá̂hʼé֛l wĕ⁠yaẖĕzĕyá֥h ben-ţi̇qĕwá֖h ʻámĕd֣ẇ ʻal-zò֑ʼţ ẇ⁠mĕşǔlá֛̇m wĕ⁠şǎbĕ̇ţa֥y ha⁠lé̇wi֖y ʻàzáruֽ⁠m׃"],[10,16,"וַ⁠יַּֽעֲשׂוּ־כֵן֮ בְּנֵ֣י הַ⁠גּוֹלָה֒ וַ⁠יִּבָּדְלוּ֩ עֶזְרָ֨א הַ⁠כֹּהֵ֜ן אֲנָשִׁ֨ים רָאשֵׁ֧י הָ⁠אָב֛וֹת לְ⁠בֵ֥ית אֲבֹתָ֖⁠ם וְ⁠כֻלָּ֣⁠ם בְּ⁠שֵׁמ֑וֹת וַ⁠יֵּשְׁב֗וּ בְּ⁠י֤וֹם אֶחָד֙ לַ⁠חֹ֣דֶשׁ הָ⁠עֲשִׂירִ֔י לְ⁠דַרְי֖וֹשׁ הַ⁠דָּבָֽר׃","wa⁠ẏֽaʻàş̂ẇ-kén֮ bĕ̇né֣y ha⁠ġwòláh֒ wa⁠yi̇bá̇dĕlẇ֩ ʻezĕrá֨ʼ ha⁠kò̇hé֜n ʼànáşǐ֨ym ráʼşé֧̌y há⁠ʼáb֛wòţ lĕ⁠bé֥yţ ʼàbòţá֖⁠m wĕ⁠kulá֣̇⁠m bĕ̇⁠şé̌m֑wòţ wa⁠yé̇şĕ̌b֗ẇ bĕ̇⁠y֤wòm ʼeẖád֙ la⁠ẖò֣deş̌ há⁠ʻàşîyri֔y lĕ⁠darĕy֖wòş̌ ha⁠dá̇báֽr׃"],[10,17,"וַ⁠יְכַלּ֣וּ בַ⁠כֹּ֔ל אֲנָשִׁ֕ים הַ⁠הֹשִׁ֖יבוּ נָשִׁ֣ים נָכְרִיּ֑וֹת עַ֛ד י֥וֹם אֶחָ֖ד לַ⁠חֹ֥דֶשׁ הָ⁠רִאשֽׁוֹן׃פ","wa⁠yĕkal֣̇ẇ ba⁠kò̇֔l ʼànáşǐ֕ym ha⁠hòşǐ֖ybẇ náşǐ֣ym nákĕriẏ֑wòţ ʻa֛d y֥wòm ʼeẖá֖d la⁠ẖò֥deş̌ há⁠riʼşֽ̌wòn׃p"],[10,18,"וַ⁠יִּמָּצֵא֙ מִ⁠בְּנֵ֣י הַ⁠כֹּהֲנִ֔ים אֲשֶׁ֥ר הֹשִׁ֖יבוּ נָשִׁ֣ים נָכְרִיּ֑וֹת מִ⁠בְּנֵ֨י יֵשׁ֤וּעַ בֶּן־יֽוֹצָדָק֙ וְ⁠אֶחָ֔י⁠ו מַֽעֲשֵׂיָה֙ וֶֽ⁠אֱלִיעֶ֔זֶר וְ⁠יָרִ֖יב וּ⁠גְדַלְיָֽה׃","wa⁠yi̇má̇ẕéʼ֙ mi⁠bĕ̇né֣y ha⁠kò̇hàni֔ym ʼàşě֥r hòşǐ֖ybẇ náşǐ֣ym nákĕriẏ֑wòţ mi⁠bĕ̇né֨y yéş֤̌ẇʻa bėn-yֽwòẕádáq֙ wĕ⁠ʼeẖá֔y⁠w maֽʻàşé̂yáh֙ wֽe⁠ʼèliyʻe֔zer wĕ⁠yári֖yb ẇ⁠gĕdalĕyáֽh׃"],[10,19,"וַ⁠יִּתְּנ֥וּ יָדָ֖⁠ם לְ⁠הוֹצִ֣יא נְשֵׁי⁠הֶ֑ם וַ⁠אֲשֵׁמִ֥ים אֵֽיל־צֹ֖אן עַל־אַשְׁמָתָֽ⁠ם׃ס","wa⁠yi̇ţĕ̇n֥ẇ yádá֖⁠m lĕ⁠hwòẕi֣yʼ nĕşé̌y⁠he֑m wa⁠ʼàşé̌mi֥ym ʼéֽyl-ẕò֖ʼn ʻal-ʼaşĕ̌máţáֽ⁠m׃s"],[10,20,"וּ⁠מִ⁠בְּנֵ֣י אִמֵּ֔ר חֲנָ֖נִי וּ⁠זְבַדְיָֽה׃ס","ẇ⁠mi⁠bĕ̇né֣y ʼimé̇֔r ẖàná֖niy ẇ⁠zĕbadĕyáֽh׃s"],[10,21,"וּ⁠מִ⁠בְּנֵ֖י חָרִ֑ם מַעֲשֵׂיָ֤ה וְ⁠אֵֽלִיָּה֙ וּֽ⁠שְׁמַֽעְיָ֔ה וִ⁠יחִיאֵ֖ל וְ⁠עֻזִיָּֽה׃","ẇ⁠mi⁠bĕ̇né֖y ẖári֑m maʻàşé̂yá֤h wĕ⁠ʼéֽliyá̇h֙ ẇֽ⁠şĕ̌maֽʻĕyá֔h wi⁠yẖiyʼé֖l wĕ⁠ʻuziyáֽ̇h׃"],[10,22,"וּ⁠מִ⁠בְּנֵ֖י פַּשְׁח֑וּר אֶלְיוֹעֵינַ֤י מַֽעֲשֵׂיָה֙ יִשְׁמָעֵ֣אל נְתַנְאֵ֔ל יוֹזָבָ֖ד וְ⁠אֶלְעָשָֽׂה׃ס","ẇ⁠mi⁠bĕ̇né֖y pȧşĕ̌ẖ֑ẇr ʼelĕywòʻéyna֤y maֽʻàşé̂yáh֙ yişĕ̌máʻé֣ʼl nĕţanĕʼé֔l ywòzábá֖d wĕ⁠ʼelĕʻáşáֽ̂h׃s"],[10,23,"וּ⁠מִֽן־הַ⁠לְוִיִּ֑ם יוֹזָבָ֣ד וְ⁠שִׁמְעִ֗י וְ⁠קֵֽלָיָה֙ ה֣וּא קְלִיטָ֔א פְּתַֽחְיָ֥ה יְהוּדָ֖ה וֶ⁠אֱלִיעֶֽזֶר׃ס","ẇ⁠miֽn-ha⁠lĕwiyi֑̇m ywòzábá֣d wĕ⁠şǐmĕʻi֗y wĕ⁠qéֽláyáh֙ h֣ẇʼ qĕliytá֔ʼ pĕ̇ţaֽẖĕyá֥h yĕhẇdá֖h we⁠ʼèliyʻeֽzer׃s"],[10,24,"וּ⁠מִן־הַ⁠מְשֹׁרְרִ֖ים אֶלְיָשִׁ֑יב וּ⁠מִן־הַ⁠שֹּׁ֣עֲרִ֔ים שַׁלֻּ֥ם וָ⁠טֶ֖לֶם וְ⁠אוּרִֽי׃ס","ẇ⁠min-ha⁠mĕşò̌rĕri֖ym ʼelĕyáşǐ֑yb ẇ⁠min-ha⁠şò֣̇̌ʻàri֔ym şǎlu֥̇m wá⁠te֖lem wĕ⁠ʼẇriֽy׃s"],[10,25,"וּ⁠מִֽ⁠יִּשְׂרָאֵ֑ל מִ⁠בְּנֵ֣י פַרְעֹ֡שׁ רַ֠מְיָה וְ⁠יִזִּיָּ֤ה וּ⁠מַלְכִּיָּה֙ וּ⁠מִיָּמִ֣ן וְ⁠אֶלְעָזָ֔ר וּ⁠מַלְכִּיָּ֖ה וּ⁠בְנָיָֽה׃ס","ẇ⁠miֽ⁠yi̇şĕ̂ráʼé֑l mi⁠bĕ̇né֣y parĕʻò֡ş̌ ra֠mĕyáh wĕ⁠yizi̇yá֤̇h ẇ⁠malĕki̇yá̇h֙ ẇ⁠miyá̇mi֣n wĕ⁠ʼelĕʻázá֔r ẇ⁠malĕki̇yá֖̇h ẇ⁠bĕnáyáֽh׃s"],[10,26,"וּ⁠מִ⁠בְּנֵ֖י עֵילָ֑ם מַתַּנְיָ֤ה זְכַרְיָה֙ וִ⁠יחִיאֵ֣ל וְ⁠עַבְדִּ֔י וִ⁠ירֵמ֖וֹת וְ⁠אֵלִיָּֽה׃ס","ẇ⁠mi⁠bĕ̇né֖y ʻéylá֑m maţȧnĕyá֤h zĕkarĕyáh֙ wi⁠yẖiyʼé֣l wĕ⁠ʻabĕdi̇֔y wi⁠yrém֖wòţ wĕ⁠ʼéliyáֽ̇h׃s"],[10,27,"וּ⁠מִ⁠בְּנֵ֖י זַתּ֑וּא אֶלְיוֹעֵנַ֤י אֶלְיָשִׁיב֙ מַתַּנְיָ֣ה וִֽ⁠ירֵמ֔וֹת וְ⁠זָבָ֖ד וַ⁠עֲזִיזָֽא׃ס","ẇ⁠mi⁠bĕ̇né֖y zaţ֑̇ẇʼ ʼelĕywòʻéna֤y ʼelĕyáşǐyb֙ maţȧnĕyá֣h wiֽ⁠yrém֔wòţ wĕ⁠zábá֖d wa⁠ʻàziyzáֽʼ׃s"],[10,28,"וּ⁠מִ⁠בְּנֵ֖י בֵּבָ֑י יְהוֹחָנָ֥ן חֲנַנְיָ֖ה זַבַּ֥י עַתְלָֽי׃ס","ẇ⁠mi⁠bĕ̇né֖y bé̇bá֑y yĕhwòẖáná֥n ẖànanĕyá֖h zabȧ֥y ʻaţĕláֽy׃s"],[10,29,"וּ⁠מִ⁠בְּנֵ֖י בָּנִ֑י מְשֻׁלָּ֤ם מַלּוּךְ֙ וַ⁠עֲדָיָ֔ה יָשׁ֖וּב וּ⁠שְׁאָ֥ל ירמות׃ס","ẇ⁠mi⁠bĕ̇né֖y bá̇ni֑y mĕşǔlá֤̇m mal̇ẇkĕ֙ wa⁠ʻàdáyá֔h yáş֖̌ẇb ẇ⁠şĕ̌ʼá֥l yrmwţ׃s"],[10,30,"וּ⁠מִ⁠בְּנֵ֛י פַּחַ֥ת מוֹאָ֖ב עַדְנָ֣א וּ⁠כְלָ֑ל בְּנָיָ֤ה מַעֲשֵׂיָה֙ מַתַּנְיָ֣ה בְצַלְאֵ֔ל וּ⁠בִנּ֖וּי וּ⁠מְנַשֶּֽׁה׃ס","ẇ⁠mi⁠bĕ̇né֛y pȧẖa֥ţ mwòʼá֖b ʻadĕná֣ʼ ẇ⁠kĕlá֑l bĕ̇náyá֤h maʻàşé̂yáh֙ maţȧnĕyá֣h bĕẕalĕʼé֔l ẇ⁠biṅ֖ẇy ẇ⁠mĕnaşėֽ̌h׃s"],[10,31,"וּ⁠בְנֵ֖י חָרִ֑ם אֱלִיעֶ֧זֶר יִשִּׁיָּ֛ה מַלְכִּיָּ֖ה שְׁמַֽעְיָ֥ה שִׁמְעֽוֹן׃","ẇ⁠bĕné֖y ẖári֑m ʼèliyʻe֧zer yişi̇̌yá֛̇h malĕki̇yá֖̇h şĕ̌maֽʻĕyá֥h şǐmĕʻֽwòn׃"],[10,32,"בְּנְיָמִ֥ן מַלּ֖וּךְ שְׁמַרְיָֽה׃ס","bĕ̇nĕyámi֥n mal֖̇ẇkĕ şĕ̌marĕyáֽh׃s"],[10,33,"מִ⁠בְּנֵ֖י חָשֻׁ֑ם מַתְּנַ֤י מַתַּתָּה֙ זָבָ֣ד אֱלִיפֶ֔לֶט יְרֵמַ֥י מְנַשֶּׁ֖ה שִׁמְעִֽי׃ס","mi⁠bĕ̇né֖y ẖáşǔ֑m maţĕ̇na֤y maţȧţá̇h֙ zábá֣d ʼèliype֔let yĕréma֥y mĕnaşė֖̌h şǐmĕʻiֽy׃s"],[10,34,"מִ⁠בְּנֵ֣י בָנִ֔י מַעֲדַ֥י עַמְרָ֖ם וְ⁠אוּאֵֽל׃ס","mi⁠bĕ̇né֣y báni֔y maʻàda֥y ʻamĕrá֖m wĕ⁠ʼẇʼéֽl׃s"],[10,35,"בְּנָיָ֥ה בֵדְיָ֖ה כלהי׃","bĕ̇náyá֥h bédĕyá֖h klhy׃"],[10,36,"וַנְיָ֥ה מְרֵמ֖וֹת אֶלְיָשִֽׁיב׃","wanĕyá֥h mĕrém֖wòţ ʼelĕyáşǐֽyb׃"],[10,37,"מַתַּנְיָ֥ה מַתְּנַ֖י ו⁠יעשו׃","maţȧnĕyá֥h maţĕ̇na֖y w⁠yʻşw׃"],[10,38,"וּ⁠בָנִ֥י וּ⁠בִנּ֖וּי שִׁמְעִֽי׃","ẇ⁠báni֥y ẇ⁠biṅ֖ẇy şǐmĕʻiֽy׃"],[10,39,"וְ⁠שֶֽׁלֶמְיָ֥ה וְ⁠נָתָ֖ן וַ⁠עֲדָיָֽה׃","wĕ⁠şěֽlemĕyá֥h wĕ⁠náţá֖n wa⁠ʻàdáyáֽh׃"],[10,40,"מַכְנַדְבַ֥י שָׁשַׁ֖י שָׁרָֽי׃","makĕnadĕba֥y şá̌şǎ֖y şá̌ráֽy׃"],[10,41,"עֲזַרְאֵ֥ל וְ⁠שֶׁלֶמְיָ֖הוּ שְׁמַרְיָֽה׃","ʻàzarĕʼé֥l wĕ⁠şělemĕyá֖hẇ şĕ̌marĕyáֽh׃"],[10,42,"שַׁלּ֥וּם אֲמַרְיָ֖ה יוֹסֵֽף׃ס","şǎl֥̇ẇm ʼàmarĕyá֖h ywòséֽp׃s"],[10,43,"מִ⁠בְּנֵ֖י נְב֑וֹ יְעִיאֵ֤ל מַתִּתְיָה֙ זָבָ֣ד זְבִינָ֔א ידו וְ⁠יוֹאֵ֖ל בְּנָיָֽה׃","mi⁠bĕ̇né֖y nĕb֑wò yĕʻiyʼé֤l maţi̇ţĕyáh֙ zábá֣d zĕbiyná֔ʼ ydw wĕ⁠ywòʼé֖l bĕ̇náyáֽh׃"],[10,44,"כָּל־אֵ֕לֶּה נשא⁠י נָשִׁ֣ים נָכְרִיּ֑וֹת וְ⁠יֵ֣שׁ מֵ⁠הֶ֣ם נָשִׁ֔ים וַ⁠יָּשִׂ֖ימוּ בָּנִֽים׃פ","ká̇l-ʼé֕lėh nşʼ⁠y náşǐ֣ym nákĕriẏ֑wòţ wĕ⁠yé֣ş̌ mé⁠he֣m náşǐ֔ym wa⁠yá̇şî֖ymẇ bá̇niֽym׃p"]]}};